INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ee8f36-27b5-4aec-b0b9-1ca8a4160b56', '贈夫詩三首 三', '贈夫诗三首 三', 'b91bb430-9fee-4126-9305-087555bf9a47', '唐', '["有意懷男女，無情亦任君。","欲知腸斷處，明月照孤墳。"]', '["有意懷男女，無情亦任君。","欲知腸斷处，明月照孤墳。"]', '诗', 'shi', '', NULL, '贈夫詩三首 三 孔氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('546705a1-a339-48d2-92fc-575da76445c3', '荅夫詩二首 一', '荅夫诗二首 一', '272fe4a0-a144-4a9f-a43f-5c32381bbdea', '唐', '["不分殊幽顯，那堪異古今。","陰陽徒自隔，聚散兩難心。"]', '["不分殊幽显，那堪異古今。","陰陽徒自隔，聚散兩难心。"]', '诗', 'shi', '', NULL, '荅夫詩二首 一 唐晅妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('266d0111-59ea-45dc-8207-43b7313e1255', '荅夫詩二首 二', '荅夫诗二首 二', '272fe4a0-a144-4a9f-a43f-5c32381bbdea', '唐', '["蘭階兔月斜，銀燭半含花。","自憐長夜客，泉路以爲家。"]', '["蘭階兔月斜，銀燭半含花。","自怜长夜客，泉路以爲家。"]', '诗', 'shi', '', NULL, '荅夫詩二首 二 唐晅妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca49463b-7d9c-4f80-a624-034c826d2eb2', '唐晅悼妻詩 一', '唐晅悼妻诗 一', '272fe4a0-a144-4a9f-a43f-5c32381bbdea', '唐', '["寢室悲長簟，妝樓泣鏡臺。","獨悲桃李節，不共夜泉開。","魂兮若有感，髣髴夢中來。"]', '["寢室悲长簟，妝楼泣镜台。","独悲桃李節，不共夜泉开。","魂兮若有感，髣髴梦中来。"]', '诗', 'shi', '', NULL, '唐晅悼妻詩 一 唐晅妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb77a71d-47d1-468a-938d-090b3e178130', '唐晅悼妻詩 二', '唐晅悼妻诗 二', '272fe4a0-a144-4a9f-a43f-5c32381bbdea', '唐', '["常時華堂靜，笑語度更籌。","恍惚人事改，冥寞委荒丘。","陽原歌薤露，陰壑惜藏舟。","清夜妝臺月，空想畫眉愁。"]', '["常时华堂静，笑語度更籌。","恍惚人事改，冥寞委荒丘。","陽原歌薤露，陰壑惜藏舟。","清夜妝台月，空想畫眉愁。"]', '诗', 'shi', '', NULL, '唐晅悼妻詩 二 唐晅妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1c964dec-38ac-45db-b886-30f6de4ade44', '贈妻詩', '贈妻诗', '272fe4a0-a144-4a9f-a43f-5c32381bbdea', '唐', '["嶧陽桐半死，延津劒一沈。","如何宿昔內，空負百年心。"]', '["嶧陽桐半死，延津劒一沈。","如何宿昔內，空負百年心。"]', '诗', 'shi', '', NULL, '贈妻詩 唐晅妻張氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36d3d277-5b20-4780-b9bc-23e30308f7cf', '贈姊', '贈姊', '7b7f23cf-88c2-48fc-adda-457ff42b1f6d', '唐', '["修短各有分，浮華亦非真。","斷腸泉壤下，幽憂難具陳。","淒淒白楊風，日暮堪愁人。"]', '["修短各有分，浮华亦非真。","斷腸泉壤下，幽憂难具陳。","淒淒白楊风，日暮堪愁人。"]', '诗', 'shi', '', NULL, '贈姊 韋璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e058769a-c7eb-450c-8058-1ecfd28acc9e', '贈夫二首 一', '贈夫二首 一', '7b7f23cf-88c2-48fc-adda-457ff42b1f6d', '唐', '["不得長相守，青春夭蕣華。","舊遊今永已，泉路却爲家。"]', '["不得长相守，青春夭蕣华。","旧游今永已，泉路却爲家。"]', '诗', 'shi', '', NULL, '贈夫二首 一 韋璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bc463c0c-a3b6-45c9-a948-fb26b62d09ef', '贈夫二首 二', '贈夫二首 二', '7b7f23cf-88c2-48fc-adda-457ff42b1f6d', '唐', '["早知離別切人心，悔作從來恩愛深。","黃泉冥寞雖長逝，白日屏帷還重尋。"]', '["早知離別切人心，悔作從来恩愛深。","黄泉冥寞雖长逝，白日屏帷還重尋。"]', '诗', 'shi', '', NULL, '贈夫二首 二 韋璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f5b6142a-c129-44de-962b-be0aa3b34cb6', '贈嫂', '贈嫂', '7b7f23cf-88c2-48fc-adda-457ff42b1f6d', '唐', '["赤心用盡爲相知，慮後防前秖定疑。","案牘可申生節目，桃符雖聖欲何爲。"]', '["赤心用尽爲相知，慮後防前秖定疑。","案牘可申生節目，桃符雖聖欲何爲。"]', '诗', 'shi', '', NULL, '贈嫂 韋璜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6766b37d-23ee-41e7-8aa8-023dfe603107', '與獨孤穆冥會詩 一', '與独孤穆冥會诗 一', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["江都昔喪亂，闕下多搆兵。","豺虎恣吞噬，干戈日縱橫。","逆徒自外至，半夜開重城。","膏血浸宮殿，刀槍倚簷楹。","今知從逆者，廼是公與卿。","白刃汚黃屋，邦家遂因傾。","疾風知勁草，世亂識忠臣。","哀哀獨孤公，臨死乃結纓。","天地既板蕩，雲雷時未亨。","今者二百載，幽懷猶未平。","山河風月古，陵寢露煙青。","君子秉祖德，方垂忠烈名。","華軒一惠顧，土室以爲榮。","丈夫立志操，存沒感其情。","求義若可託，誰能抱幽貞。"]', '["江都昔喪亂，闕下多搆兵。","豺虎恣吞噬，干戈日縱橫。","逆徒自外至，半夜开重城。","膏血浸宮殿，刀槍倚簷楹。","今知從逆者，廼是公與卿。","白刃汚黄屋，邦家遂因傾。","疾风知勁草，世亂識忠臣。","哀哀独孤公，臨死乃結纓。","天地既板蕩，云雷时未亨。","今者二百載，幽懷猶未平。","山河风月古，陵寢露煙青。","君子秉祖德，方垂忠烈名。","华軒一惠顧，土室以爲榮。","丈夫立志操，存沒感其情。","求義若可託，誰能抱幽貞。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 一 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8b2f521-32da-41f6-ada6-59564d956334', '與獨孤穆冥會詩 二', '與独孤穆冥會诗 二', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["皇天昔降禍，隋室若綴旒。","患難在雙闕，干戈連九州。","出門皆凶豎，所向多逆謀。","白日忽然暮，頹波不可收。","望夷既結釁，宗社亦貽羞。","溫室兵始合，宮闈血已流。","憫哉吹簫子，悲啼下鳳樓。","霜刃徒見逼，玉笄不可求。","羅襦遺侍者，粉黛成仇讎。","邦國已淪覆，餘生誓不留。","英英將軍祖，獨以社稷憂。","丹血濺黼扆，豐肌染戈矛。","今來見禾黍，盡日悲宗周。","玉樹已寂寞，泉臺千萬秋。","感茲一顧重，願以死節酬。","幽顯儻不昧，終焉契綢繆。"]', '["皇天昔降禍，隋室若綴旒。","患难在雙闕，干戈連九州。","出门皆凶豎，所向多逆謀。","白日忽然暮，頹波不可收。","望夷既結釁，宗社亦貽羞。","溫室兵始合，宮闈血已流。","憫哉吹簫子，悲啼下鳳楼。","霜刃徒见逼，玉笄不可求。","羅襦遺侍者，粉黛成仇讎。","邦国已淪覆，餘生誓不留。","英英將軍祖，独以社稷憂。","丹血濺黼扆，豐肌染戈矛。","今来见禾黍，尽日悲宗周。","玉樹已寂寞，泉台千万秋。","感茲一顧重，願以死節酬。","幽显儻不昧，終焉契綢繆。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 二 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9459c13b-c3c0-4c7e-a151-dda5097025b1', '與獨孤穆冥會詩 三', '與独孤穆冥會诗 三', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["平陽縣中樹，久作廣陵塵。","不意何郎至，黃泉重見春。"]', '["平陽縣中樹，久作廣陵塵。","不意何郎至，黄泉重见春。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 三 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b109faf0-132a-4ae3-8851-c3f174bd3b82', '與獨孤穆冥會詩 四', '與独孤穆冥會诗 四', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["今閨久無主，羅袂坐生塵。","願作吹簫伴，同爲騎鳳人。"]', '["今閨久無主，羅袂坐生塵。","願作吹簫伴，同爲騎鳳人。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 四 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9302719-9cfa-41e2-aed9-5d2070972ea2', '與獨孤穆冥會詩 五', '與独孤穆冥會诗 五', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["朱軒下長路，青草啓孤墳。","猶勝陽臺上，空看朝暮雲。"]', '["朱軒下长路，青草啓孤墳。","猶勝陽台上，空看朝暮云。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 五 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6d35c03-5fff-4623-be90-8be88aa676b2', '與獨孤穆冥會詩 六', '與独孤穆冥會诗 六', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["露草芊芊，頹塋未遷。","自我居此，於今幾年。","與君先祖，疇昔恩波。","死生契闊，忽此相過。","誰謂佳期，尋當別離。","俟君之北，攜手同歸。"]', '["露草芊芊，頹塋未遷。","自我居此，於今幾年。","與君先祖，疇昔恩波。","死生契闊，忽此相過。","誰謂佳期，尋當別離。","俟君之北，携手同归。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 六 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15d2d0cc-9042-4e62-ae0c-a923309b1db9', '與獨孤穆冥會詩 七', '與独孤穆冥會诗 七', '8ef754a8-36c3-42fc-9b1a-a40239d44a2a', '唐', '["伊彼維揚，在天一方。","驅馬悠悠，忽來異鄉。","情通幽顯，獲此相見。","義感疇昔，言存繾綣。","清江桂洲，可以遨遊。","惟子之故，不遑淹留。"]', '["伊彼維揚，在天一方。","驱马悠悠，忽来異乡。","情通幽显，獲此相见。","義感疇昔，言存繾綣。","清江桂洲，可以遨游。","惟子之故，不遑淹留。"]', '诗', 'shi', '', NULL, '與獨孤穆冥會詩 七 臨淄縣主 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4805eef-d90c-4afa-a9bb-049a46274b84', '與李章武贈荅詩 一', '與李章武贈荅诗 一', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["鴛鴦綺，知結幾千絲。","別後尋交頸，應傷未別時。"]', '["鴛鴦綺，知結幾千絲。","別後尋交頸，應傷未別时。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 一 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2cad7053-c204-44d6-aee8-1981d3f53e60', '與李章武贈荅詩 二', '與李章武贈荅诗 二', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["捻指環，相思見環重相憶。","願君永持翫，循環無終極。"]', '["捻指环，相思见环重相憶。","願君永持翫，循环無終極。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 二 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45d77514-436f-4446-9fed-a0b8dbc45e62', '與李章武贈荅詩 三', '與李章武贈荅诗 三', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["河漢已傾斜，神魂欲超越。","願郎更迴抱，終天從此訣。"]', '["河漢已傾斜，神魂欲超越。","願郎更迴抱，終天從此訣。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 三 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2763892c-409e-4818-99ee-cf4544bf7d0e', '與李章武贈荅詩 四', '與李章武贈荅诗 四', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["分從幽顯隔，豈謂有佳期。","寧辭重重別，所歎去何之。"]', '["分從幽显隔，豈謂有佳期。","寧辞重重別，所歎去何之。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 四 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d756bfd-759b-411f-bb2e-7ba7c3208f43', '與李章武贈荅詩 五', '與李章武贈荅诗 五', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["昔辭懷後會，今別便終天。","新悲與舊恨，千古閉窮泉。"]', '["昔辞懷後會，今別便終天。","新悲與旧恨，千古閉窮泉。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 五 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d333b7e3-02d7-4475-bd59-6a2d8c4addb2', '與李章武贈荅詩 六', '與李章武贈荅诗 六', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["後期杳無約，前恨已相尋。","別路無行信，何因得寄心。"]', '["後期杳無約，前恨已相尋。","別路無行信，何因得寄心。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 六 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eb18320f-9135-481a-8c70-805383e9510f', '與李章武贈荅詩 七', '與李章武贈荅诗 七', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["水不西歸月暫圓，令人惆悵古城邊。","蕭條明早分岐路，知更相逢何歲年。"]', '["水不西归月暫圓，令人惆悵古城邊。","蕭條明早分岐路，知更相逢何歲年。"]', '诗', 'shi', '', NULL, '與李章武贈荅詩 七 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd320c3-1872-44a2-8f8a-81afc49de228', '李助爲章武賦', '李助爲章武賦', '08fabc14-619d-46f3-afdf-c164e3392bac', '唐', '["石沈遼海闊，劍別楚天長。","會合知無日，離心滿夕陽。"]', '["石沈遼海闊，劍別楚天长。","會合知無日，離心满夕陽。"]', '诗', 'shi', '', NULL, '李助爲章武賦 王氏婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('427e5247-4d70-4804-9382-ebc084a8cfa3', '與曾季衡冥會詩 一', '與曾季衡冥會诗 一', 'c3a401ed-160a-4a8f-a9ed-7bd4def917da', '唐', '["五原分袂真吳越，燕拆鶯離芳草歇。","年少煙花處處春，北邙空恨清秋月。"]', '["五原分袂真吳越，燕拆鶯離芳草歇。","年少煙花处处春，北邙空恨清秋月。"]', '诗', 'shi', '', NULL, '與曾季衡冥會詩 一 王麗真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c73b1917-7cff-4b0e-9a33-82a78a972435', '與曾季衡冥會詩 二', '與曾季衡冥會诗 二', 'c3a401ed-160a-4a8f-a9ed-7bd4def917da', '唐', '["莎草青青雁欲歸，玉腮珠淚灑臨岐。","雲鬟飄去香風盡，愁見鶯啼紅樹枝。"]', '["莎草青青雁欲归，玉腮珠泪灑臨岐。","云鬟飄去香风尽，愁见鶯啼紅樹枝。"]', '诗', 'shi', '', NULL, '與曾季衡冥會詩 二 王麗真 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a693c2a5-f0a0-4ac9-a48c-b0fc03d2b1df', '贈段何', '贈段何', '4482199d-d3e2-46b7-944d-3cfd5f6342de', '唐', '["樂廣清羸經幾年，姹娘相托不論錢。","輕盈妙質歸何處，惆悵碧樓紅玉鈿。"]', '["乐廣清羸經幾年，姹娘相托不論錢。","轻盈妙質归何处，惆悵碧楼紅玉鈿。"]', '诗', 'shi', '', NULL, '贈段何 客戶里女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09ef0a89-4c75-4f6e-803b-ed10b82179bc', '湖城廳吟', '湖城廳吟', 'b1042e63-1899-417c-b64b-f99b76c17bde', '唐', '["黃帝上天時，鼎湖元在茲。","七十二玉女，化作黃金芝。"]', '["黄帝上天时，鼎湖元在茲。","七十二玉女，化作黄金芝。"]', '诗', 'shi', '', NULL, '湖城廳吟 密陀僧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd7952d-1405-4a0c-83a5-bc54d75292cd', '謝王軒', '謝王軒', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["妾自吳宮還越國，素衣千載無人識。","當時心比金石堅，今日爲君堅不得。"]', '["妾自吳宮還越国，素衣千載無人識。","當时心比金石堅，今日爲君堅不得。"]', '诗', 'shi', '', NULL, '謝王軒 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('030a4be5-e7c6-4acf-b93c-870f2e39210b', '王軒題西施石詩', '王軒題西施石诗', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["嶺上千峰秀，江邊細草春。","今逢浣紗石，不見浣紗人。"]', '["嶺上千峰秀，江邊細草春。","今逢浣紗石，不见浣紗人。"]', '诗', 'shi', '', NULL, '王軒題西施石詩 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f707ad0-57aa-48ad-bdc7-bd5c2d74d4c9', '軒詩', '軒诗', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["佳人去千載，溪山久寂寞。","野水浮白煙，巖花自開落。","猨鳥舊清音，風月閑樓閣。","無語立斜陽，幽情入天幕。"]', '["佳人去千載，溪山久寂寞。","野水浮白煙，巖花自开落。","猨鸟旧清音，风月闲楼閣。","無語立斜陽，幽情入天幕。"]', '诗', 'shi', '', NULL, '軒詩 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6324cedb-99a2-4cbb-8374-ce2bebc4a535', '西施詩', '西施诗', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["高花巖外曉相鮮，幽鳥雨中啼不歇。","紅雲飛過大江西，從此人間怨風月。"]', '["高花巖外晓相鲜，幽鸟雨中啼不歇。","紅云飞過大江西，從此人间怨风月。"]', '诗', 'shi', '', NULL, '西施詩 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8083dc7-09f6-43ad-acae-850158d085ff', '軒詩', '軒诗', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["當時計拙笑將軍，何事安邦賴美人。","一自仙葩入吳國，從茲越國更無春。"]', '["當时計拙笑將軍，何事安邦賴美人。","一自仙葩入吳国，從茲越国更無春。"]', '诗', 'shi', '', NULL, '軒詩 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184771db-dc12-4e83-b701-4f741f09efcb', '西施詩', '西施诗', '835cc1be-b165-4462-bd66-477ae88f1a0c', '唐', '["雲霞出沒羣峰外，鷗鳥浮沈一水間。","一自越兵齊振地，夢魂不到虎丘山。"]', '["云霞出沒羣峰外，鷗鸟浮沈一水间。","一自越兵齊振地，梦魂不到虎丘山。"]', '诗', 'shi', '', NULL, '西施詩 西施 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f37e2c7d-1dcc-458c-8545-ef29d798f436', '與蕭曠冥會詩 一', '與蕭曠冥會诗 一', '88d047b6-40ac-4202-8c95-fcdfaf09857d', '唐', '["玉筯凝腮憶魏宮，朱弦一弄洗清風。","明晨追賞應愁寂，沙渚煙銷翠羽空。"]', '["玉筯凝腮憶魏宮，朱弦一弄洗清风。","明晨追賞應愁寂，沙渚煙銷翠羽空。"]', '诗', 'shi', '', NULL, '與蕭曠冥會詩 一 甄后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f1b6e65-1d71-43dc-be1e-f2c87aa2b242', '與蕭曠冥會詩 二', '與蕭曠冥會诗 二', '88d047b6-40ac-4202-8c95-fcdfaf09857d', '唐', '["織綃泉底少歡娛，更勸蕭郎盡酒壺。","愁見玉琴彈別鶴，又將清淚滴真珠。"]', '["织綃泉底少歡娛，更勸蕭郎尽酒壺。","愁见玉琴彈別鹤，又將清泪滴真珠。"]', '诗', 'shi', '', NULL, '與蕭曠冥會詩 二 甄后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90cbeeb8-098f-4eaa-a01c-a23511422eea', '與蕭曠冥會詩 三', '與蕭曠冥會诗 三', '88d047b6-40ac-4202-8c95-fcdfaf09857d', '唐', '["紅蘭吐豔間夭桃，自喜尋芳數已遭。","珠珮鶴橋從此斷，遙天空恨碧雲高。"]', '["紅蘭吐豔间夭桃，自喜尋芳數已遭。","珠珮鹤橋從此斷，遙天空恨碧云高。"]', '诗', 'shi', '', NULL, '與蕭曠冥會詩 三 甄后 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1184034-c9d6-47a3-a6ae-5f51a5fcbdaf', '五原夜吟', '五原夜吟', '8846c4bd-b4c6-4bb7-8edf-b82ad7ff499e', '唐', '["雲鬟消盡轉蓬稀，埋骨窮荒失所依。","牧馬不嘶沙月白，孤魂空逐雁南飛。"]', '["云鬟消尽轉蓬稀，埋骨窮荒失所依。","牧马不嘶沙月白，孤魂空逐雁南飞。"]', '诗', 'shi', '', NULL, '五原夜吟 沙磧女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c10e75d4-faa4-4e28-bfee-c64c71e8c2df', '與顏濬冥會詩 一', '與顏濬冥會诗 一', '6770cba0-8b1b-468d-8d34-3d529e1b0211', '唐', '["秋草荒臺響夜蛩，白楊凋盡減悲風。","綵箋曾擘欺江總，綺閣塵消玉樹空。"]', '["秋草荒台响夜蛩，白楊凋尽減悲风。","綵箋曾擘欺江總，綺閣塵消玉樹空。"]', '诗', 'shi', '', NULL, '與顏濬冥會詩 一 陳宮妃嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da4cb62b-c75a-4b43-8643-a95a411f6c36', '與顏濬冥會詩 二', '與顏濬冥會诗 二', '6770cba0-8b1b-468d-8d34-3d529e1b0211', '唐', '["寶閣排雲稱望仙，五雲高豔擁朝天。","清溪猶有當時月，應照瓊花綻綺筵。"]', '["寶閣排云稱望仙，五云高豔擁朝天。","清溪猶有當时月，應照瓊花綻綺筵。"]', '诗', 'shi', '', NULL, '與顏濬冥會詩 二 陳宮妃嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57e09b96-f8df-4838-a28b-e355fb080199', '與顏濬冥會詩 三', '與顏濬冥會诗 三', '6770cba0-8b1b-468d-8d34-3d529e1b0211', '唐', '["素魄初圓恨翠娥，繁華濃豔竟如何。","南朝唯有長江水，依舊門前作逝波。"]', '["素魄初圓恨翠娥，繁华濃豔竟如何。","南朝唯有长江水，依旧门前作逝波。"]', '诗', 'shi', '', NULL, '與顏濬冥會詩 三 陳宮妃嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('204b4249-aae6-4e85-ab35-508924d11839', '與顏濬冥會詩 四', '與顏濬冥會诗 四', '6770cba0-8b1b-468d-8d34-3d529e1b0211', '唐', '["簫管清吟怨麗華，秋江寒月綺窗斜。","慚非後主題箋客，得見臨春閣上花。"]', '["簫管清吟怨丽华，秋江寒月綺窗斜。","慚非後主題箋客，得见臨春閣上花。"]', '诗', 'shi', '', NULL, '與顏濬冥會詩 四 陳宮妃嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('83fd19d2-5f8e-474d-ac46-a0bc550d3789', '驛樓誦詩', '驛楼誦诗', '0dde48b0-d2f8-4b23-8871-872b8dbb741b', '唐', '["紅樹醉秋色，碧溪彈夜弦。","佳期不可再，風雨杳如年。"]', '["紅樹醉秋色，碧溪彈夜弦。","佳期不可再，风雨杳如年。"]', '诗', 'shi', '', NULL, '驛樓誦詩 湘中女子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8864251b-b248-40ab-95b3-a213e7d69d19', '贈楊藴中', '贈楊藴中', 'f5420a2f-ceb8-4039-ad6e-7251d1852014', '唐', '["玉漏聲長燈耿耿，東牆西牆時見影。","月明窗外子規啼，忍使孤魂愁夜永。"]', '["玉漏声长灯耿耿，东牆西牆时见影。","月明窗外子規啼，忍使孤魂愁夜永。"]', '诗', 'shi', '', NULL, '贈楊藴中 薛濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01d31485-c23b-47d0-80b7-3710f924195c', '葬後見形詩', '葬後见形诗', '435c37e9-78f5-4b95-b495-94a8d1875dac', '唐', '["獨臥經秋墮鬢蟬，白楊風起不成眠。","尋思往日椒房寵，淚濕衣襟損翠鈿。"]', '["独臥經秋墮鬢蟬，白楊风起不成眠。","尋思往日椒房寵，泪濕衣襟損翠鈿。"]', '诗', 'shi', '', NULL, '葬後見形詩 孟蜀妃張太華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c579ed2-3dd4-4396-8e03-2d6c98db9a4b', '謝李若沖', '謝李若沖', '435c37e9-78f5-4b95-b495-94a8d1875dac', '唐', '["符吏匆匆叩夜扃，便隨金簡出幽冥。","蒙師薦拔恩非淺，領得生神九過經。"]', '["符吏匆匆叩夜扃，便隨金簡出幽冥。","蒙師薦拔恩非淺，領得生神九過經。"]', '诗', 'shi', '', NULL, '謝李若沖 孟蜀妃張太華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e10b58ae-e575-40b5-ac2a-d2f89c200f88', '幽恨詩', '幽恨诗', '3252b417-2e09-4388-ae8b-1cabc150c19c', '唐', '["卜得上峽日，秋江風浪多。","巴陵一夜雨，腸斷木蘭歌。"]', '["卜得上峽日，秋江风浪多。","巴陵一夜雨，腸斷木蘭歌。"]', '诗', 'shi', '', NULL, '幽恨詩 安邑坊女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3451b23-106e-49cc-84c8-a5458c9745ac', '和檢詩', '和檢诗', 'da13df65-87b1-4e0a-94f6-f010aa094635', '唐', '["春雨濛濛不見天，家家門外柳和煙。","如今腸斷空垂淚，歡笑重追別有年。"]', '["春雨濛濛不见天，家家门外柳和煙。","如今腸斷空垂泪，歡笑重追別有年。"]', '诗', 'shi', '', NULL, '和檢詩 韋檢亡姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec468eb3-5f29-41ff-bfdd-faa75f448a60', '檢悼亡姬詩', '檢悼亡姬诗', 'da13df65-87b1-4e0a-94f6-f010aa094635', '唐', '["寶劒化龍歸碧落，嫦娥隨月下黃泉。","一杯酒向青春晚，寂寞書窗恨獨眠。"]', '["寶劒化龙归碧落，嫦娥隨月下黄泉。","一杯酒向青春晚，寂寞书窗恨独眠。"]', '诗', 'shi', '', NULL, '檢悼亡姬詩 韋檢亡姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('affeca76-00ca-4ddc-b5e3-edd9da06adf8', '夢後自題', '梦後自題', 'da13df65-87b1-4e0a-94f6-f010aa094635', '唐', '["白浪漫漫去不迴，浮雲飛盡日西頹。","始皇陵上千年樹，銀鴨金鳧也變灰。"]', '["白浪漫漫去不迴，浮云飞尽日西頹。","始皇陵上千年樹，銀鴨金鳧也变灰。"]', '诗', 'shi', '', NULL, '夢後自題 韋檢亡姬 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92024527-0c18-44ae-b8b1-3ee1a51ddbc2', '與夫同詠詩 一', '與夫同詠诗 一', '8075a205-76c7-4b36-97f5-6f15b4cca2a2', '唐', '["楚水平如鏡，周迴白鳥飛。","金陵幾多地，一去不知歸。"]', '["楚水平如镜，周迴白鸟飞。","金陵幾多地，一去不知归。"]', '诗', 'shi', '', NULL, '與夫同詠詩 一 蘇檢妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d8575e7-412b-435e-a4f1-81d3b392c8a1', '與夫同詠詩 二', '與夫同詠诗 二', '8075a205-76c7-4b36-97f5-6f15b4cca2a2', '唐', '["還吳東去過澄城，樓上清風酒半醒。","想得到家春已暮，海棠千樹已凋零。"]', '["還吳东去過澄城，楼上清风酒半醒。","想得到家春已暮，海棠千樹已凋零。"]', '诗', 'shi', '', NULL, '與夫同詠詩 二 蘇檢妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d82d37dd-2404-4599-b1f8-aa17b6cbfde1', '冥會詩 一', '冥會诗 一', '0892e44a-6309-49e1-802c-7ccad26cbba0', '唐', '["爭不逢人話此身，此身長夜不知春。","自從國破家亡後，隴上惟添芳草新。"]', '["爭不逢人話此身，此身长夜不知春。","自從国破家亡後，隴上惟添芳草新。"]', '诗', 'shi', '', NULL, '冥會詩 一 宮嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9587eb7b-3381-420a-a5d8-ad7ed6550bb4', '冥會詩 二', '冥會诗 二', '0892e44a-6309-49e1-802c-7ccad26cbba0', '唐', '["休說人間恨戀多，況逢佳客此相過。","堂中縱有千般樂，爭及陽春一曲歌。"]', '["休说人间恨戀多，況逢佳客此相過。","堂中縱有千般乐，爭及陽春一曲歌。"]', '诗', 'shi', '', NULL, '冥會詩 二 宮嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2734c5d1-2cd2-48fc-a6c1-636db69898bf', '冥會詩 三', '冥會诗 三', '0892e44a-6309-49e1-802c-7ccad26cbba0', '唐', '["幽谷窮花似妾身，縱懷香豔吐無因。","多情公子能相訪，應解回風暫借春。"]', '["幽谷窮花似妾身，縱懷香豔吐無因。","多情公子能相訪，應解回风暫借春。"]', '诗', 'shi', '', NULL, '冥會詩 三 宮嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4395d2ce-b601-4287-99e5-0b1bfab62b36', '冥會詩 四', '冥會诗 四', '0892e44a-6309-49e1-802c-7ccad26cbba0', '唐', '["恩情未足曉光催，數朵眠花未得開。","却羨一雙金扼臂，得隨人世出將來。"]', '["恩情未足晓光催，數朵眠花未得开。","却羨一雙金扼臂，得隨人世出將来。"]', '诗', 'shi', '', NULL, '冥會詩 四 宮嬪 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f07b9a00-14d4-495d-9b20-09b89f28dcb3', '與謝翶贈荅詩 一', '與謝翶贈荅诗 一', 'aa40e466-c649-4ae0-88f8-5eee75d7320e', '唐', '["陽臺後會杳無期，碧樹煙深玉漏遲。","半夜香風滿庭月，花前空賦別離詩。"]', '["陽台後會杳無期，碧樹煙深玉漏遲。","半夜香风满庭月，花前空賦別離诗。"]', '诗', 'shi', '', NULL, '與謝翶贈荅詩 一 金車美人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c33c30a-7391-4656-a879-73b7c1e81648', '與謝翶贈荅詩 二', '與謝翶贈荅诗 二', 'aa40e466-c649-4ae0-88f8-5eee75d7320e', '唐', '["相思無路莫相思，風裏花開只片時。","惆悵金閨却歸去，曉鶯啼斷綠楊枝。"]', '["相思無路莫相思，风裏花开只片时。","惆悵金閨却归去，晓鶯啼斷綠楊枝。"]', '诗', 'shi', '', NULL, '與謝翶贈荅詩 二 金車美人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4f325815-50e2-4fb0-9b20-8f95e9d1e2ba', '與謝翶贈荅詩 三', '與謝翶贈荅诗 三', 'aa40e466-c649-4ae0-88f8-5eee75d7320e', '唐', '["一紙華箋灑碧雲，餘香猶在墨猶新。","空添滿目淒涼事，不見三山縹緲人。","斜月照衣今夜夢，落花啼鳥去年春。","紅閨更有堪愁處，窗上蟲絲几上塵。"]', '["一紙华箋灑碧云，餘香猶在墨猶新。","空添满目淒涼事，不见三山縹緲人。","斜月照衣今夜梦，落花啼鸟去年春。","紅閨更有堪愁处，窗上蟲絲几上塵。"]', '诗', 'shi', '', NULL, '與謝翶贈荅詩 三 金車美人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcd2e38c-5aea-493c-bc18-b4b26a2e22c6', '與謝翶贈荅詩 四', '與謝翶贈荅诗 四', 'aa40e466-c649-4ae0-88f8-5eee75d7320e', '唐', '["惆悵佳期一夢中，武陵春色盡成空。","欲知離別偏堪恨，只爲音塵兩不通。","愁態上眉凝淺綠，淚痕侵臉落輕紅。","雙輪暫與王孫駐，明日西馳又向東。"]', '["惆悵佳期一梦中，武陵春色尽成空。","欲知離別偏堪恨，只爲音塵兩不通。","愁態上眉凝淺綠，泪痕侵臉落轻紅。","雙輪暫與王孫駐，明日西驰又向东。"]', '诗', 'shi', '', NULL, '與謝翶贈荅詩 四 金車美人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e27f3f2-a985-4884-a502-ff19873530e8', '贈朋詩', '贈朋诗', 'c0953fc3-a87b-4538-b346-8f665e5e8b73', '唐', '["孤墳臨清江，每覩白日晚。","松影搖長風，蟾光落嵓甸。","故鄉千里餘，親戚罕相見。","望望空雲山，哀哀淚如霰。","恨爲泉臺客，復此異鄉縣。","願言敦疇昔，勿以棄疵賤。"]', '["孤墳臨清江，每覩白日晚。","松影搖长风，蟾光落嵓甸。","故乡千里餘，親戚罕相见。","望望空云山，哀哀泪如霰。","恨爲泉台客，复此異乡縣。","願言敦疇昔，勿以棄疵賤。"]', '诗', 'shi', '', NULL, '贈朋詩 魏朋妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70169124-9a1e-49d1-89ea-bd054f7f1b0b', '題明月堂二首 一', '題明月堂二首 一', '000cdd78-093e-4c8c-a5bc-c524574fb511', '唐', '["蟬鬢驚秋華髮新，可憐紅隙盡埃塵。","西山一夢何年覺，明月堂前不見人。"]', '["蟬鬢驚秋华髮新，可怜紅隙尽埃塵。","西山一梦何年覺，明月堂前不见人。"]', '诗', 'shi', '', NULL, '題明月堂二首 一 劉氏亡婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e9e715e-7fc9-42ca-a14c-1fc624350465', '題明月堂二首 二', '題明月堂二首 二', '000cdd78-093e-4c8c-a5bc-c524574fb511', '唐', '["玉鉤風急響丁東，回首西山似夢中。","明月堂前人不到，庭前一夜老秋風。"]', '["玉鉤风急响丁东，回首西山似梦中。","明月堂前人不到，庭前一夜老秋风。"]', '诗', 'shi', '', NULL, '題明月堂二首 二 劉氏亡婦 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64a3dde0-580d-474c-a784-f04b3ef6cccb', '詩', '诗', '04e6678d-3ffa-4b66-9506-1fbedc8c76df', '唐', '["歌罷玉樓月，舞殘金縷衣。","勻鈿收迸節，歛黛別重闈。","網斷蛛猶織，梁春燕不歸。","那堪回首處，江步野棠飛。"]', '["歌罷玉楼月，舞殘金縷衣。","勻鈿收迸節，歛黛別重闈。","網斷蛛猶织，梁春燕不归。","那堪回首处，江步野棠飞。"]', '诗', 'shi', '', NULL, '詩 故臺城妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ffe4c13-9ad6-4985-b231-80361ffed3e9', '金陵詞', '金陵词', '04e6678d-3ffa-4b66-9506-1fbedc8c76df', '唐', '["宮中細草香紅濕，宮內纖腰碧窗泣。","唯有虹梁春燕雛，猶傍珠簾玉鉤立。"]', '["宮中細草香紅濕，宮內纖腰碧窗泣。","唯有虹梁春燕雛，猶傍珠簾玉鉤立。"]', '诗', 'shi', '', NULL, '金陵詞 故臺城妓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b2443b-fd4d-49ee-85b1-3b5f738e88f4', '示宋善威', '示宋善威', 'a4e88b20-06a0-4a73-a815-eafe5c925cd2', '唐', '["月落三株樹，日映九重天。","良夜歡宴罷，暫別庚申年。"]', '["月落三株樹，日映九重天。","良夜歡宴罷，暫別庚申年。"]', '诗', 'shi', '', NULL, '示宋善威 無名女鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bceef88-00b6-443c-a185-c69f3e03b8b7', '詩 一', '诗 一', '3a2fe736-7101-4ab6-a8bd-487081f25d13', '唐', '["江上檣竿一百尺，山中樓臺十二重。","山僧樓上望江上，指點檣竿笑殺儂。"]', '["江上檣竿一百尺，山中楼台十二重。","山僧楼上望江上，指点檣竿笑殺儂。"]', '诗', 'shi', '', NULL, '詩 一 無名鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8d30735-3682-4fc1-81c5-1c09a5770ee8', '詩 二', '诗 二', '3a2fe736-7101-4ab6-a8bd-487081f25d13', '唐', '["仙人未必便仙去，還在人間人不知。","手把白鬚從兩鹿，相逢却問姓名誰。"]', '["仙人未必便仙去，還在人间人不知。","手把白鬚從兩鹿，相逢却问姓名誰。"]', '诗', 'shi', '', NULL, '詩 二 無名鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caf419a4-a0df-4cb3-bb13-ee47a8ec2926', '句', '句', '7e871a1b-8a10-4a09-a4a1-2e7bf8c449a3', '唐', '["柏堂新成樂未央，迴來迴去繞裴郎。"]', '["柏堂新成乐未央，迴来迴去繞裴郎。"]', '诗', 'shi', '', NULL, '句 穠華 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34a5445d-4ff6-4f68-a77e-12a45691f68e', '句', '句', '8b294038-192f-4818-b8be-6eac94298136', '唐', '["薄命蘇秦頻去國，多情潘岳旋興悲。","今夜若棲芳草徑，爲傳幽意達王孫。"]', '["薄命蘇秦頻去国，多情潘岳旋兴悲。","今夜若棲芳草徑，爲傳幽意達王孫。"]', '诗', 'shi', '', NULL, '句 張守中 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e646716-6430-43ad-9aee-c0da45a342bd', '句', '句', '3a2fe736-7101-4ab6-a8bd-487081f25d13', '唐', '["芫花半落，松風晚清。"]', '["芫花半落，松风晚清。"]', '诗', 'shi', '', NULL, '句 無名鬼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a367a96d-c6cd-4696-bcfb-b644f5a36494', '渾家門客聯句 一', '渾家门客聯句 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["自與渾家鄰，馨香遂滿身。","無心好清靜，人用去灰塵。"]', '["自與渾家鄰，馨香遂满身。","無心好清静，人用去灰塵。"]', '诗', 'shi', '', NULL, '渾家門客聯句 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f347f297-2fc3-408d-9cef-107caabfd61a', '渾家門客聯句 二', '渾家门客聯句 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["終朝每去依煙火，春至還歸養子孫。","曾向苻王筆端坐，爾來求食渾家門。"]', '["終朝每去依煙火，春至還归養子孫。","曾向苻王笔端坐，爾来求食渾家门。"]', '诗', 'shi', '', NULL, '渾家門客聯句 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56371040-0a1f-4141-97fa-e26b1907feb5', '長鬚國駙馬詠妻', '长鬚国駙马詠妻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["花無葉不妍，女無鬚亦醜。","丈人試遣惣無，未必不如惣有。"]', '["花無葉不妍，女無鬚亦醜。","丈人試遣惣無，未必不如惣有。"]', '诗', 'shi', '', NULL, '長鬚國駙馬詠妻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4a13248-aed5-4408-8d69-678c8e0b39d3', '原陵老翁吟', '原陵老翁吟', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["野田荆棘春，閨閣綺羅新。","出沒頭上日，生死眼前人。","欲知我家在何處，北邙松柏正爲鄰。","洛陽女兒羅綺多，無奈孤翁老去何，奈爾何。","正色鴻燾，神思化伐。","穹施后承，光負玄設。","嘔淪吐萌，垠倪散截。","迷腸郗曲，䨴零霾曀。","雀燬龜水，健馳御屈。","拿尾研動，袾袾哳哳。","㳷用祕功，以嶺以穴。","柂薪伐藥，莽榤萬茁。","嘔律則祥，佛倫惟薩。","牡虛無有，頤咽蘂屑。","肇素未來，晦明興滅。","五行七曜，成此閏餘。","上帝降靈，歲且涒徐。","蛇蛻其皮，吾亦神攄。","九九六六，束身天除。","何以充喉，吐納太虛。","何以蔽踝，霞袂雲袽。","哀爾浮生，櫛比荒墟。","吾復麗氣，還形之初。","在帝左右，道濟忽諸。"]', '["野田荆棘春，閨閣綺羅新。","出沒头上日，生死眼前人。","欲知我家在何处，北邙松柏正爲鄰。","洛陽女兒羅綺多，無奈孤翁老去何，奈爾何。","正色鴻燾，神思化伐。","穹施后承，光負玄設。","嘔淪吐萌，垠倪散截。","迷腸郗曲，䨴零霾曀。","雀燬龟水，健驰御屈。","拿尾研动，袾袾哳哳。","㳷用祕功，以嶺以穴。","柂薪伐藥，莽榤万茁。","嘔律則祥，佛倫惟薩。","牡虛無有，頤咽蘂屑。","肇素未来，晦明兴滅。","五行七曜，成此閏餘。","上帝降靈，歲且涒徐。","蛇蛻其皮，吾亦神攄。","九九六六，束身天除。","何以充喉，吐納太虛。","何以蔽踝，霞袂云袽。","哀爾浮生，櫛比荒墟。","吾复丽氣，還形之初。","在帝左右，道濟忽諸。"]', '诗', 'shi', '', NULL, '原陵老翁吟 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b21cf19f-854d-4a0a-9c77-3ab33b94193e', '嚴含質詩 一', '嚴含質诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昔爲仙子今爲虎，流落陰崖足風雨。","更將斑毳被余身，千載空山萬般苦。"]', '["昔爲仙子今爲虎，流落陰崖足风雨。","更將斑毳被余身，千載空山万般苦。"]', '诗', 'shi', '', NULL, '嚴含質詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46911494-dfa0-4001-a27d-a8235716ecf3', '嚴含質詩 二', '嚴含質诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["下玄八千億甲子，丹飛先生嚴含質。","謫下中天被斑革，六千甲子，血食澗飲廁猨狖。","下濁界，景雲元紀升太一。"]', '["下玄八千億甲子，丹飞先生嚴含質。","謫下中天被斑革，六千甲子，血食澗饮廁猨狖。","下濁界，景云元紀升太一。"]', '诗', 'shi', '', NULL, '嚴含質詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18f2d824-0200-4e23-8dbb-483726bd698e', '李微詩', '李微诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["偶因狂疾成殊類，災患相任不可逃。","今日爪牙誰敢敵，當時聲跡共相高。","我爲異物蓬茅下，君已乘軺氣勢豪。","此夕溪山對明月，不成長嘯但成嗥。"]', '["偶因狂疾成殊類，災患相任不可逃。","今日爪牙誰敢敵，當时声跡共相高。","我爲異物蓬茅下，君已乘軺氣勢豪。","此夕溪山对明月，不成长嘯但成嗥。"]', '诗', 'shi', '', NULL, '李微詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7cbebfdd-2974-46ef-b399-f27a69574b0b', '維揚空莊四怪聯句', '維揚空莊四怪聯句', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["齊紈魯縞如霜雪，寥亮高聲予所發。","嘉賓良會清夜時，煌煌燈燭我能持。","清冷之泉候朝汲，桑綆相牽常出入。","爨薪貯泉相煎熬，充他口腹我爲勞。"]', '["齊紈魯縞如霜雪，寥亮高声予所發。","嘉賓良會清夜时，煌煌灯燭我能持。","清冷之泉候朝汲，桑綆相牽常出入。","爨薪貯泉相煎熬，充他口腹我爲勞。"]', '诗', 'shi', '', NULL, '維揚空莊四怪聯句 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fd8b4cc-de12-4683-b608-f21f1634f690', '柳藏經二絕句 一', '柳藏經二絕句 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寒水停園沼，秋池滿敗荷。","杜門窮典籍，所得事今多。"]', '["寒水停园沼，秋池满敗荷。","杜门窮典籍，所得事今多。"]', '诗', 'shi', '', NULL, '柳藏經二絕句 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e571c24-326f-47c3-a161-91fb5ff41f23', '柳藏經二絕句 二', '柳藏經二絕句 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["誰謂三才貴，余觀萬化同。","心虛嫌蠹食，年老怯狂風。"]', '["誰謂三才貴，余观万化同。","心虛嫌蠹食，年老怯狂风。"]', '诗', 'shi', '', NULL, '柳藏經二絕句 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c35f75b-cdd0-463c-9e81-d74494772679', '太白山魔誑道士詩', '太白山魔誑道士诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三秋稽顙叩真靈，龍虎交時金液成。","絳雪既凝身可度，蓬壺頂上彩雲生。"]', '["三秋稽顙叩真靈，龙虎交时金液成。","絳雪既凝身可度，蓬壺頂上彩云生。"]', '诗', 'shi', '', NULL, '太白山魔誑道士詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d877cad-559e-40a3-ba25-30eaff832e1e', '金缶魅詩', '金缶魅诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["色分藍葉青，聲比磬中鳴。","七月初七夜，吾當示汝形。"]', '["色分藍葉青，声比磬中鳴。","七月初七夜，吾當示汝形。"]', '诗', 'shi', '', NULL, '金缶魅詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2776a09-efd7-4022-b2fa-e44c2a1d9c47', '東陽夜怪詩 一', '东陽夜怪诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["誰家掃雪滿庭前，萬壑千峰在一拳。","吾心不覺侵衣冷，曾向此中居幾年。"]', '["誰家掃雪满庭前，万壑千峰在一拳。","吾心不覺侵衣冷，曾向此中居幾年。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae73843-88b1-4611-9426-abce7549c85f', '東陽夜怪詩 二', '东陽夜怪诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["擁褐藏名無定蹤，流沙千里度衰容。","傳得南宗心地後，此身應便老雙峰。"]', '["擁褐藏名無定蹤，流沙千里度衰容。","傳得南宗心地後，此身應便老雙峰。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716f33b2-d9e1-4ca3-9089-8ea68e9d1794', '東陽夜怪詩 三', '东陽夜怪诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爲有閻浮珍重因，遠離西國赴咸秦。","自從無力休行道，且作頭陀不繫身。"]', '["爲有閻浮珍重因，远離西国赴咸秦。","自從無力休行道，且作头陀不繫身。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e2a5a6d2-17ae-43e9-b24d-48b88b84d7de', '東陽夜怪詩 四', '东陽夜怪诗 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["長安城東洛陽道，車輪不息塵浩浩。","爭利貪前競著鞭，相逢盡是塵中老。"]', '["长安城东洛陽道，车輪不息塵浩浩。","爭利貪前競著鞭，相逢尽是塵中老。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ef3da5d-c758-46d6-96aa-c6e76dcd26eb', '東陽夜怪詩 五', '东陽夜怪诗 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["日晚長川不計程，離羣獨步不能鳴。","賴有青青河畔草，春來猶得慰羈情。"]', '["日晚长川不計程，離羣独步不能鳴。","賴有青青河畔草，春来猶得慰羈情。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('369deef3-fa19-4b2b-8a31-d5b6f1e9556b', '東陽夜怪詩 六', '东陽夜怪诗 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["愛此飄颻六出公，輕瓊冷絮舞長空。","當時正逐秦丞相，騰躑川原喜北風。"]', '["愛此飄颻六出公，轻瓊冷絮舞长空。","當时正逐秦丞相，腾躑川原喜北风。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf88997e-b729-4d0f-b0bb-b7ebcca84b46', '東陽夜怪詩 七', '东陽夜怪诗 七', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["事君同樂義同憂，那校糟糠滿志休。","不是守株空待兔，終當逐鹿出林丘。"]', '["事君同乐義同憂，那校糟糠满志休。","不是守株空待兔，終當逐鹿出林丘。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 七 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9becb56d-e25e-4fca-96de-613751da9dbb', '東陽夜怪詩 八', '东陽夜怪诗 八', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["少年長負飢鷹用，內顧曾無寵鶴心。","秋草驅除思去宇，平原毛血興從禽。"]', '["少年长負飢鷹用，內顧曾無寵鹤心。","秋草驱除思去宇，平原毛血兴從禽。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 八 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e6e7829-ac91-4eb3-a1b2-1c9d1d37a5aa', '東陽夜怪詩 九', '东陽夜怪诗 九', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["舞鏡爭鸞綵，臨場定鶻拳。","正思仙仗日，翹首仰樓前。"]', '["舞镜爭鸾綵，臨場定鶻拳。","正思仙仗日，翹首仰楼前。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 九 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e46985e-3191-43cd-8b61-9379099bcb97', '東陽夜怪詩 十', '东陽夜怪诗 十', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["養鬬形如木，迎春質似泥。","信如風雨在，何憚跡卑棲。"]', '["養鬬形如木，迎春質似泥。","信如风雨在，何憚跡卑棲。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 十 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccbe0a83-5f8e-4444-9c4e-01267a83d416', '東陽夜怪詩 十一', '东陽夜怪诗 十一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爲脫田文難，常懷紀渻恩。","欲知疎野態，霜曉叫荒村。"]', '["爲脫田文难，常懷紀渻恩。","欲知疎野態，霜晓叫荒村。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 十一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f4cfd5-1231-4f2b-a92b-ec292ce9c042', '東陽夜怪詩 十二', '东陽夜怪诗 十二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["亂魯負虛名，遊秦感甯生。","候驚丞相喘，用識葛盧鳴。","黍稷滋農具，軒車乏道情。","近來筋力退，一志在歸耕。"]', '["亂魯負虛名，游秦感甯生。","候驚丞相喘，用識葛盧鳴。","黍稷滋農具，軒车乏道情。","近来筋力退，一志在归耕。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 十二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca294d43-667e-4c92-8059-a0ef3eeb634b', '東陽夜怪詩 十三', '东陽夜怪诗 十三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["爲慙食肉主恩深，日晏蟠蜿臥錦衾。","且學志人知白黑，那將好爵動吾心。"]', '["爲慙食肉主恩深，日晏蟠蜿臥錦衾。","且学志人知白黑，那將好爵动吾心。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 十三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d4fb98d-7d09-4ff7-8ce1-14059227f93b', '東陽夜怪詩 十四', '东陽夜怪诗 十四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鳥鼠是家川，周王昔獵賢。","一從離子卯，應見海桑田。"]', '["鸟鼠是家川，周王昔獵賢。","一從離子卯，應见海桑田。"]', '诗', 'shi', '', NULL, '東陽夜怪詩 十四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('388f8514-7fdc-41b0-a05d-7f27ea542514', '田四郎求婚聯句', '田四郎求婚聯句', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一點紅裳出翠微，秋天雲靜月離離。","天曹使者徒回首，何不從他九族卑。"]', '["一点紅裳出翠微，秋天云静月離離。","天曹使者徒回首，何不從他九族卑。"]', '诗', 'shi', '', NULL, '田四郎求婚聯句 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1454c43c-537e-4ee4-9d33-1e1af71fd19b', '黑駒別盧傳素詩', '黑駒別盧傳素诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["既食丈人粟，又飽丈人芻。","今日相償了，永離三惡途。"]', '["既食丈人粟，又飽丈人芻。","今日相償了，永離三惡途。"]', '诗', 'shi', '', NULL, '黑駒別盧傳素詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e4957c8-27eb-4147-a8cb-bbedd9bd4adf', '筆精詩 一', '笔精诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昔荷蒙恬惠，尋遭仲叔投。","夫君不指使，何處覓銀鈎。"]', '["昔荷蒙恬惠，尋遭仲叔投。","夫君不指使，何处覓銀鈎。"]', '诗', 'shi', '', NULL, '筆精詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7862ae7a-1f0d-4c35-ac5b-50cfdf16803e', '筆精詩 二', '笔精诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["學問從君有，詩書自我傳。","須知王逸少，名價動千年。"]', '["学问從君有，诗书自我傳。","須知王逸少，名價动千年。"]', '诗', 'shi', '', NULL, '筆精詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd615553-33d3-4c3c-b403-e016e84cc7fe', '筆精詩 三', '笔精诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["能令音信通千里，解致龍蛇運八行。","惆悵江生不相賞，應緣自負好文章。"]', '["能令音信通千里，解致龙蛇運八行。","惆悵江生不相賞，應緣自負好文章。"]', '诗', 'shi', '', NULL, '筆精詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f112c8e5-74d9-442c-8a57-020c6ff9ba10', '二斑與甯茵賦詩 一', '二斑與甯茵賦诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["曉讀雲水靜，夜吟山月高。","焉能履虎尾，豈用學牛刀。"]', '["晓读云水静，夜吟山月高。","焉能履虎尾，豈用学牛刀。"]', '诗', 'shi', '', NULL, '二斑與甯茵賦詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50714082-3ba6-467d-aa03-d22d8a020827', '二斑與甯茵賦詩 二', '二斑與甯茵賦诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["但得居林嘯，焉能當路蹲。","渡河何所適，終是怯劉琨。"]', '["但得居林嘯，焉能當路蹲。","渡河何所適，終是怯劉琨。"]', '诗', 'shi', '', NULL, '二斑與甯茵賦詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('690f0b29-8ed6-4508-a1ba-45dd549ea494', '二斑與甯茵賦詩 三', '二斑與甯茵賦诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["無非悲甯戚，終是怯庖丁。","若遇龔爲守，蹄涔向北溟。"]', '["無非悲甯戚，終是怯庖丁。","若遇龔爲守，蹄涔向北溟。"]', '诗', 'shi', '', NULL, '二斑與甯茵賦詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9003971-440b-4de5-a44d-1cc4fd25fd04', '白田獺魅別村女詩', '白田獺魅別村女诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["潮來逐潮上，潮落在空灘。","有來終有去，情易復情難。","腸斷腸中子，明月秋江寒。"]', '["潮来逐潮上，潮落在空灘。","有来終有去，情易复情难。","腸斷腸中子，明月秋江寒。"]', '诗', 'shi', '', NULL, '白田獺魅別村女詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a77214a-0f1e-4c41-afe7-b18d8f346450', '邢君才舊宅三怪詩 一', '邢君才旧宅三怪诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["昔日炎炎徒自知，今無烽竈欲何爲。","可憐國柄全無用，曾見家人下第時。"]', '["昔日炎炎徒自知，今無烽竈欲何爲。","可怜国柄全無用，曾见家人下第时。"]', '诗', 'shi', '', NULL, '邢君才舊宅三怪詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10b291ec-d302-46ff-bb10-3459289c303f', '邢君才舊宅三怪詩 二', '邢君才旧宅三怪诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["當時得意氣填心，一曲君前直萬金。","今日不如庭下竹，風來猶得學龍吟。"]', '["當时得意氣填心，一曲君前直万金。","今日不如庭下竹，风来猶得学龙吟。"]', '诗', 'shi', '', NULL, '邢君才舊宅三怪詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('335fe8e7-5a29-4282-8ffa-82e991009011', '邢君才舊宅三怪詩 三', '邢君才旧宅三怪诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["頭焦鬢禿但心存，力盡塵埃不復論。","莫笑今來同腐草，曾經終日掃朱門。"]', '["头焦鬢禿但心存，力尽塵埃不复論。","莫笑今来同腐草，曾經終日掃朱门。"]', '诗', 'shi', '', NULL, '邢君才舊宅三怪詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca2e01a7-d44d-4c45-891d-2794d3053053', '維揚少年與孟氏贈荅詩 一', '維揚少年與孟氏贈荅诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["可惜春時節，依然獨自遊。","無端兩行淚，長祇對花流。"]', '["可惜春时節，依然独自游。","無端兩行泪，长祇对花流。"]', '诗', 'shi', '', NULL, '維揚少年與孟氏贈荅詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16b83c74-858d-4a0d-82c7-25b8ba3361a0', '維揚少年與孟氏贈荅詩 二', '維揚少年與孟氏贈荅诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["誰家少年兒，心中暗自欺。","不道終不可，可即恐郎知。"]', '["誰家少年兒，心中暗自欺。","不道終不可，可即恐郎知。"]', '诗', 'shi', '', NULL, '維揚少年與孟氏贈荅詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3425de6-ea6d-474e-b0f3-43443944053d', '維揚少年與孟氏贈荅詩 三', '維揚少年與孟氏贈荅诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["神女得張碩，文君遇長卿。","逢時兩相得，聊足慰多情。"]', '["神女得張碩，文君遇长卿。","逢时兩相得，聊足慰多情。"]', '诗', 'shi', '', NULL, '維揚少年與孟氏贈荅詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed6dd400-0029-4a8d-8717-110539dfc884', '胡志忠題戶', '胡志忠題戶', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["恃勇禍必嬰，恃強勢必傾。","胡爲萬金子，而與惡物爭。","休將逝魄趨府庭，止於此館歸冥冥。"]', '["恃勇禍必嬰，恃強勢必傾。","胡爲万金子，而與惡物爭。","休將逝魄趨府庭，止於此館归冥冥。"]', '诗', 'shi', '', NULL, '胡志忠題戶 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aeb9ccb-bfc9-4f1e-943c-a80c10f22f15', '高侍郎詩', '高侍郎诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["危冠高袖楚宮妝，獨步閑庭逐夜涼。","自把玉簪敲砌竹，清歌一曲月如霜。"]', '["危冠高袖楚宮妝，独步闲庭逐夜涼。","自把玉簪敲砌竹，清歌一曲月如霜。"]', '诗', 'shi', '', NULL, '高侍郎詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46cdaeb3-500d-4ef4-9e95-8c8093457109', '呂氏宅妖誓師詞', '呂氏宅妖誓師词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天馬斜飛度三止，上將橫行擊四方。","輜車直入無迴翔，六甲次第不乖行。"]', '["天马斜飞度三止，上將橫行擊四方。","輜车直入無迴翔，六甲次第不乖行。"]', '诗', 'shi', '', NULL, '呂氏宅妖誓師詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fc0d056-b329-4c4d-96a6-4833ce7a5ab7', '袁少年詩 一', '袁少年诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["風波千里闊，臺榭半天高。","此興將何比，身知插羽毛。"]', '["风波千里闊，台榭半天高。","此兴將何比，身知插羽毛。"]', '诗', 'shi', '', NULL, '袁少年詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('057a3920-5f3b-4deb-8b8c-b40d6af6ecb6', '袁少年詩 二', '袁少年诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["峰巒多秀色，松桂足清聲。","自有山林趣，全忘城闕情。"]', '["峰巒多秀色，松桂足清声。","自有山林趣，全忘城闕情。"]', '诗', 'shi', '', NULL, '袁少年詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f06d895-4618-4aa1-9eb0-6493266c9e1d', '袁少年詩 三', '袁少年诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["羅浮南海外，昔日已聞之。","千里來游覽，幽情我自知。"]', '["羅浮南海外，昔日已闻之。","千里来游覽，幽情我自知。"]', '诗', 'shi', '', NULL, '袁少年詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bd2092f-c2e1-423b-89a1-e694c0716b8c', '東柯院妖謔杜令 一', '东柯院妖謔杜令 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["雖共蒿蘭伍，南朝有宗祖。","莫打綠袍人，空中且歌舞。"]', '["雖共蒿蘭伍，南朝有宗祖。","莫打綠袍人，空中且歌舞。"]', '诗', 'shi', '', NULL, '東柯院妖謔杜令 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a453e7-4e10-4a22-8299-f8af413b53a6', '東柯院妖謔杜令 二', '东柯院妖謔杜令 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["堪憐木邊土，非兒不似女。","瘦馬上高山，登臨何自苦。"]', '["堪怜木邊土，非兒不似女。","瘦马上高山，登臨何自苦。"]', '诗', 'shi', '', NULL, '東柯院妖謔杜令 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('525fec80-f68a-4eec-9c45-181f8b3395c7', '嵩山小兒吟', '嵩山小兒吟', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我本長生深山內，更何入他不二門。","爭如訪取舊時伴，休更朝夕勞神魂。"]', '["我本长生深山內，更何入他不二门。","爭如訪取旧时伴，休更朝夕勞神魂。"]', '诗', 'shi', '', NULL, '嵩山小兒吟 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aac0c05-e83d-4a37-9a6a-6eb75d873785', '魚腹丹書', '鱼腹丹书', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["九登龍門山，三飲太湖水。","畢竟不成龍，命負張胡子。"]', '["九登龙门山，三饮太湖水。","畢竟不成龙，命負張胡子。"]', '诗', 'shi', '', NULL, '魚腹丹書 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31677a47-3b7f-412a-a5fc-6d55d6eb64e3', '魚身字', '鱼身字', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["三度過海，兩度上漢。","行至勒漠，命屬柏君。"]', '["三度過海，兩度上漢。","行至勒漠，命屬柏君。"]', '诗', 'shi', '', NULL, '魚身字 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42b1806e-4526-4d7a-8a6c-d302b90c57f5', '馬作人語', '马作人語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蘆荻花，此花開後路無家。"]', '["蘆荻花，此花开後路無家。"]', '诗', 'shi', '', NULL, '馬作人語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f84d580d-58d5-4cd4-8f3d-3bc3ba58e729', '孫長史女與焦封贈荅詩 一', '孫长史女與焦封贈荅诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["妾失鴛鴦伴，君方萍梗遊。","少年懽醉後，只恐苦相留。"]', '["妾失鴛鴦伴，君方萍梗游。","少年懽醉後，只恐苦相留。"]', '诗', 'shi', '', NULL, '孫長史女與焦封贈荅詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c3e4908-43d7-41e0-9fd9-bbc71cf3d9de', '孫長史女與焦封贈荅詩 二', '孫长史女與焦封贈荅诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["心常名宦外，終不恥狂遊。","誤入桃源裏，仙家爭肯留。"]', '["心常名宦外，終不恥狂游。","誤入桃源裏，仙家爭肯留。"]', '诗', 'shi', '', NULL, '孫長史女與焦封贈荅詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a82470c7-9c10-4acc-9cd6-9f8ea39dc549', '孫長史女與焦封贈荅詩 三', '孫长史女與焦封贈荅诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鵲橋織女會，也是不多時。","今日送君處，羞言連理枝。"]', '["鵲橋织女會，也是不多时。","今日送君处，羞言連理枝。"]', '诗', 'shi', '', NULL, '孫長史女與焦封贈荅詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56e2f071-8c26-4bf0-9e66-104d61c3b061', '孫長史女與焦封贈荅詩 四', '孫长史女與焦封贈荅诗 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["但保同心結，無勞織錦詩。","蘇秦求富貴，自有一回時。"]', '["但保同心結，無勞织錦诗。","蘇秦求富貴，自有一回时。"]', '诗', 'shi', '', NULL, '孫長史女與焦封贈荅詩 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b283827a-cc1d-4dda-8409-f63c55264f1a', '石甕寺燈魅詩 一', '石甕寺灯魅诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["涼風暮起驪山空，長生殿鏁霜葉紅。","朝來試入華清宮，分明憶得開元中。"]', '["涼风暮起驪山空，长生殿鏁霜葉紅。","朝来試入华清宮，分明憶得开元中。"]', '诗', 'shi', '', NULL, '石甕寺燈魅詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca50f017-b4ff-43d8-9269-feaf97f18a74', '石甕寺燈魅詩 二', '石甕寺灯魅诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["金殿不勝秋，月斜石樓冷。","誰是相顧人，褰帷弔孤影。"]', '["金殿不勝秋，月斜石楼冷。","誰是相顧人，褰帷弔孤影。"]', '诗', 'shi', '', NULL, '石甕寺燈魅詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0dde1ca-388c-4dda-8563-cddb089eba7b', '石甕寺燈魅詩 三', '石甕寺灯魅诗 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["煙滅石樓空，悠悠永夜中。","虛心怯秋雨，豔質畏飄風。","向壁殘花碎，侵堦墜葉紅。","還如失羣鶴，飲恨在雕籠。"]', '["煙滅石楼空，悠悠永夜中。","虛心怯秋雨，豔質畏飄风。","向壁殘花碎，侵堦墜葉紅。","還如失羣鹤，饮恨在雕籠。"]', '诗', 'shi', '', NULL, '石甕寺燈魅詩 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('65f422fe-8fd0-4d24-bb9e-f434abb97ebb', '洛下女郎歌 一', '洛下女郎歌 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["皎潔玉顏勝白雪，況乃當年對風月。","沈吟不敢怨春風，自歎容華暗消歇。"]', '["皎潔玉顏勝白雪，況乃當年对风月。","沈吟不敢怨春风，自歎容华暗消歇。"]', '诗', 'shi', '', NULL, '洛下女郎歌 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2de96d93-760f-4249-bc09-b34c418f73bc', '洛下女郎歌 二', '洛下女郎歌 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["絳衣披拂露盈盈，淡染胭脂一朵輕。","自恨紅顏留不住，莫怨春風道薄情。"]', '["絳衣披拂露盈盈，淡染胭脂一朵轻。","自恨紅顏留不住，莫怨春风道薄情。"]', '诗', 'shi', '', NULL, '洛下女郎歌 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d734ba3-0c76-479a-96c8-296aa8c61f32', '袁長官女詩 一', '袁长官女诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["彼見是忘憂，此看同腐草。","青山與白雲，方展我懷抱。"]', '["彼见是忘憂，此看同腐草。","青山與白云，方展我懷抱。"]', '诗', 'shi', '', NULL, '袁長官女詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba152647-95b9-414a-bb91-561f6f0c35ba', '袁長官女詩 二', '袁长官女诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["剛被恩情役此心，無端變化幾湮沈。","不知逐伴歸山去，長笑一聲煙霧深。"]', '["剛被恩情役此心，無端变化幾湮沈。","不知逐伴归山去，长笑一声煙霧深。"]', '诗', 'shi', '', NULL, '袁長官女詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e6f954-bf47-471a-a245-eae592537e8d', '真符女與申屠澄贈和詩 一', '真符女與申屠澄贈和诗 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["一尉慙梅福，三年媿孟光。","此情何所喻，川上有鴛鴦。"]', '["一尉慙梅福，三年媿孟光。","此情何所喻，川上有鴛鴦。"]', '诗', 'shi', '', NULL, '真符女與申屠澄贈和詩 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed5b7b0c-5cc3-4dc2-b536-6a0f8b48f269', '真符女與申屠澄贈和詩 二', '真符女與申屠澄贈和诗 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["琴瑟情雖重，山林志自深。","常憂時節變，辜負百年心。"]', '["琴瑟情雖重，山林志自深。","常憂时節变，辜負百年心。"]', '诗', 'shi', '', NULL, '真符女與申屠澄贈和詩 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('083bb041-6302-4365-9743-eccfc4ccf9ce', '夭桃詩', '夭桃诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鉛華久御向人間，欲捨鉛華更慘顏。","縱有青丘吟夜月，無因重照舊雲鬟。"]', '["鉛华久御向人间，欲捨鉛华更慘顏。","縱有青丘吟夜月，無因重照旧云鬟。"]', '诗', 'shi', '', NULL, '夭桃詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1075f485-50a9-4b32-a284-3a75f012ceb4', '青衣春條詩', '青衣春條诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["幽室鎖妖豔，無人蘭蕙芳。","春風三十載，不盡羅衣香。"]', '["幽室鎖妖豔，無人蘭蕙芳。","春风三十載，不尽羅衣香。"]', '诗', 'shi', '', NULL, '青衣春條詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a158ad04-05f8-4ab6-aa73-2eac1270cc17', '明器婢詩', '明器婢诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["獨持巾櫛掩玄關，小帳無人燭影殘。","昔日羅衣今化盡，白楊風起隴頭寒。"]', '["独持巾櫛掩玄关，小帳無人燭影殘。","昔日羅衣今化尽，白楊风起隴头寒。"]', '诗', 'shi', '', NULL, '明器婢詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85734c17-231e-43a5-8915-4d6ce508ac4e', '妙香詞', '妙香词', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["勸君酒莫辭，花落拋舊枝。","只有北邙山下月，清光到死也相隨。"]', '["勸君酒莫辞，花落拋旧枝。","只有北邙山下月，清光到死也相隨。"]', '诗', 'shi', '', NULL, '妙香詞 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3917850f-512c-4ec4-8679-11b61aff3b0b', '廬山女贈朱朴 一', '廬山女贈朱朴 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["但持冰潔心，不識風霜冷。","任是懷禮容，無人顧形影。"]', '["但持冰潔心，不識风霜冷。","任是懷禮容，無人顧形影。"]', '诗', 'shi', '', NULL, '廬山女贈朱朴 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4eec8f5c-7b64-47e1-a2cd-7548f5801bd3', '廬山女贈朱朴 二', '廬山女贈朱朴 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["知君久積池塘夢，遣我方思變動來。","操執若同顏叔子，今宵寧免淚盈顋。"]', '["知君久積池塘梦，遣我方思变动来。","操執若同顏叔子，今宵寧免泪盈顋。"]', '诗', 'shi', '', NULL, '廬山女贈朱朴 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f13ccd7-450d-44df-8157-53da39cf9da2', '青蘿帳女贈穆郎', '青蘿帳女贈穆郎', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["團圓今夕色光輝，結了同心翠帶垂。","此後莫教塵點染，他年長照歲寒姿。"]', '["團圓今夕色光輝，結了同心翠带垂。","此後莫教塵点染，他年长照歲寒姿。"]', '诗', 'shi', '', NULL, '青蘿帳女贈穆郎 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('832a400e-8878-401c-a250-d2b4a29c147c', '青蘿帳女贈穆郎 褰帳', '青蘿帳女贈穆郎 褰帳', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["揉藍綠色麴塵開，靜見三星入坐來。","桂影已圓攀折後，子孫長作棟梁材。"]', '["揉藍綠色麴塵开，静见三星入坐来。","桂影已圓攀折後，子孫长作棟梁材。"]', '诗', 'shi', '', NULL, '青蘿帳女贈穆郎 褰帳 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ef184f-fe89-4e2d-a041-05d4282d112c', '青蘿帳女贈穆郎 題碧花牋', '青蘿帳女贈穆郎 題碧花牋', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["珠露素中書繾綣，青蘿帳裏寄鴛鴦。","自憐孤影清秋夕，灑淚裴回滴冷光。"]', '["珠露素中书繾綣，青蘿帳裏寄鴛鴦。","自怜孤影清秋夕，灑泪裴回滴冷光。"]', '诗', 'shi', '', NULL, '青蘿帳女贈穆郎 題碧花牋 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7acc1c4c-bc11-42c8-bdae-5c162c918018', '白蘋洲碧衣女子吟', '白蘋洲碧衣女子吟', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["碧水色堪染，白蓮香正濃。","分飛俱有恨，此別幾時逢。","藕隱玲瓏玉，花藏縹緲容。","何當假雙翼，聲影暫相從。"]', '["碧水色堪染，白蓮香正濃。","分飞俱有恨，此別幾时逢。","藕隐玲瓏玉，花藏縹緲容。","何當假雙翼，声影暫相從。"]', '诗', 'shi', '', NULL, '白蘋洲碧衣女子吟 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('86b8346e-2c20-4395-9921-f0c915658a92', '新林驛女吟示歐陽訓', '新林驛女吟示歐陽訓', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月明階悄悄，影隻腰身小。","誰是鶱翔人，願爲比翼鳥。"]', '["月明階悄悄，影隻腰身小。","誰是鶱翔人，願爲比翼鸟。"]', '诗', 'shi', '', NULL, '新林驛女吟示歐陽訓 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9627bc46-36fa-4781-bd99-7b35ad84f967', '新林驛女吟示歐陽訓 擊盤歌送歐陽訓酒', '新林驛女吟示歐陽訓 擊盤歌送歐陽訓酒', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["飛燕身輕未是輕，枉將弱質在巖扃。","今來不得同鴛枕，相伴神魂入杳冥。"]', '["飞燕身轻未是轻，枉將弱質在巖扃。","今来不得同鴛枕，相伴神魂入杳冥。"]', '诗', 'shi', '', NULL, '新林驛女吟示歐陽訓 擊盤歌送歐陽訓酒 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50abcf72-68f3-4f67-b83b-b2097f1d50d3', '白衣女子木葉上詩', '白衣女子木葉上诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桃花洞口開，香蘂落莓苔。","佳景雖堪翫，蕭郎殊未來。"]', '["桃花洞口开，香蘂落莓苔。","佳景雖堪翫，蕭郎殊未来。"]', '诗', 'shi', '', NULL, '白衣女子木葉上詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('263a7f05-f019-491d-8e58-83331ec38244', '白衣女子木葉上詩 席上歌', '白衣女子木葉上诗 席上歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["洞府深沈春日長，山花無主自芬芳。","凭闌寂寂看明月，欲種桃花待阮郎。"]', '["洞府深沈春日长，山花無主自芬芳。","凭闌寂寂看明月，欲種桃花待阮郎。"]', '诗', 'shi', '', NULL, '白衣女子木葉上詩 席上歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7c12f7-d6f1-4311-86ea-474cdbe398eb', '鳳皇臺怪和歌四首 一', '鳳皇台怪和歌四首 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["深閨閑鎖難成夢，那得同衾共繡牀。","一自與郎江上別，霜天更自覺宵長。"]', '["深閨闲鎖难成梦，那得同衾共繡牀。","一自與郎江上別，霜天更自覺宵长。"]', '诗', 'shi', '', NULL, '鳳皇臺怪和歌四首 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e6d6661-bc83-43e9-9690-f369496bdcaf', '鳳皇臺怪和歌四首 二', '鳳皇台怪和歌四首 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["愁聽黃鶯喚友聲，空閨曙色夢初成。","窗間總有花牋紙，難寄妾心字字明。"]', '["愁听黄鶯喚友声，空閨曙色梦初成。","窗间總有花牋紙，难寄妾心字字明。"]', '诗', 'shi', '', NULL, '鳳皇臺怪和歌四首 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21b4db81-318b-4684-b6c0-5c87c06c58e0', '鳳皇臺怪和歌四首 三', '鳳皇台怪和歌四首 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["寂靜璇閨度歲年，竝頭蓮葉又如錢。","愁人獨處那堪此，安得君來獨枕眠。"]', '["寂静璇閨度歲年，竝头蓮葉又如錢。","愁人独处那堪此，安得君来独枕眠。"]', '诗', 'shi', '', NULL, '鳳皇臺怪和歌四首 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec2e8459-6da4-4a6f-9466-edcdf3630133', '鳳皇臺怪和歌四首 四', '鳳皇台怪和歌四首 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["臥病匡牀香屢添，夜深猶有一絲煙。","懷君無計能成夢，更恨砧聲到枕邊。"]', '["臥病匡牀香屢添，夜深猶有一絲煙。","懷君無計能成梦，更恨砧声到枕邊。"]', '诗', 'shi', '', NULL, '鳳皇臺怪和歌四首 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6732b2dc-449f-4fae-93ef-48379963e669', '夢丹書', '梦丹书', 'f1ceb7cd-3ecb-4ff2-88e0-872e9298f6e6', '唐', '["厥不云乎，惟其惟時。","上天所保，福祿不虧。"]', '["厥不云乎，惟其惟时。","上天所保，福祿不虧。"]', '诗', 'shi', '', NULL, '夢丹書 肅宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb96429f-19e0-4d34-aa00-a1e3f586cb37', '夢黃衣童子歌', '梦黄衣童子歌', '582443c3-3212-4760-abea-6a5c67b7ee4b', '唐', '["中五之德方峨峨，胡胡呼呼何奈何。"]', '["中五之德方峨峨，胡胡呼呼何奈何。"]', '诗', 'shi', '', NULL, '夢黃衣童子歌 代宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50e5dcaf-4519-4191-b3fe-a8cf1cadb302', '夢揚州樂妓和詩', '梦揚州乐妓和诗', '6202bbb8-ed35-45f7-aaa1-cef518a65b6b', '唐', '["花作嬋娟玉作妝，風流爭似舊徐娘。","夜深曲曲灣灣月，萬里隨君一寸腸。"]', '["花作嬋娟玉作妝，风流爭似旧徐娘。","夜深曲曲灣灣月，万里隨君一寸腸。"]', '诗', 'shi', '', NULL, '夢揚州樂妓和詩 劉禹錫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31a93f0b-e4c8-4bf1-a7f6-a04903a159ad', '夢中美人歌', '梦中美人歌', 'd16aaa42-fc19-49cc-af0a-8c7523fbb6e3', '唐', '["長安少女踏春陽，何處春陽不斷腸？舞袖弓彎渾忘却，羅衣空換九秋霜。"]', '["长安少女踏春陽，何处春陽不斷腸？舞袖弓彎渾忘却，羅衣空換九秋霜。"]', '诗', 'shi', '', NULL, '夢中美人歌 邢鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d77cd87d-1535-457d-a9d7-1c978292b67a', '夢中詩', '梦中诗', 'ff51461b-5680-42e4-afca-ad2fe0b1a9f6', '唐', '["聳轡排金闕，乘軒上漢槎。","浮名何足戀，高舉入煙霞。"]', '["聳轡排金闕，乘軒上漢槎。","浮名何足戀，高舉入煙霞。"]', '诗', 'shi', '', NULL, '夢中詩 石季武 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b500309-2aff-43c5-95e3-7b58e4f527ac', '葬西施挽歌', '葬西施挽歌', '2ec3ee00-9977-485c-b7f3-457458e18ce6', '唐', '["西望吳王國，雲書鳳字牌。","連江起珠帳，擇地葬金釵。","滿地紅心草，三層碧玉階。","春風無處所，悽恨不勝懷。"]', '["西望吳王国，云书鳳字牌。","連江起珠帳，擇地葬金釵。","满地紅心草，三層碧玉階。","春风無处所，悽恨不勝懷。"]', '诗', 'shi', '', NULL, '葬西施挽歌 王炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8006fc56-8f6e-4f87-a8d1-463632c8b3db', '秦夢詩三首 一', '秦梦诗三首 一', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["泣葬一枝紅，生同死不同。","金鈿墜芳草，香繡滿春風。","舊日聞簫處，高樓當月中。","梨花寒食夜，深閉翠微宮。"]', '["泣葬一枝紅，生同死不同。","金鈿墜芳草，香繡满春风。","旧日闻簫处，高楼當月中。","梨花寒食夜，深閉翠微宮。"]', '诗', 'shi', '', NULL, '秦夢詩三首 一 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('518c5bb0-46ca-4937-bb3c-521419f7d84e', '秦夢詩三首 二', '秦梦诗三首 二', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["擊髆舞，恨滿煙光無處所。","淚如雨，欲擬著辭不成語。","金鳳銜紅舊繡衣，幾度宮中同看舞。","人間春日正歡樂，日暮東風何處去。"]', '["擊髆舞，恨满煙光無处所。","泪如雨，欲擬著辞不成語。","金鳳銜紅旧繡衣，幾度宮中同看舞。","人间春日正歡乐，日暮东风何处去。"]', '诗', 'shi', '', NULL, '秦夢詩三首 二 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c0135625-b581-4537-9dc8-7281af2b4273', '秦夢詩三首 三', '秦梦诗三首 三', '7340b3f7-b51a-4c42-86bc-cb8c1fa06bc1', '唐', '["君王多感放東歸，從此秦宮不復期。","春景似傷秦喪主，落花如雨淚燕脂。"]', '["君王多感放东归，從此秦宮不复期。","春景似傷秦喪主，落花如雨泪燕脂。"]', '诗', 'shi', '', NULL, '秦夢詩三首 三 沈亞之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('51b1fb56-a714-4666-9fb4-939d90464ca0', '夢中詩', '梦中诗', 'd8074d20-3bc0-4995-8261-891b3d6dd290', '唐', '["卜築郊原古，青山無四鄰。","扶疎遶屋樹，寂寞獨歸人。"]', '["卜築郊原古，青山無四鄰。","扶疎遶屋樹，寂寞独归人。"]', '诗', 'shi', '', NULL, '夢中詩 盧獻卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0875b11-a161-49cc-9bda-6a5337996edf', '夢爲吳泰伯作勝兒歌', '梦爲吳泰伯作勝兒歌', '1c9134e0-5501-494b-b5cd-7395f7746a9c', '唐', '["繁弦已停雜吹歇，勝兒調弄邏娑撥。","四弦攏撚三五聲，喚起邊風駐明月。","大聲嘈嘈奔淈淈，浪蹙波翻倒溟渤。","小弦切切怨颸颸，鬼哭神悲秋窸窣。","倒腕斜挑摯流電，春雷直戛騰秋鶻。","漢妃徒得端正名，秦女虛誇有仙骨。","我聞天寶十年前，涼州未作西戎窟。","麻衣右衽皆漢民，不省胡塵暫蓬勃。","太平之末狂胡亂，犬豕崩騰恣唐突。","玄宗未到萬里橋，東洛西京一時沒。","漢土民皆沒爲虜，飲恨吞聲空嗢咽。","時看漢月望漢天，怨氣衝星成彗孛。","國門之西八九鎮，高城深壘閉閑卒。","河湟咫尺不能收，輓粟推車徒兀兀。","今朝聞奏涼州曲，使我心神暗超忽。","勝兒若向邊塞彈，征人淚血應闌干。"]', '["繁弦已停杂吹歇，勝兒調弄邏娑撥。","四弦攏撚三五声，喚起邊风駐明月。","大声嘈嘈奔淈淈，浪蹙波翻倒溟渤。","小弦切切怨颸颸，鬼哭神悲秋窸窣。","倒腕斜挑摯流電，春雷直戛腾秋鶻。","漢妃徒得端正名，秦女虛誇有仙骨。","我闻天寶十年前，涼州未作西戎窟。","麻衣右衽皆漢民，不省胡塵暫蓬勃。","太平之末狂胡亂，犬豕崩腾恣唐突。","玄宗未到万里橋，东洛西京一时沒。","漢土民皆沒爲虜，饮恨吞声空嗢咽。","时看漢月望漢天，怨氣衝星成彗孛。","国门之西八九鎮，高城深壘閉闲卒。","河湟咫尺不能收，輓粟推车徒兀兀。","今朝闻奏涼州曲，使我心神暗超忽。","勝兒若向邊塞彈，征人泪血應闌干。"]', '诗', 'shi', '', NULL, '夢爲吳泰伯作勝兒歌 劉景復 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0290882c-a58a-42c6-a885-adc856521bc3', '夢中辭', '梦中辞', '79cefbbc-26ab-4b68-9879-0dda600f48d1', '唐', '["飄風暴雨可思惟，鶴望巢門歛翅飛，吾道之宗正可依。"]', '["飄风暴雨可思惟，鹤望巢门歛翅飞，吾道之宗正可依。"]', '诗', 'shi', '', NULL, '夢中辭 郭仁表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aaa35a16-6b58-44c9-b85a-f43d701e4f4b', '夢崔嘏妻詩', '梦崔嘏妻诗', '71019ab6-6515-4998-b84f-03e33c878796', '唐', '["莫以真留妾，從他理管弦。","容華難久駐，知得幾多年。"]', '["莫以真留妾，從他理管弦。","容华难久駐，知得幾多年。"]', '诗', 'shi', '', NULL, '夢崔嘏妻詩 國邵南 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('836fe1c0-1ada-4158-8669-378e166e6347', '夢白衣婦人歌詞 一', '梦白衣婦人歌词 一', '36e05089-875a-4cba-bb82-c82d2614de7e', '唐', '["玉京人去秋簫索，畫簷鵲起梧桐落。","欹枕悄無言，月和殘夢圓。","背燈惟暗泣，甚處碪聲急。","眉黛小山攢，芭蕉生暮寒。"]', '["玉京人去秋簫索，畫簷鵲起梧桐落。","欹枕悄無言，月和殘梦圓。","背灯惟暗泣，甚处碪声急。","眉黛小山攢，芭蕉生暮寒。"]', '诗', 'shi', '', NULL, '夢白衣婦人歌詞 一 盧絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('798c2db1-a126-4f31-bd61-fed5d6e87026', '夢白衣婦人歌詞 二', '梦白衣婦人歌词 二', '36e05089-875a-4cba-bb82-c82d2614de7e', '唐', '["清風明月夜深時，箕箒盧郎恨已遲。","他日孟家坡上約，再來相見是佳期。"]', '["清风明月夜深时，箕箒盧郎恨已遲。","他日孟家坡上約，再来相见是佳期。"]', '诗', 'shi', '', NULL, '夢白衣婦人歌詞 二 盧絳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98368183-d8a9-4d4b-a45b-c6fbbaea78e1', '夢舜撫琴歌', '梦舜撫琴歌', '1b407a6a-f2d4-4afa-a542-f0e406018b6b', '唐', '["南風薰薰兮草芊芊，妙有之音兮歸清弦。","蕩蕩之教兮由自然，熈熈之化兮吾道全，薰薰兮思何傳。"]', '["南风薰薰兮草芊芊，妙有之音兮归清弦。","蕩蕩之教兮由自然，熈熈之化兮吾道全，薰薰兮思何傳。"]', '诗', 'shi', '', NULL, '夢舜撫琴歌 張生 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81693941-5773-4626-b828-65416b22ebd9', '夢康仙示詩', '梦康仙示诗', '38c5a8b9-3ddb-4718-ade2-15e10bfe8fe4', '唐', '["賣藥因循未得還，却因耽酒到人間。","有心只戀琵琶坂，無意更登山上山。"]', '["賣藥因循未得還，却因耽酒到人间。","有心只戀琵琶坂，無意更登山上山。"]', '诗', 'shi', '', NULL, '夢康仙示詩 漳郡守 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8f68f36e-80ab-45ae-bfe6-318ae1fbb473', '夢中歌', '梦中歌', '93fc8998-9f70-4683-991a-2191ee1d638b', '唐', '["今夕何夕，存耶沒耶。","良人去兮天之涯，園樹傷心兮三見花。"]', '["今夕何夕，存耶沒耶。","良人去兮天之涯，园樹傷心兮三见花。"]', '诗', 'shi', '', NULL, '夢中歌 獨孤遐叔妻白氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15f660ce-d6c6-48b1-a38c-787bc38874e6', '夢中歌 一', '梦中歌 一', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["歎衰草，絡緯聲切切。","良人一去不復還，今夕坐愁鬢如雪。"]', '["歎衰草，絡緯声切切。","良人一去不复還，今夕坐愁鬢如雪。"]', '诗', 'shi', '', NULL, '夢中歌 一 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f8a2d08-2a69-4f8a-86df-8bc7a677c157', '夢中歌 二', '梦中歌 二', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["勸君酒，君莫辭。","落花徒繞枝，流水無返期。"]', '["勸君酒，君莫辞。","落花徒繞枝，流水無返期。"]', '诗', 'shi', '', NULL, '夢中歌 二 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e315b31-af38-4361-8147-571ee2cde3c5', '夢中歌 三', '梦中歌 三', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["怨空閨，秋日亦難暮。","夫壻斷音書，遙天鴈空度。"]', '["怨空閨，秋日亦难暮。","夫壻斷音书，遙天鴈空度。"]', '诗', 'shi', '', NULL, '夢中歌 三 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('100e82db-454f-48fd-8f2d-2862c0d8b89e', '夢中歌 四', '梦中歌 四', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["切切夕風急，露滋庭草濕。","良人去不回，焉知掩閨泣。"]', '["切切夕风急，露滋庭草濕。","良人去不回，焉知掩閨泣。"]', '诗', 'shi', '', NULL, '夢中歌 四 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6308ad2-713e-4866-a3ae-776ffb5ff69c', '夢中歌 五', '梦中歌 五', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["螢火穿白楊，悲風入荒草。","疑是夢中遊，愁迷故園道。"]', '["螢火穿白楊，悲风入荒草。","疑是梦中游，愁迷故园道。"]', '诗', 'shi', '', NULL, '夢中歌 五 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d5d5a9d-ab75-4ad0-88ff-d14cb6536d5e', '夢中歌 六', '梦中歌 六', '14b07fce-39c4-4a7e-a800-5ecd809674c8', '唐', '["花前始相見，花下又相送。","何必言夢中，人生盡如夢。"]', '["花前始相见，花下又相送。","何必言梦中，人生尽如梦。"]', '诗', 'shi', '', NULL, '夢中歌 六 張生妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4340ea4-f288-4ab2-9085-feee0fcfe948', '夢王尚書口授吟', '梦王尚书口授吟', 'd1a47c0c-7c3d-428e-9511-aeea81e92e00', '唐', '["鬟梳鬧掃學宮妝，獨立閑庭納夜涼。","手把玉簪敲砌竹，清歌一曲月如霜。"]', '["鬟梳鬧掃学宮妝，独立闲庭納夜涼。","手把玉簪敲砌竹，清歌一曲月如霜。"]', '诗', 'shi', '', NULL, '夢王尚書口授吟 張氏女 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92827562-54bf-4aa0-8db0-1ccb15c93a01', '歌 一', '歌 一', '1b9a9835-b94a-47aa-a241-7db38d4ca720', '唐', '["踏陽春，人間三月雨和塵。","陽春踏，秋風起，腸斷人間白髮人。"]', '["踏陽春，人间三月雨和塵。","陽春踏，秋风起，腸斷人间白髮人。"]', '诗', 'shi', '', NULL, '歌 一 病狂人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28122823-f99f-49a0-a7b1-b2019a77a36a', '歌 二', '歌 二', '1b9a9835-b94a-47aa-a241-7db38d4ca720', '唐', '["五靈華，曉玲瓏，天府由來汝府中。","惆悵此情言不盡，一丸蘿蔔火吾宮。"]', '["五靈华，晓玲瓏，天府由来汝府中。","惆悵此情言不尽，一丸蘿蔔火吾宮。"]', '诗', 'shi', '', NULL, '歌 二 病狂人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('597f9b00-dbab-49ac-b9a4-38e7ea891af0', '題禪窟蘭若', '題禪窟蘭若', '9c987a0e-c7a8-4d0c-b4b9-d50fb007ef81', '唐', '["霜鐘鳴時夕風急，亂鴉又望寒林集。","此時輟櫂悲且吟，獨向蓮華一峰立。"]', '["霜鐘鳴时夕风急，亂鴉又望寒林集。","此时輟櫂悲且吟，独向蓮华一峰立。"]', '诗', 'shi', '', NULL, '題禪窟蘭若 陳季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e95b166d-5bbc-4c13-9b3f-dd0382ee6435', '題潼關普通院門', '題潼关普通院门', '9c987a0e-c7a8-4d0c-b4b9-d50fb007ef81', '唐', '["度關悲失志，萬緒亂心機。","下坂馬無力，掃門塵滿衣。","計謀多不就，心口自相違。","已作羞歸計，還勝羞不歸。"]', '["度关悲失志，万緒亂心機。","下坂马無力，掃门塵满衣。","計謀多不就，心口自相違。","已作羞归計，還勝羞不归。"]', '诗', 'shi', '', NULL, '題潼關普通院門 陳季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e46afb60-4162-47d7-8622-667cd957ebc3', '江亭晚望題書齋', '江亭晚望題书斋', '9c987a0e-c7a8-4d0c-b4b9-d50fb007ef81', '唐', '["立向江亭滿目愁，十年前事信悠悠。","田園已逐浮雲散，鄉里半隨逝水流。","川上莫逢諸釣叟，浦邊難得舊沙鷗。","不緣齒發未遲暮，吟對遠山堪白頭。"]', '["立向江亭满目愁，十年前事信悠悠。","田园已逐浮云散，乡里半隨逝水流。","川上莫逢諸釣叟，浦邊难得旧沙鷗。","不緣齒發未遲暮，吟对远山堪白头。"]', '诗', 'shi', '', NULL, '江亭晚望題書齋 陳季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d151bde-42b8-4e4d-8ed8-e3f1d47a8d27', '別妻', '別妻', '9c987a0e-c7a8-4d0c-b4b9-d50fb007ef81', '唐', '["月斜寒露白，此夕去留心。","酒至添愁飲，詩成和淚吟。","離歌悽鳳管，別鶴怨瑤琴。","明夜相思處，秋風吹半衾。"]', '["月斜寒露白，此夕去留心。","酒至添愁饮，诗成和泪吟。","離歌悽鳳管，別鹤怨瑤琴。","明夜相思处，秋风吹半衾。"]', '诗', 'shi', '', NULL, '別妻 陳季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45a02ed-ec8f-4516-9f36-c5d542cdeb87', '別兄弟', '別兄弟', '9c987a0e-c7a8-4d0c-b4b9-d50fb007ef81', '唐', '["謀身非不早，其奈命來遲。","舊友皆霄漢，此身猶路岐。","北風微雪後，晚景有雲時。","惆悵清江上，區區趁試期。"]', '["謀身非不早，其奈命来遲。","旧友皆霄漢，此身猶路岐。","北风微雪後，晚景有云时。","惆悵清江上，區區趁試期。"]', '诗', 'shi', '', NULL, '別兄弟 陳季卿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e77086-1ce8-433b-a28a-3e7fe95fc389', '夢中句', '梦中句', '6e4f10f8-6561-4c29-b044-a15912d8d6ee', '唐', '["紫髯之伴有丹砂。"]', '["紫髯之伴有丹砂。"]', '诗', 'shi', '', NULL, '夢中句 周延翰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2666126c-e959-4244-8de8-3eece65eec8d', '夢中和句', '梦中和句', 'd7bc362b-5eba-4e36-bd68-0a292a67d0c8', '唐', '["故國路遙歸去來，春風天遠望不盡。"]', '["故国路遙归去来，春风天远望不尽。"]', '诗', 'shi', '', NULL, '夢中和句 任玠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf6dd7ae-a2bc-4f6d-80cc-565192ae63d6', '夢中語', '梦中語', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["辭春不及秋，昆脚與皆頭。"]', '["辞春不及秋，昆脚與皆头。"]', '诗', 'shi', '', NULL, '夢中語 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e195121c-3ace-4c2c-968b-082772f9597b', '夢中詩', '梦中诗', '709d9a51-5ab1-4526-879d-860e9467aefd', '唐', '["昔作樹頭花，今爲塚中骨。"]', '["昔作樹头花，今爲塚中骨。"]', '诗', 'shi', '', NULL, '夢中詩 胥偃 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2b295157-55b9-4ef1-b480-d66d1e626e60', '夢中語', '梦中語', '99ee5743-3e58-4be5-bbe6-76d68577a535', '唐', '["田頭有鹿跡，由尾著日炙。"]', '["田头有鹿跡，由尾著日炙。"]', '诗', 'shi', '', NULL, '夢中語 曾崇範妻 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a57f658a-f9fe-44f0-bba4-5fb3666e8a56', '紀夢句', '紀梦句', '2965da63-c004-4441-951d-324aaf46e36c', '唐', '["上天知我憶其人，使向人間夢中見。"]', '["上天知我憶其人，使向人间梦中见。"]', '诗', 'shi', '', NULL, '紀夢句 張孜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e91b22e8-ba3f-4ecf-bab0-01f48a13fee1', '嘲蘇世長', '嘲蘇世长', 'e51343a0-ad45-4dfa-9232-11dd612512b3', '唐', '["名長意短，口正心邪。","棄忠貞於鄭國，忘信義於吾家。"]', '["名长意短，口正心邪。","棄忠貞於鄭国，忘信義於吾家。"]', '诗', 'shi', '', NULL, '嘲蘇世長 高祖 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e7923c1-27ba-4e95-bd7d-ed572fa60f8b', '戲題畫', '戲題畫', 'ff281831-d7c9-40aa-bab8-5a01cb2426a2', '唐', '["喚出眼，何用苦深藏。","縮却鼻，何畏不聞香。"]', '["喚出眼，何用苦深藏。","縮却鼻，何畏不闻香。"]', '诗', 'shi', '', NULL, '戲題畫 睿宗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8c40dac-d201-4bf5-80b2-a4c3e889b288', '嘲蕭瑀射', '嘲蕭瑀射', '34606369-a7ad-400f-aefc-c6b12375ac82', '唐', '["急風吹緩箭，弱手馭強弓。","欲高飜復下，應西還更東。","十迴俱著地，兩手幷擎空。","借問誰爲此，乃應是宋公。"]', '["急风吹緩箭，弱手馭強弓。","欲高飜复下，應西還更东。","十迴俱著地，兩手幷擎空。","借问誰爲此，乃應是宋公。"]', '诗', 'shi', '', NULL, '嘲蕭瑀射 歐陽詢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70652987-854b-46c9-ac28-36eae35702a0', '與歐陽詢互嘲 一', '與歐陽詢互嘲 一', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["聳膊成山字，埋肩不出頭。","誰家麟角上，畫此一獼猴。"]', '["聳膊成山字，埋肩不出头。","誰家麟角上，畫此一獼猴。"]', '诗', 'shi', '', NULL, '與歐陽詢互嘲 一 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c856a9b8-f782-4410-9439-86de2e9a8cb6', '與歐陽詢互嘲 二', '與歐陽詢互嘲 二', '534166ae-f81c-495a-85fd-2aba8c72b557', '唐', '["索頭連背暖，漫襠畏肚寒。","只因心渾渾，所以面團團。"]', '["索头連背暖，漫襠畏肚寒。","只因心渾渾，所以面團團。"]', '诗', 'shi', '', NULL, '與歐陽詢互嘲 二 長孫無忌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b7f111d9-7d30-4a69-920f-f55998e470b9', '爲溫僕射嘲竹', '爲溫僕射嘲竹', 'e88999a8-758e-460b-aaa9-8e261906879f', '唐', '["竹，風吹青肅肅，凌冬葉不凋，經春子不熟。","虚心未得待國士，皮上何湏生節目。"]', '["竹，风吹青肅肅，凌冬葉不凋，經春子不熟。","虚心未得待国士，皮上何湏生節目。"]', '诗', 'shi', '', NULL, '爲溫僕射嘲竹 裴略 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b104cf65-4ad6-4010-a19d-395125b685ee', '又嘲屏牆', '又嘲屏牆', 'e88999a8-758e-460b-aaa9-8e261906879f', '唐', '["高下八九尺，東西六七步。","突兀當廳坐，幾許遮賢路。"]', '["高下八九尺，东西六七步。","突兀當廳坐，幾許遮賢路。"]', '诗', 'shi', '', NULL, '又嘲屏牆 裴略 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59b057b4-f271-488a-b3f7-70a07ca537d0', '嘲崔左丞', '嘲崔左丞', '6e782660-56c2-4bbd-9f2a-42adb48095a6', '唐', '["崔子曲如鉤，隨例得封侯。","髆上全無項，胸前別有頭。"]', '["崔子曲如鉤，隨例得封侯。","髆上全無項，胸前別有头。"]', '诗', 'shi', '', NULL, '嘲崔左丞 省吏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c73fe42-22f2-4348-9e02-69b511867818', '嘲高士廉木履', '嘲高士廉木履', '32ceae89-45ac-49c4-9c3a-31eb263b2c44', '唐', '["刺鼻何曾嚏，蹋面不知嗔。","高生兩箇齒，自謂得勝人。"]', '["刺鼻何曾嚏，蹋面不知嗔。","高生兩箇齒，自謂得勝人。"]', '诗', 'shi', '', NULL, '嘲高士廉木履 選人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('01347646-dd39-47d2-8870-2fc1a11fc74c', '書化度藏院壁', '书化度藏院壁', '89171617-e2c4-4022-a7ad-b4a472038d15', '唐', '["將肉遣狼守，置骨向狗頭。","自非阿羅漢，焉能免得偷。"]', '["將肉遣狼守，置骨向狗头。","自非阿羅漢，焉能免得偷。"]', '诗', 'shi', '', NULL, '書化度藏院壁 裴玄智 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fae5cb13-5506-411c-a957-f3eee4b0f57d', '嘲許子儒', '嘲許子儒', '1a5f3c68-d99d-48cb-98f0-7bb3edea1498', '唐', '["不能專習禮，虛心強覓階。","一年辭爵弁，半歲履麻鞋。","瓦惡頻蒙𢸗，墻虛屢被扠。","映樹便側睡，過匱即放乖。","歲暮良工畢，言是越朋儕。","今日綸言降，方知愚計喎。"]', '["不能專習禮，虛心強覓階。","一年辞爵弁，半歲履麻鞋。","瓦惡頻蒙𢸗，墻虛屢被扠。","映樹便側睡，過匱即放乖。","歲暮良工畢，言是越朋儕。","今日綸言降，方知愚計喎。"]', '诗', 'shi', '', NULL, '嘲許子儒 竇昉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('104fd722-b3f4-4240-8b82-71b8e3f6fc49', '與趙神德互嘲', '與趙神德互嘲', '899c5640-9f21-4fad-af32-8caa299d0b3d', '唐', '["趙神德，天上既無雲，閃電何以無準則。","向者入門來，案後惟見一挺墨。","官裏料朱砂，半眼供一國。","磨公小拇指，塗得太社北。"]', '["趙神德，天上既無云，閃電何以無準則。","向者入门来，案後惟见一挺墨。","官裏料朱砂，半眼供一国。","磨公小拇指，塗得太社北。"]', '诗', 'shi', '', NULL, '與趙神德互嘲 梁寶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffe8b26f-8d79-466d-973c-9d8269e8e425', '與講師互謔', '與講師互謔', '56ca0fbf-6bb2-4fd0-86f4-12efa672240c', '唐', '["甘桃不結實，苦李壓低枝。","輪王千箇子，巷伯勿孫兒。"]', '["甘桃不結實，苦李壓低枝。","輪王千箇子，巷伯勿孫兒。"]', '诗', 'shi', '', NULL, '與講師互謔 釋元康 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('463f6093-4493-495e-99cc-f2c034c8c874', '詠興善寺佛殿災', '詠兴善寺佛殿災', 'b0af6032-eace-4680-aa38-7df769572965', '唐', '["道善何曾善，言興且不興。","如來燒赤盡，惟有一羣僧。"]', '["道善何曾善，言兴且不兴。","如来燒赤尽，惟有一羣僧。"]', '诗', 'shi', '', NULL, '詠興善寺佛殿災 李榮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8d51deb0-399b-4ee2-8288-56f650ee7e9b', '敘可笑事', '敘可笑事', '99522a20-f4b4-4cbe-9cb0-b4e7445f0c18', '唐', '["朱前疑著綠，逯仁傑著朱。","閻知微騎馬，馬吉甫騎驢。","將名作姓李千里，將姓作名吳栖梧。","左臺胡御史，右臺御史胡。"]', '["朱前疑著綠，逯仁傑著朱。","閻知微騎马，马吉甫騎驢。","將名作姓李千里，將姓作名吳栖梧。","左台胡御史，右台御史胡。"]', '诗', 'shi', '', NULL, '敘可笑事 張元一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b105b34b-bfa9-4d35-b307-f5e90a3d7740', '嘲武懿宗', '嘲武懿宗', '99522a20-f4b4-4cbe-9cb0-b4e7445f0c18', '唐', '["長弓短度箭，蜀馬臨階騗。","去賊七百里，隈墻獨自戰。","忽然逢著賊，騎豬向南𧾩。"]', '["长弓短度箭，蜀马臨階騗。","去賊七百里，隈墻独自戰。","忽然逢著賊，騎豬向南𧾩。"]', '诗', 'shi', '', NULL, '嘲武懿宗 張元一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42fa29ca-dafd-4616-90f0-da2f1b802955', '又嘲武懿宗', '又嘲武懿宗', '99522a20-f4b4-4cbe-9cb0-b4e7445f0c18', '唐', '["裹頭極草草，掠鬢不菶菶。","未見桃花面皮，漫作杏子眼孔。"]', '["裹头極草草，掠鬢不菶菶。","未见桃花面皮，漫作杏子眼孔。"]', '诗', 'shi', '', NULL, '又嘲武懿宗 張元一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('278596d5-b47a-4379-9429-2b98a732ad40', '詠靜樂縣主', '詠静乐縣主', '99522a20-f4b4-4cbe-9cb0-b4e7445f0c18', '唐', '["馬帶桃花錦，帬銜綠草羅。","定知幃帽底，儀容似大哥。"]', '["马带桃花錦，帬銜綠草羅。","定知幃帽底，儀容似大哥。"]', '诗', 'shi', '', NULL, '詠靜樂縣主 張元一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('232e79ed-ed88-4110-a038-fc2dd71a5df2', '嘲格輔元', '嘲格輔元', 'eaf529fc-90b8-430a-847f-a4435a712301', '唐', '["有恥宿龍門，精彩先瞰渾。","眼瘦呈近店，睡響徹遙林。","埒囊將舊識，製被異新婚。","誰言驄馬使，飜作蟄熊蹲。"]', '["有恥宿龙门，精彩先瞰渾。","眼瘦呈近店，睡响徹遙林。","埒囊將旧識，製被異新婚。","誰言驄马使，飜作蟄熊蹲。"]', '诗', 'shi', '', NULL, '嘲格輔元 杜易簡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71c1a098-46fb-485f-9d19-d47361bef04b', '始平諧詩', '始平諧诗', '957b07dc-3610-48f7-ae0b-b81a07a31bff', '唐', '["平明發始平，薄暮至何城。","庫墖朝雲上，晃池夜月明。","略彴橋頭逢長史，櫺星門外揖司兵。","一羣縣尉驢騾驟，數箇參軍鵝鴨行。"]', '["平明發始平，薄暮至何城。","庫墖朝云上，晃池夜月明。","略彴橋头逢长史，櫺星门外揖司兵。","一羣縣尉驢騾驟，數箇參軍鵝鴨行。"]', '诗', 'shi', '', NULL, '始平諧詩 石抱忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c790ecf1-5730-493d-920f-fbc5a7b5b009', '詠傅巖監祠', '詠傅巖監祠', '79d1f996-23e6-451f-8f1b-ff1c3d8fe9e2', '唐', '["聞道監中霤，初言是大祠。","很傍索傳馬，𬾠動出安徽。","衛司無帟幕，供膳乏鮮肥。","形容消瘦盡，空往復空歸。"]', '["闻道監中霤，初言是大祠。","很傍索傳马，𬾠动出安徽。","衛司無帟幕，供膳乏鲜肥。","形容消瘦尽，空往复空归。"]', '诗', 'shi', '', NULL, '詠傅巖監祠 梁載言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61728213-0a86-4629-978c-bc36e755ba36', '嘲崔生', '嘲崔生', '3f9874af-5648-4cb3-ba3f-0473647c4e8b', '唐', '["崔生犯夜行，武候正嚴更。","幞頭拳下落，高髻掌中擎。","杖迹胸前出，繩文腕後生。","愁人不惜夜，隨意曉參橫。"]', '["崔生犯夜行，武候正嚴更。","幞头拳下落，高髻掌中擎。","杖迹胸前出，繩文腕後生。","愁人不惜夜，隨意晓參橫。"]', '诗', 'shi', '', NULL, '嘲崔生 劉行敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2eefd72c-00fc-40aa-a3da-2e9c53e5eb00', '又嘲楊文瓘', '又嘲楊文瓘', '3f9874af-5648-4cb3-ba3f-0473647c4e8b', '唐', '["武陵敬愛客，終宴不知疲。","遣共渾王飲，錯宴延陀兒。","始被鴻臚識，終蒙御史知。","精神既如此，長歎復何爲。"]', '["武陵敬愛客，終宴不知疲。","遣共渾王饮，錯宴延陀兒。","始被鴻臚識，終蒙御史知。","精神既如此，长歎复何爲。"]', '诗', 'shi', '', NULL, '又嘲楊文瓘 劉行敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a87ae15a-f618-4585-96c3-a23eff99e74d', '嘲李叔慎賀蘭僧伽杜善賢', '嘲李叔慎賀蘭僧伽杜善賢', '3f9874af-5648-4cb3-ba3f-0473647c4e8b', '唐', '["叔慎騎烏馬，僧伽把漆弓。","喚取長安令，共獵北山熊。"]', '["叔慎騎烏马，僧伽把漆弓。","喚取长安令，共獵北山熊。"]', '诗', 'shi', '', NULL, '嘲李叔慎賀蘭僧伽杜善賢 劉行敏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c8ab327a-94f5-4cd2-ac5c-118ce26089d1', '嘲父', '嘲父', 'fcbc29a8-b3b8-4449-8e4a-7c200ca1555b', '唐', '["陸餘慶，筆頭無力觜頭硬。","一朝受辭訟，十日判不竟。"]', '["陸餘慶，笔头無力觜头硬。","一朝受辞訟，十日判不竟。"]', '诗', 'shi', '', NULL, '嘲父 陸子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b26a219-0097-4fd7-9a3a-3ac3512e4582', '迴波詞', '迴波词', 'efc58c4b-af33-45cf-8906-87a6f9e045dc', '唐', '["迴波爾時廷玉，打獠取錢未足。","阿姑婆見作天子，傍人不得棖觸。"]', '["迴波爾时廷玉，打獠取錢未足。","阿姑婆见作天子，傍人不得棖觸。"]', '诗', 'shi', '', NULL, '迴波詞 楊廷玉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e15865c3-e43c-41d7-bc4e-7d625f37960a', '迴波詞', '迴波词', 'ce0703da-6a94-4d1c-8568-cd0cb5520350', '唐', '["迴波爾時栲栳，怕婦也是大好。","外邊祗有裴談，內里無過李老。"]', '["迴波爾时栲栳，怕婦也是大好。","外邊祗有裴談，內里無過李老。"]', '诗', 'shi', '', NULL, '迴波詞 中宗朝優人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6fe30e4c-25d1-437a-ade1-bc97d0add9e3', '乞金魚詞', '乞金鱼词', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["臺中鼠子直須諳，信足跳梁上壁龕。","倚飜燈脂汚張五，還來齧帶報韓三。","莫浪語，直王相，大家必若賜金龜，賣却貓兒相報賞。"]', '["台中鼠子直須諳，信足跳梁上壁龕。","倚飜灯脂汚張五，還来齧带報韓三。","莫浪語，直王相，大家必若賜金龟，賣却貓兒相報賞。"]', '诗', 'shi', '', NULL, '乞金魚詞 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c5d0b985-9e6a-4799-8a28-63623f119228', '又賜宴自歌', '又賜宴自歌', 'b93f3304-6cb5-42e4-923f-9928d32ae301', '唐', '["東館總是鵷鸞，南臺自多杞梓。","日用讀書萬卷，何忍不蒙學士。","墨制簾下出來，微臣眼看喜死。"]', '["东館總是鵷鸾，南台自多杞梓。","日用读书万卷，何忍不蒙学士。","墨制簾下出来，微臣眼看喜死。"]', '诗', 'shi', '', NULL, '又賜宴自歌 崔日用 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f51d8b7b-116e-42fb-88f3-d68b1888b378', '詠癡', '詠癡', '70cd5f1b-f55d-46c7-a2e0-f0222a19e4a9', '唐', '["榆兒復榆婦，造屋兼造車。","十七八九夜，還書復借書。"]', '["榆兒复榆婦，造屋兼造车。","十七八九夜，還书复借书。"]', '诗', 'shi', '', NULL, '詠癡 吳人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7d4caf45-52b5-4a97-bbb0-8fd7900fcb2b', '歇後', '歇後', '685dc8a9-a080-4235-9d4f-abce1bfe28b9', '唐', '["面作天地玄，鼻有雁門紫。","既無左達承，何勞罔談彼。"]', '["面作天地玄，鼻有雁门紫。","既無左達承，何勞罔談彼。"]', '诗', 'shi', '', NULL, '歇後 封抱一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('477ea2b0-981b-482c-986d-d4b4ed725539', '送司功入京', '送司功入京', 'c8d17d43-55b5-44d1-83a7-639ef9811dac', '唐', '["崇裕有幸會，得遇明流行。","司士向京去，曠野哭聲哀。"]', '["崇裕有幸會，得遇明流行。","司士向京去，曠野哭声哀。"]', '诗', 'shi', '', NULL, '送司功入京 麴崇裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcb52ce7-3cde-4b77-bdf8-ec58a5aebd1c', '嶺南歸後獻詩', '嶺南归後獻诗', 'dcb89911-6aea-4e2b-b254-d0776b244a60', '唐', '["龍褒有何罪，天恩放嶺南。","敕知無罪過，追來與將軍。"]', '["龙褒有何罪，天恩放嶺南。","敕知無罪過，追来與將軍。"]', '诗', 'shi', '', NULL, '嶺南歸後獻詩 權龍褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30543d11-40a3-473d-8c9c-004e05d05bc6', '初到滄州呈州官', '初到滄州呈州官', 'dcb89911-6aea-4e2b-b254-d0776b244a60', '唐', '["遙看滄海城，楊柳鬱青青。","中央一羣漢，聚坐打杯觥。"]', '["遙看滄海城，楊柳鬱青青。","中央一羣漢，聚坐打杯觥。"]', '诗', 'shi', '', NULL, '初到滄州呈州官 權龍褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5cb87ff-7aa7-4095-8274-ad6c9993b73c', '秋日述懷', '秋日述懷', 'dcb89911-6aea-4e2b-b254-d0776b244a60', '唐', '["檐前飛七百，雪白後園彊。","飽食房裏側，家糞集野蜋。"]', '["檐前飞七百，雪白後园彊。","飽食房裏側，家糞集野蜋。"]', '诗', 'shi', '', NULL, '秋日述懷 權龍褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00626b70-9005-4cf7-9e75-30972b6e1877', '喜雨', '喜雨', 'dcb89911-6aea-4e2b-b254-d0776b244a60', '唐', '["暗去也沒雨，明來也沒雲。","日頭赫赤出，地上綠氤氳。"]', '["暗去也沒雨，明来也沒云。","日头赫赤出，地上綠氤氳。"]', '诗', 'shi', '', NULL, '喜雨 權龍褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca065bd5-de7e-4b4a-8b65-53b5b973e6ac', '皇太子夏日賜宴詩', '皇太子夏日賜宴诗', 'dcb89911-6aea-4e2b-b254-d0776b244a60', '唐', '["嚴霜白浩浩，明月赤團團。"]', '["嚴霜白浩浩，明月赤團團。"]', '诗', 'shi', '', NULL, '皇太子夏日賜宴詩 權龍褒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77ee1a89-aed7-49e6-9b72-7cf6d6259780', '哭李嶠詩', '哭李嶠诗', '69486548-12a1-434b-926d-e5ea9b2bec01', '唐', '["臺閣神仙地，衣冠君子鄉。","昨朝猶對坐，今日忽云亡。","魂隨司命鬼，魄逐見閻王。","此時罷歡笑，無復向朝堂。"]', '["台閣神仙地，衣冠君子乡。","昨朝猶对坐，今日忽云亡。","魂隨司命鬼，魄逐见閻王。","此时罷歡笑，無复向朝堂。"]', '诗', 'shi', '', NULL, '哭李嶠詩 崔泰之 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a0848bc-da0e-4623-9dd0-0a6995e3feae', '詠尹字', '詠尹字', '93a2c850-c875-4649-8c16-96e884fbb99e', '唐', '["丑雖有足，甲不全身。","見君無口，知伊少人。"]', '["丑雖有足，甲不全身。","见君無口，知伊少人。"]', '诗', 'shi', '', NULL, '詠尹字 蘇頲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4436e5bd-a636-474f-b081-c188212be626', '詠王主敬', '詠王主敬', '60996138-e4e3-4185-8985-98d3b0f8ff26', '唐', '["有意嫌兵部，專心望考功。","誰知脚踜蹬，却落省牆東。"]', '["有意嫌兵部，專心望考功。","誰知脚踜蹬，却落省牆东。"]', '诗', 'shi', '', NULL, '詠王主敬 張敬忠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a172985-54b3-4388-953b-60ea0e16b42f', '嘲邵景蕭嵩', '嘲邵景蕭嵩', 'e488eb86-0fbb-4350-9dc9-6d7b9ddb722d', '唐', '["一雙胡子著緋袍，一箇鬚多一鼻高。","相對廳前捺且立，自慙身品世間毛。"]', '["一雙胡子著緋袍，一箇鬚多一鼻高。","相对廳前捺且立，自慙身品世间毛。"]', '诗', 'shi', '', NULL, '嘲邵景蕭嵩 韋鏗 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ae6672e-58e1-4c66-8e4d-91ba617c36bc', '嘲韋鏗', '嘲韋鏗', '7abd9667-1baa-4a31-906b-03a65de49c74', '唐', '["飄風忽起團團旋，倒地還如著脚䭔。","莫怪殿上空行事，却爲元非五品才。"]', '["飄风忽起團團旋，倒地還如著脚䭔。","莫怪殿上空行事，却爲元非五品才。"]', '诗', 'shi', '', NULL, '嘲韋鏗 邵景 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ac792b8c-adeb-4bde-9f9a-f962cfd54255', '詠毀天樞', '詠毀天樞', '877ec342-2b6b-4ca3-bd69-5ee7e408c179', '唐', '["天門街上倒天樞，火急先須卸火珠。","計合一條麻線挽，何勞兩縣索人夫。"]', '["天门街上倒天樞，火急先須卸火珠。","計合一條麻線挽，何勞兩縣索人夫。"]', '诗', 'shi', '', NULL, '詠毀天樞 李休烈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ec2a3cc-702b-4015-a9f9-ff0fbae6f7af', '與李全交詩', '與李全交诗', '064814c2-7cf4-4e6e-83f1-a46f69dccebf', '唐', '["御史非常任，參軍不久居。","待君遷轉後，此職還到余。"]', '["御史非常任，參軍不久居。","待君遷轉後，此職還到余。"]', '诗', 'shi', '', NULL, '與李全交詩 石惠泰 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94685790-d054-4585-b093-645d7141beaa', '嘲劉文樹', '嘲劉文樹', '17d1363c-fa51-4ff7-9231-53022aee07c8', '唐', '["可憐好箇劉文樹，髭鬚共頦頤別住。","文樹面孔不似猢猻，猢猻面孔強似文樹。"]', '["可怜好箇劉文樹，髭鬚共頦頤別住。","文樹面孔不似猢猻，猢猻面孔強似文樹。"]', '诗', 'shi', '', NULL, '嘲劉文樹 黃幡綽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b631320e-73fc-43f7-8d4d-3f9ac668d155', '尚書省門吟', '尚书省门吟', 'ad0c2f94-fc30-4693-aa87-4aeabcf876de', '唐', '["落去他，兩兩三三戴帽子。","日暮祖侯吟一聲，長安竹柏皆枯死。"]', '["落去他，兩兩三三戴帽子。","日暮祖侯吟一声，长安竹柏皆枯死。"]', '诗', 'shi', '', NULL, '尚書省門吟 祖詠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706a6715-b027-4a1e-acd6-3cc910974dd7', '上馬當山神', '上马當山神', 'a4a10e63-d822-47a6-9064-444a6d7a9ffa', '唐', '["青驄一匹崑崙牽，奏上大王不取錢。","直爲猛風波滾驟，莫怪昌齡不下船。"]', '["青驄一匹崑崙牽，奏上大王不取錢。","直爲猛风波滾驟，莫怪昌齡不下船。"]', '诗', 'shi', '', NULL, '上馬當山神 王昌齡 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84e07753-e67b-46d4-99d1-02e7b43341ca', '竊李義府詩', '竊李義府诗', 'b3652f50-0d3c-4620-b68a-8a34e424aa16', '唐', '["生情鏤月爲歌扇，出性裁雲作舞衣。","照鏡自憐迴雪影，來時好取洛川歸。"]', '["生情鏤月爲歌扇，出性裁云作舞衣。","照镜自怜迴雪影，来时好取洛川归。"]', '诗', 'shi', '', NULL, '竊李義府詩 張懷慶 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4fec622e-42ba-4f8e-951f-b6c3c1e89b91', '荅朝士', '荅朝士', '3379ae1d-ad39-42f1-aa77-0a168f065885', '唐', '["鈒鏤銀盤盛蛤蜊，鏡湖蓴菜亂如絲。","鄉曲近來佳此味，遮渠不道是吳兒。"]', '["鈒鏤銀盤盛蛤蜊，镜湖蓴菜亂如絲。","乡曲近来佳此味，遮渠不道是吳兒。"]', '诗', 'shi', '', NULL, '荅朝士 賀知章 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8568c12-f9f1-4a46-8ba2-01b7efecd580', '和知章詩', '和知章诗', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["鈒鏤銀盤盛炒鰕，鏡湖蓴菜亂如麻。","漢兒女嫁吳兒婦，吳兒盡是漢兒爺。"]', '["鈒鏤銀盤盛炒鰕，镜湖蓴菜亂如麻。","漢兒女嫁吳兒婦，吳兒尽是漢兒爺。"]', '诗', 'shi', '', NULL, '和知章詩 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef209680-bd61-4f71-84b2-64994e2e20a4', '續茅山秀才吟', '續茅山秀才吟', 'a6b9d980-d193-440f-9a68-9059e7de0b6e', '唐', '["駐馬上山阿，風來屎氣多。"]', '["駐马上山阿，风来屎氣多。"]', '诗', 'shi', '', NULL, '續茅山秀才吟 顧況 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e1edd84-b808-4f24-b79e-51f4d28987f1', '櫻桃子詩', '櫻桃子诗', '2efa768f-df91-4108-96f9-9a2a21c3e48c', '唐', '["櫻桃子，半赤半已黃。","一半與懷王，一半與周至。"]', '["櫻桃子，半赤半已黄。","一半與懷王，一半與周至。"]', '诗', 'shi', '', NULL, '櫻桃子詩 史思明 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e45731a3-8d0b-4a18-8fb0-c1cf57807d2c', '譏元載詩', '譏元載诗', '3fe8c9ca-ee29-4703-9f98-1613fc7d5947', '唐', '["上元官吏務剝削，江淮之人皆白著。"]', '["上元官吏務剝削，江淮之人皆白著。"]', '诗', 'shi', '', NULL, '譏元載詩 高亭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72cb7f32-233f-4647-af45-3fce77dd380e', '嘲趙謙光', '嘲趙謙光', 'd1b25f23-0c32-46de-8330-706a78f5371b', '唐', '["員外由來美，郎中望亦優。","寧知粉署裏，飜作土山頭。"]', '["員外由来美，郎中望亦優。","寧知粉署裏，飜作土山头。"]', '诗', 'shi', '', NULL, '嘲趙謙光 賀遂涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e3546170-8ec5-420c-a9b6-432ce63eb74e', '荅賀遂涉', '荅賀遂涉', '10579e24-8eb3-4878-8557-a2d1edc7ad4f', '唐', '["錦帳隨情設，金爐任意熏。","唯愁員外置，不應列星文。"]', '["錦帳隨情設，金爐任意熏。","唯愁員外置，不應列星文。"]', '诗', 'shi', '', NULL, '荅賀遂涉 趙謙光 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98d96fce-fb78-4dd9-b959-0e7785dc5f43', '上浙東孟尚書', '上浙东孟尚书', '7101a94e-b72d-49e8-a7ce-c821481c3f44', '唐', '["有箇將軍不得名，唯教健卒喝書生。","尚書近日清如鏡，天子官街不許行。"]', '["有箇將軍不得名，唯教健卒喝书生。","尚书近日清如镜，天子官街不許行。"]', '诗', 'shi', '', NULL, '上浙東孟尚書 孔顒 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('663a3af4-1d97-4908-b074-e464c3fc56da', '嘲柳州柳子厚', '嘲柳州柳子厚', '24bdea98-300c-4e5f-a9e7-223bea417588', '唐', '["柳州柳刺史，種柳柳江邊。","柳管依然在，千秋柳拂天。"]', '["柳州柳刺史，種柳柳江邊。","柳管依然在，千秋柳拂天。"]', '诗', 'shi', '', NULL, '嘲柳州柳子厚 呂溫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfcdd0c6-3836-4f46-9646-bdfa15b2323b', '嘲黔南觀察南卓', '嘲黔南观察南卓', '24bdea98-300c-4e5f-a9e7-223bea417588', '唐', '["終南南太守，南郡在雲南。","閑向南亭醉，南風變俗談。"]', '["終南南太守，南郡在云南。","闲向南亭醉，南风变俗談。"]', '诗', 'shi', '', NULL, '嘲黔南觀察南卓 呂溫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7268a30a-29ba-490f-8406-a9e9601fd770', '戲簡朱壇詩', '戲簡朱壇诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["昔人有玉盌，擊之千里鳴。","今日覩斯文，盌有當時聲。"]', '["昔人有玉盌，擊之千里鳴。","今日覩斯文，盌有當时声。"]', '诗', 'shi', '', NULL, '戲簡朱壇詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970a59a2-d0fe-427f-8aaa-976634ca8eae', '戲顏郎官騎獵詩', '戲顏郎官騎獵诗', '2fed37c6-3fb8-407e-8df8-4853a275e3f7', '唐', '["忽聞射獵出軍城，人著戎衣馬帶纓。","倒把角弓呈一箭，滿山狐兔當頭行。"]', '["忽闻射獵出軍城，人著戎衣马带纓。","倒把角弓呈一箭，满山狐兔當头行。"]', '诗', 'shi', '', NULL, '戲顏郎官騎獵詩 張祜 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e40419a-1211-46e0-8106-02d94f6bcaba', '嘲張祜', '嘲張祜', 'd5399e6a-b14b-4442-b60a-54259d08b4d6', '唐', '["白在東都元已薨，蘭臺鳳閣少人登。","冬瓜堰下逢張祜，牛屎堆旁說我能。"]', '["白在东都元已薨，蘭台鳳閣少人登。","冬瓜堰下逢張祜，牛屎堆旁说我能。"]', '诗', 'shi', '', NULL, '嘲張祜 朱沖和 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5c84fd2-74a7-4475-87b8-9120c86e987f', '嘲妓 一', '嘲妓 一', '7958783a-d3f8-4c34-b561-96bbe7c6fa3d', '唐', '["雖得蘇方木，猶貪玳瑁皮。","懷胎十箇月，生下崑崙兒。"]', '["雖得蘇方木，猶貪玳瑁皮。","懷胎十箇月，生下崑崙兒。"]', '诗', 'shi', '', NULL, '嘲妓 一 崔涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da28348b-fe36-444c-8afb-7cf28a5aaf08', '嘲妓 二', '嘲妓 二', '7958783a-d3f8-4c34-b561-96bbe7c6fa3d', '唐', '["布袍披襖火燒氈，紙補箜篌麻接弦。","更著一雙皮屐子，紇梯紇榻出門前。"]', '["布袍披襖火燒氈，紙補箜篌麻接弦。","更著一雙皮屐子，紇梯紇榻出门前。"]', '诗', 'shi', '', NULL, '嘲妓 二 崔涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('281f8298-4f01-497a-b8d5-0552c1f70c6b', '嘲李端端 一', '嘲李端端 一', '7958783a-d3f8-4c34-b561-96bbe7c6fa3d', '唐', '["黃昏不語不知行，鼻似煙窗耳似鐺。","獨把象牙梳插鬢，崑崙山上月初明。"]', '["黄昏不語不知行，鼻似煙窗耳似鐺。","独把象牙梳插鬢，崑崙山上月初明。"]', '诗', 'shi', '', NULL, '嘲李端端 一 崔涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ccae3e5-c56b-4215-9fe2-3aa41198f5ce', '嘲李端端 二', '嘲李端端 二', '7958783a-d3f8-4c34-b561-96bbe7c6fa3d', '唐', '["覓得黃騮鞁繡鞍，善和坊裏取端端。","揚州近日渾成差，一朵能行白牡丹。"]', '["覓得黄騮鞁繡鞍，善和坊裏取端端。","揚州近日渾成差，一朵能行白牡丹。"]', '诗', 'shi', '', NULL, '嘲李端端 二 崔涯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a334abf-0c25-46cf-9026-180e37973021', '詠崔雲娘', '詠崔云娘', '443e0f19-9a22-4307-800d-5a004af827a8', '唐', '["何事最堪悲，雲娘只首奇。","瘦拳拋令急，長嘯出歌遲。","只見肩侵鬢，唯憂骨透皮。","不須當戶立，頭上有鍾馗。"]', '["何事最堪悲，云娘只首奇。","瘦拳拋令急，长嘯出歌遲。","只见肩侵鬢，唯憂骨透皮。","不須當戶立，头上有鍾馗。"]', '诗', 'shi', '', NULL, '詠崔雲娘 李宣古 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc6d5586-5da2-4481-97e2-24680f43c0b9', '嘲妓', '嘲妓', 'c0decb09-1133-44ee-8fa8-2386c17d68ae', '唐', '["盤古當時有遠孫，尚令今日逞家門。","一車白土將泥項，十幅紅旗補破裩。","瓦官寺裏逢行跡，華嶽山前見掌痕。","不須惆悵憂難嫁，待與將書問樂坤。"]', '["盤古當时有远孫，尚令今日逞家门。","一车白土將泥項，十幅紅旗補破裩。","瓦官寺裏逢行跡，华嶽山前见掌痕。","不須惆悵憂难嫁，待與將书问乐坤。"]', '诗', 'shi', '', NULL, '嘲妓 杜牧 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8e84f6d7-fabd-41b7-bb11-16dbf9235a23', '嘲游使君', '嘲游使君', 'f9d1fe7e-5e73-43ea-97a9-92a18c96b07d', '唐', '["白帝城頭二月時，忍教清醒看花枝。","莫言世上無袁許，客子由來是相師。"]', '["白帝城头二月时，忍教清醒看花枝。","莫言世上無袁許，客子由来是相師。"]', '诗', 'shi', '', NULL, '嘲游使君 盧肇 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('39ff5d21-333b-41f0-8985-d3728a5eed44', '嘲李瑒題名', '嘲李瑒題名', '0f6c8018-43c0-4a4c-abad-344c37ea6e71', '唐', '["渭水秦山照眼明，希仁何事寡詩情。","只因學得虞姬壻，書字纔能記姓名。"]', '["渭水秦山照眼明，希仁何事寡诗情。","只因学得虞姬壻，书字纔能記姓名。"]', '诗', 'shi', '', NULL, '嘲李瑒題名 韋蟾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bea387d6-c934-4229-bfa4-d0fec315043d', '聞鹿鳴互謔', '闻鹿鳴互謔', '2000f0ae-eecd-475d-a776-c2f11a481dc1', '唐', '["釜戴山中鹿又鳴，此際多應到表兄。","表兄不是嚴家子，合是三兄與四兄。"]', '["釜戴山中鹿又鳴，此際多應到表兄。","表兄不是嚴家子，合是三兄與四兄。"]', '诗', 'shi', '', NULL, '聞鹿鳴互謔 嚴震 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de4de19c-e5ab-42fb-a9ee-77c05cce3ed7', '及第後寄李紳', '及第後寄李紳', '037f5a12-a1ca-422c-82f5-9c1a2b49b796', '唐', '["及第全勝十政官，金鞍鍍了出長安。","馬頭漸入揚州郭，爲報時人洗眼看。"]', '["及第全勝十政官，金鞍鍍了出长安。","马头漸入揚州郭，爲報时人洗眼看。"]', '诗', 'shi', '', NULL, '及第後寄李紳 章孝標 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af5670b6-a62b-4ebc-95ec-0b6ee21b9129', '荅章孝標', '荅章孝標', 'ae9cc624-259b-4885-8b37-9442fd6d5de9', '唐', '["假金只用真金鍍，若是真金不鍍金。","十載長安得一第，何須空腹用高心。"]', '["假金只用真金鍍，若是真金不鍍金。","十載长安得一第，何須空腹用高心。"]', '诗', 'shi', '', NULL, '荅章孝標 李紳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aa6f166-ea50-4941-83fd-d6c163bfcbf8', '戲柳棠', '戲柳棠', '1ecea968-b89d-47a4-b7f9-8a0b4bf5e3af', '唐', '["文章漫道能吞鳳，杯酒何曾解喫魚。","今日梓州張社會，應須遭這老尚書。"]', '["文章漫道能吞鳳，杯酒何曾解喫鱼。","今日梓州張社會，應須遭這老尚书。"]', '诗', 'shi', '', NULL, '戲柳棠 楊汝士 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4223b9a6-5ec5-4bf6-bab2-627b02c7e69e', '荅楊尚書', '荅楊尚书', '5cdad4f8-c204-490b-8d90-7b22911c4887', '唐', '["未向燕臺逢厚禮，幸因社會接餘歡。","一魚喫了終無媿，鯤化爲鵬也不難。"]', '["未向燕台逢厚禮，幸因社會接餘歡。","一鱼喫了終無媿，鯤化爲鵬也不难。"]', '诗', 'shi', '', NULL, '荅楊尚書 柳棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d46a870-f18f-471a-8d82-a26c259d0452', '又忤楊尚書詩', '又忤楊尚书诗', '5cdad4f8-c204-490b-8d90-7b22911c4887', '唐', '["莫言名位未相儔，風月何曾阻獻酬。","前輩不須輕後輩，靖安今日在衡州。"]', '["莫言名位未相儔，风月何曾阻獻酬。","前輩不須轻後輩，靖安今日在衡州。"]', '诗', 'shi', '', NULL, '又忤楊尚書詩 柳棠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47d8d098-7eb0-4411-a400-ef90874664e3', '嘲郭凝素', '嘲郭凝素', '35df3a4c-112b-4fb1-a1cc-fcd3d6575b85', '唐', '["三春桃李本無言，苦被殘陽鳥雀喧。","借問東鄰效西子，何如郭素擬王軒。"]', '["三春桃李本無言，苦被殘陽鸟雀喧。","借问东鄰效西子，何如郭素擬王軒。"]', '诗', 'shi', '', NULL, '嘲郭凝素 朱澤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae6c6496-7638-4e49-89ce-9c63a146f522', '紀中表試案', '紀中表試案', '89af74ef-ce53-4742-8048-d7ad29ceb03e', '唐', '["新糊案子，其白如銀。","入試出試，千春萬春。"]', '["新糊案子，其白如銀。","入試出試，千春万春。"]', '诗', 'shi', '', NULL, '紀中表試案 鄭光業 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c48232e4-c4ba-440b-902e-74efb9514633', '醉題廣州使院', '醉題廣州使院', '56355a6f-287b-4a28-ae04-3ab685c5d112', '唐', '["數年百姓受飢荒，太守貪殘似虎狼。","今日海隅魚米賤，大須慙媿石榴黃。"]', '["數年百姓受飢荒，太守貪殘似虎狼。","今日海隅鱼米賤，大須慙媿石榴黄。"]', '诗', 'shi', '', NULL, '醉題廣州使院 鄭愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a88d5b2-0301-4937-9474-e577eca17641', '擬權龍褒體贈鄠縣李令及寄朝右', '擬權龙褒體贈鄠縣李令及寄朝右', '56355a6f-287b-4a28-ae04-3ab685c5d112', '唐', '["鄠縣李長官，橫琴膝上弄。","不聞有政聲，但見手子動。"]', '["鄠縣李长官，橫琴膝上弄。","不闻有政声，但见手子动。"]', '诗', 'shi', '', NULL, '擬權龍褒體贈鄠縣李令及寄朝右 鄭愚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab63a001-d9d9-436e-9da8-57a9af708f67', '題滄浪峽牓', '題滄浪峽牓', '5ea9840c-4ab8-408d-ac8c-eb6b58c1a013', '唐', '["分峽東西路正長，行人名利火然湯。","路傍著板滄浪峽，真是將閑攪撩忙。"]', '["分峽东西路正长，行人名利火然湯。","路傍著板滄浪峽，真是將闲攪撩忙。"]', '诗', 'shi', '', NULL, '題滄浪峽牓 鄭仁表 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3dda59-01cf-40c2-ad9b-8af42c278264', '戲妻族語不正', '戲妻族語不正', '1f0fb1fa-eb15-4f74-bf8d-5f381a97d01d', '唐', '["呼十却爲石，喚針將作真。","忽然雲雨至，總道是天因。"]', '["呼十却爲石，喚針將作真。","忽然云雨至，總道是天因。"]', '诗', 'shi', '', NULL, '戲妻族語不正 胡曾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb60afc-1c26-4078-86d7-3fa799aaa138', '婢僕詩 一', '婢僕诗 一', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["春娘愛上酒家樓，不怕歸遲總不憂。","推道那家娘子臥，且留教住待梳頭。"]', '["春娘愛上酒家楼，不怕归遲總不憂。","推道那家娘子臥，且留教住待梳头。"]', '诗', 'shi', '', NULL, '婢僕詩 一 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d529e239-1a4a-4643-9a62-86c75dcebd1a', '婢僕詩 二', '婢僕诗 二', '79be1684-fc60-4cbf-9cef-2e84efd8894b', '唐', '["不論秋菊與春花，箇箇能噇空腹茶。","無事莫教頻入庫，一名閑物要些些。"]', '["不論秋菊與春花，箇箇能噇空腹茶。","無事莫教頻入庫，一名闲物要些些。"]', '诗', 'shi', '', NULL, '婢僕詩 二 李昌符 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f0f350-bd42-4b13-9c8c-7bcb603bb6a5', '嘲鄭傪妓', '嘲鄭傪妓', '20f22866-abe8-466f-bc4d-2106f25a4b8b', '唐', '["相公經文復經武，常侍好今兼好古。","昔人曾聞阿武婆，今日親見阿婆舞。"]', '["相公經文复經武，常侍好今兼好古。","昔人曾闻阿武婆，今日親见阿婆舞。"]', '诗', 'shi', '', NULL, '嘲鄭傪妓 孫子多 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('888a9b5d-6b80-4e71-b235-b8386b657639', '嘲趙璘 一', '嘲趙璘 一', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["巡關每傍摴蒲局，望月還登乞巧樓。","第一莫教嬌太過，緣人衣帶上人頭。"]', '["巡关每傍摴蒲局，望月還登乞巧楼。","第一莫教嬌太過，緣人衣带上人头。"]', '诗', 'shi', '', NULL, '嘲趙璘 一 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad497017-115e-4449-a5ee-ef722931a6b2', '嘲趙璘 二', '嘲趙璘 二', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["不知原在鞍轎裏，將謂空馱席帽歸。"]', '["不知原在鞍轎裏，將謂空馱席帽归。"]', '诗', 'shi', '', NULL, '嘲趙璘 二 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('814ee97c-84c3-43d5-a30e-f7ff9d3d2cfe', '嘲趙璘 三', '嘲趙璘 三', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["火爐牀上平身立，便與夫人作鏡臺。"]', '["火爐牀上平身立，便與夫人作镜台。"]', '诗', 'shi', '', NULL, '嘲趙璘 三 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8aae3c10-0234-4ac1-acff-07523bd5d3e3', '口號', '口號', 'd62cbac9-409f-4c33-9042-cf4ab7c9263f', '唐', '["素脊鳴秋杖，烏鞾響暮廳。","刃飛三尺雪，白日落文星。"]', '["素脊鳴秋杖，烏鞾响暮廳。","刃飞三尺雪，白日落文星。"]', '诗', 'shi', '', NULL, '口號 薛能 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('786aa650-2834-4fdd-a991-9c541ea4a576', '嘲歸仁紹龜詩', '嘲归仁紹龟诗', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["硬骨殘形知幾秋，屍骸終是不風流。","頑皮死後鑽須徧，都爲平生不出頭。"]', '["硬骨殘形知幾秋，屍骸終是不风流。","頑皮死後鑽須徧，都爲平生不出头。"]', '诗', 'shi', '', NULL, '嘲歸仁紹龜詩 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c332420d-5837-4bdc-8156-c42679585b42', '詠螃蟹呈浙西從事', '詠螃蟹呈浙西從事', 'd40f2921-9c7e-4269-bc34-690f16c476d2', '唐', '["未遊滄海早知名，有骨還從肉上生。","莫道無心畏雷電，海龍王處也橫行。"]', '["未游滄海早知名，有骨還從肉上生。","莫道無心畏雷電，海龙王处也橫行。"]', '诗', 'shi', '', NULL, '詠螃蟹呈浙西從事 皮日休 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3f4fafae-f982-45b2-8d6d-36fccb75625f', '題中書壁', '題中书壁', 'a50985c6-f11d-4c77-830d-68be319a2986', '唐', '["側坡蛆蜫蜦，蟻子競來拖。","一朝白雨中，無鈍無嘍羅。"]', '["側坡蛆蜫蜦，蟻子競来拖。","一朝白雨中，無鈍無嘍羅。"]', '诗', 'shi', '', NULL, '題中書壁 鄭綮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a47e3068-5c2f-4d4c-a482-a899869de68a', '別廬州郡人', '別廬州郡人', 'a50985c6-f11d-4c77-830d-68be319a2986', '唐', '["唯有兩行公廨淚，一時灑向渡頭風。"]', '["唯有兩行公廨泪，一时灑向渡头风。"]', '诗', 'shi', '', NULL, '別廬州郡人 鄭綮 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3d00f20b-f08b-4ad9-9b01-303105e7dced', '戲荅成汭', '戲荅成汭', '71ed8985-8d63-42e0-bb57-1065731ef49f', '唐', '["南海黃茅瘴，不死成和尚。"]', '["南海黄茅瘴，不死成和尚。"]', '诗', 'shi', '', NULL, '戲荅成汭 徐彥若 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8ad02010-ecaf-4652-b6fc-497006aeffe1', '醉中謔浙江廉使', '醉中謔浙江廉使', '11fd39de-9d42-4c6e-b159-8bffb04c3844', '唐', '["山夫留意向丹梯，連帥邀來出藥畦。","常見浙東誇鏡水，鏡湖元在浙江西。"]', '["山夫留意向丹梯，連帥邀来出藥畦。","常见浙东誇镜水，镜湖元在浙江西。"]', '诗', 'shi', '', NULL, '醉中謔浙江廉使 崔立言 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6067523-9a43-4ae2-bf7a-5c89347791fe', '戲題盱眙邵明府壁', '戲題盱眙邵明府壁', '07ea8fc4-3ef2-43e0-be02-3c6ca5544d7b', '唐', '["豈肯閑尋竹徑行，却嫌絲管好蛙聲。","自從煮鶴燒琴後，背却青山臥月明。"]', '["豈肯闲尋竹徑行，却嫌絲管好蛙声。","自從煮鹤燒琴後，背却青山臥月明。"]', '诗', 'shi', '', NULL, '戲題盱眙邵明府壁 韋鵬翼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7f31dbbc-89da-414c-bc74-6536ad7a2063', '題大梁臨汴驛', '題大梁臨汴驛', '1b429292-f123-4995-a78a-f8361758d07b', '唐', '["近日侯門不重才，莫將文藝擬爲媒。","相逢若要如膠漆，不是紅妝即撥灰。"]', '["近日侯门不重才，莫將文藝擬爲媒。","相逢若要如膠漆，不是紅妝即撥灰。"]', '诗', 'shi', '', NULL, '題大梁臨汴驛 姚嶸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a805f242-aae2-4e68-a88e-2591a20cf90d', '題仙娥驛', '題仙娥驛', '84189049-c6a5-451a-8338-a904b3f277e2', '唐', '["商山食店大悠悠，陳鶡䭔鑼古䭃頭。","更有臺中牛肉炙，尚盤數臠紫光毬。"]', '["商山食店大悠悠，陳鶡䭔鑼古䭃头。","更有台中牛肉炙，尚盤數臠紫光毬。"]', '诗', 'shi', '', NULL, '題仙娥驛 李日新 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de87f5c9-6382-4518-99d6-282d657a7258', '嘲染家', '嘲染家', 'a5f1e013-e512-42b5-bf99-6082551135d7', '唐', '["紫綠終朝染，因何不識非。","莆田竹木貴，背負十柴歸。"]', '["紫綠終朝染，因何不識非。","莆田竹木貴，背負十柴归。"]', '诗', 'shi', '', NULL, '嘲染家 柳逢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe864493-5408-4e4e-a0e4-6140a9516e19', '贈漳州崔使君鄉飲飜韻詩', '贈漳州崔使君乡饮飜韻诗', 'b6284fe4-d6b9-42c8-84ff-2fe2cc374196', '唐', '["慣向溪邊折柳楊，因循行客到州漳。","無端觸忤王衙押，不得今朝看飲鄉。"]', '["慣向溪邊折柳楊，因循行客到州漳。","無端觸忤王衙押，不得今朝看饮乡。"]', '诗', 'shi', '', NULL, '贈漳州崔使君鄉飲飜韻詩 黎瓘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c207359a-1345-4823-9ea5-40055978d0de', '示妓牓子', '示妓牓子', 'cc35b941-1abc-4f63-8020-903dec8fe1a3', '唐', '["綠羅帬下標三棒，紅粉顋邊淚兩行。","叉手向前咨大使，這迴不敢惱兒郎。"]', '["綠羅帬下標三棒，紅粉顋邊泪兩行。","叉手向前咨大使，這迴不敢惱兒郎。"]', '诗', 'shi', '', NULL, '示妓牓子 張保胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c07d83-f75b-4a57-af32-95e1da905984', '又留別同院', '又留別同院', 'cc35b941-1abc-4f63-8020-903dec8fe1a3', '唐', '["憶昔當年富貴時，如今頭腦尚依稀。","布袍破後思宮內，錦袴穿時憶御衣。","鶻子背鑽高力士，嬋娟飜畫太真妃。","如今顦顇離南海，恰似當時幸蜀時。"]', '["憶昔當年富貴时，如今头腦尚依稀。","布袍破後思宮內，錦袴穿时憶御衣。","鶻子背鑽高力士，嬋娟飜畫太真妃。","如今顦顇離南海，恰似當时幸蜀时。"]', '诗', 'shi', '', NULL, '又留別同院 張保胤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5451d582-51c6-49ff-92be-32eb6bcf28b0', '桂州筵上贈胡予女', '桂州筵上贈胡予女', '651770dc-b188-40c7-83c6-61ce7cec24d1', '唐', '["自道風流不可攀，却堪蹙額更頹顏。","眼睛深却湘江水，鼻孔高於華岳山。","舞態固難居掌上，歌聲應不繞梁間。","孟陽死後欲千載，猶在佳人覓往還。"]', '["自道风流不可攀，却堪蹙額更頹顏。","眼睛深却湘江水，鼻孔高於华岳山。","舞態固难居掌上，歌声應不繞梁间。","孟陽死後欲千載，猶在佳人覓往還。"]', '诗', 'shi', '', NULL, '桂州筵上贈胡予女 陸巖夢 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b733e47f-c47c-4da6-8afd-9342f9e31dbe', '戲荅朝士', '戲荅朝士', '26fd3222-ba78-4f4c-929b-efe9004d6957', '唐', '["華緘千里到荆門，章草縱橫任意論。","應笑鍾張虛用力，却教羲獻枉勞魂。","惟堪愛惜爲珍寶，不敢傳留誤子孫。","深荷故人相厚處，天行時氣許教吞。"]', '["华緘千里到荆门，章草縱橫任意論。","應笑鍾張虛用力，却教羲獻枉勞魂。","惟堪愛惜爲珍寶，不敢傳留誤子孫。","深荷故人相厚处，天行时氣許教吞。"]', '诗', 'shi', '', NULL, '戲荅朝士 李都 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e493788d-8432-439b-a35a-4b1392f22705', '嘲僧惟恭', '嘲僧惟恭', 'b0272f70-453b-4f3d-8cdb-2416a3ee8255', '唐', '["靈巋作盡業，惟恭繼其跡。","地獄千萬重，莫厭排頭人。"]', '["靈巋作尽業，惟恭繼其跡。","地獄千万重，莫厭排头人。"]', '诗', 'shi', '', NULL, '嘲僧惟恭 荆人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4931459e-cd0f-4872-9671-9799b727a5f8', '題酒戶修孔廟狀', '題酒戶修孔廟狀', '8e2cbe17-7405-468c-8859-b04308c50dbd', '唐', '["槐影參差覆杏壇，儒門子弟盡高官。","却教酒戶重脩廟，覓我慚惶也不難。"]', '["槐影參差覆杏壇，儒门子弟尽高官。","却教酒戶重脩廟，覓我慚惶也不难。"]', '诗', 'shi', '', NULL, '題酒戶修孔廟狀 馮道幕客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d0db88a-fd4f-49a5-a60c-21f2b5e5bf8c', '孔廟口號', '孔廟口號', 'b83877ef-3b7c-4efd-a5db-616183893970', '唐', '["破落三間屋，蕭條一旅人。","不知負何事，生死厄於陳。"]', '["破落三间屋，蕭條一旅人。","不知負何事，生死厄於陳。"]', '诗', 'shi', '', NULL, '孔廟口號 李花開 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc9172de-0a15-4dcb-a159-3fe305e03ac4', '荅妻', '荅妻', 'e62749b6-1109-463a-a2b7-1ad882c24a6d', '唐', '["休說辦不辦，且看甕裏飛出雁。"]', '["休说辦不辦，且看甕裏飞出雁。"]', '诗', 'shi', '', NULL, '荅妻 馮暉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('089e7241-65c2-4373-a46c-db84eae3522a', '題僧院', '題僧院', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["走却坐禪客，移將不動尊。","世間顛倒事，八萬四千門。"]', '["走却坐禪客，移將不动尊。","世间顛倒事，八万四千门。"]', '诗', 'shi', '', NULL, '題僧院 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34361a12-5cfc-4216-a840-9752b7c86cf5', '詠垂絲蜘蛛嘲雲辨僧', '詠垂絲蜘蛛嘲云辨僧', '53347179-ab61-419d-9fe6-c02b707fb88d', '唐', '["喫得肚嬰撐，尋思繞寺行。","空中設羅網，只待殺衆生。"]', '["喫得肚嬰撐，尋思繞寺行。","空中設羅網，只待殺衆生。"]', '诗', 'shi', '', NULL, '詠垂絲蜘蛛嘲雲辨僧 楊苧蘿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8df4bc80-add4-4728-9894-4ad7967db275', '自嘲絕句', '自嘲絕句', 'fbdd8256-fce0-44df-82ce-855988f95b07', '唐', '["取水郎中何日了，破柴員外幾時休。","早知蜀地區娵與，悔不長安大比丘。"]', '["取水郎中何日了，破柴員外幾时休。","早知蜀地區娵與，悔不长安大比丘。"]', '诗', 'shi', '', NULL, '自嘲絕句 馮涓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('125c90a9-26a6-4140-92c5-dbae978a9e3e', '哭亡將詩', '哭亡將诗', '5216e078-555a-4540-bda4-099bd291516f', '唐', '["自是碙砂發，非干駭石傷。","牒高身上職，盌大背邊創。"]', '["自是碙砂發，非干駭石傷。","牒高身上職，盌大背邊創。"]', '诗', 'shi', '', NULL, '哭亡將詩 盧延讓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7131b467-0f3a-4149-8878-51a0d45a7c9e', '詠王給事', '詠王給事', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["厥父元非道郡奴，允光何事太侏儒。","可中與箇皮裩著，擎得天王左脚無。"]', '["厥父元非道郡奴，允光何事太侏儒。","可中與箇皮裩著，擎得天王左脚無。"]', '诗', 'shi', '', NULL, '詠王給事 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72590b4c-9725-4a02-938f-bce002fdf927', '詠金剛', '詠金剛', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["揚眉斗目惡精神，揑合將來恰似真。","剛被時流借拳勢，不知身自是泥人。"]', '["揚眉斗目惡精神，揑合將来恰似真。","剛被时流借拳勢，不知身自是泥人。"]', '诗', 'shi', '', NULL, '詠金剛 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee5d197f-7d47-4106-adfa-dac889ff17bd', '詠傴背子', '詠傴背子', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["出得門來背拄天，同行難可與差肩。","若教倚向閑牕下，恰似箜篌不著弦。"]', '["出得门来背拄天，同行难可與差肩。","若教倚向闲牕下，恰似箜篌不著弦。"]', '诗', 'shi', '', NULL, '詠傴背子 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd214135-8f3b-41cc-b6e7-0719b06f08c4', '詠安仁宰擣蒜', '詠安仁宰擣蒜', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["安仁縣令好誅求，百姓脂膏滿面流。","半破磁缸成醋酒，死牛腸肚作饅頭。","帳生歲取餐三頓，鄉老盤庚犯五甌。","半醉半醒齊出縣，共傷塗炭不勝愁。"]', '["安仁縣令好誅求，百姓脂膏满面流。","半破磁缸成醋酒，死牛腸肚作饅头。","帳生歲取餐三頓，乡老盤庚犯五甌。","半醉半醒齊出縣，共傷塗炭不勝愁。"]', '诗', 'shi', '', NULL, '詠安仁宰擣蒜 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5189b2f2-83b8-4a5b-9072-faabe6299e5e', '五門街望有題', '五门街望有題', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["我皇開國十餘年，一輩超升炙手歡。","閑向五門樓下望，衙官騎馬使衙官。"]', '["我皇开国十餘年，一輩超升炙手歡。","闲向五门楼下望，衙官騎马使衙官。"]', '诗', 'shi', '', NULL, '五門街望有題 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('577d8eeb-67f3-4d87-a286-f05e834d422f', '謝郎中惠茶', '謝郎中惠茶', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["三斤綠茗賜貽恭，一種頒霑事不同。","想料腸懷無荅處，披毛戴角謝郎中。"]', '["三斤綠茗賜貽恭，一種頒霑事不同。","想料腸懷無荅处，披毛戴角謝郎中。"]', '诗', 'shi', '', NULL, '謝郎中惠茶 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36182c17-4621-4e37-89f7-0069f4652544', '詠蝦蟆', '詠蝦蟆', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["坐臥兼行總一般，向人努眼太無端。","欲知自己形骸小，試就蹄涔照影看。"]', '["坐臥兼行總一般，向人努眼太無端。","欲知自己形骸小，試就蹄涔照影看。"]', '诗', 'shi', '', NULL, '詠蝦蟆 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd12eafe-2579-4bb8-9c0a-b56ae2647b05', '住名山日陳情上府主高太保', '住名山日陳情上府主高太保', '9a8c6daf-3802-4c59-8140-e50f1073c34f', '唐', '["名山主簿實堪愁，難齩他家大骨頭。","米納功南錢納府，祗看江面水東流。"]', '["名山主簿實堪愁，难齩他家大骨头。","米納功南錢納府，祗看江面水东流。"]', '诗', 'shi', '', NULL, '住名山日陳情上府主高太保 蔣貽恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16f2749a-aa1a-4bce-9d10-7761dcf75968', '詠刺蝟', '詠刺蝟', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["行似針氈動，臥若栗毬圓。","莫欺如此大，誰敢便行拳。"]', '["行似針氈动，臥若栗毬圓。","莫欺如此大，誰敢便行拳。"]', '诗', 'shi', '', NULL, '詠刺蝟 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c50bc10a-e1df-411c-bd3c-7ecfb4540872', '謁貴公子不禮書格子屏風', '謁貴公子不禮书格子屏风', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["道格何曾格，言糊又不糊。","渾身總是眼，還解識人無。"]', '["道格何曾格，言糊又不糊。","渾身總是眼，還解識人無。"]', '诗', 'shi', '', NULL, '謁貴公子不禮書格子屏風 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('18449f67-6788-4bd8-85d0-dae0c7561a29', '詠月', '詠月', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["當塗當塗見，蕪湖蕪湖見。","八月十五夜，一似沒柄扇。"]', '["當塗當塗见，蕪湖蕪湖见。","八月十五夜，一似沒柄扇。"]', '诗', 'shi', '', NULL, '詠月 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af3700b6-9f75-4e84-b480-785d3e5c6f87', '詠狗蚤', '詠狗蚤', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["與蝨都來不較多，㩧挑筋斗太嘍囉。","忽然管著一籃子，有甚心情那你何。"]', '["與蝨都来不較多，㩧挑筋斗太嘍囉。","忽然管著一籃子，有甚心情那你何。"]', '诗', 'shi', '', NULL, '詠狗蚤 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a5003e6-f76d-440c-aa1e-8d335aec8d95', '詠罌粟子', '詠罌粟子', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["倒排雙陸子，希插碧牙籌。","既似犧牛乳，又如鈴馬兜。","鼓捶幷瀑箭，直是有來由。"]', '["倒排雙陸子，希插碧牙籌。","既似犧牛乳，又如鈴马兜。","鼓捶幷瀑箭，直是有来由。"]', '诗', 'shi', '', NULL, '詠罌粟子 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8b9ae6fe-2dbd-455c-8150-759a27bdcf9f', '詠蟹', '詠蟹', '4ebd5283-ee77-4764-ad5b-3f5d5128c7e0', '唐', '["蟬眼龜形脚似蛛，未曾正面向人趨。","如今飣在盤筵上，得似江湖亂走無。"]', '["蟬眼龟形脚似蛛，未曾正面向人趨。","如今飣在盤筵上，得似江湖亂走無。"]', '诗', 'shi', '', NULL, '詠蟹 李貞白 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c326c254-572a-4d33-9d77-d2b329daf9e1', '示女詩', '示女诗', 'b8a02f4c-1fba-499a-a741-7e85d8c7caa2', '唐', '["深宮富貴事風流，莫忘生身老骨頭。","因與太師歡笑處，爲吾方便覓彭州。"]', '["深宮富貴事风流，莫忘生身老骨头。","因與太師歡笑处，爲吾方便覓彭州。"]', '诗', 'shi', '', NULL, '示女詩 郫城令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c29eac77-3cf7-40ae-85c5-0e6d9edad36a', '寄女', '寄女', 'f8a288b5-9e49-476e-9010-4ce2ffc054a5', '唐', '["有人教我向衡陽，一度思歸欲斷腸。","爲報豔妻兼少女，與吾覓取朗州場。"]', '["有人教我向衡陽，一度思归欲斷腸。","爲報豔妻兼少女，與吾覓取朗州場。"]', '诗', 'shi', '', NULL, '寄女 李令 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30aacfb4-d236-4548-ab67-305f2aaeae4f', '諷劉炎索賄詩', '諷劉炎索賄诗', '78bb7237-1669-40c4-acc0-4e0417226be3', '唐', '["未到桃源時，長憶出家景。","及到桃源了，還似鑑中影。"]', '["未到桃源时，长憶出家景。","及到桃源了，還似鑑中影。"]', '诗', 'shi', '', NULL, '諷劉炎索賄詩 太守 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69e3d4bc-111a-4284-b8c2-c7666d11389c', '被按自悔詩', '被按自悔诗', 'f12c5923-e07e-44d1-b3aa-a83721e324af', '唐', '["早知太守如虎狼，獵取膏粱以啗之。"]', '["早知太守如虎狼，獵取膏粱以啗之。"]', '诗', 'shi', '', NULL, '被按自悔詩 劉炎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43290b84-f17e-4356-84f7-2254f8e85726', '與王仙客互嘲', '與王仙客互嘲', '2f2b9fe7-3ed9-40e8-8723-91d4bbe90591', '唐', '["王，計爾應姓田，爲你面撥獺，抽却你兩邊。","甘，計爾應姓丹，爲你頭不曲，迴脚向上安。"]', '["王，計爾應姓田，爲你面撥獺，抽却你兩邊。","甘，計爾應姓丹，爲你头不曲，迴脚向上安。"]', '诗', 'shi', '', NULL, '與王仙客互嘲 甘洽 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('823bbd1f-3959-4d09-942d-b1388e63db12', '題濠州高塘館', '題濠州高塘館', 'a5af94b8-e451-4162-b37b-43ae6306513c', '唐', '["借問襄王安在哉，山川此地勝陽臺。","今宵寓宿高塘館，神女何曾入夢來。"]', '["借问襄王安在哉，山川此地勝陽台。","今宵寓宿高塘館，神女何曾入梦来。"]', '诗', 'shi', '', NULL, '題濠州高塘館 閻敬愛 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47bc39ef-a668-4da5-96ae-75a12818ee72', '題敬愛詩後', '題敬愛诗後', '28df4f38-1ea6-4261-afc8-663cb061e4d1', '唐', '["高唐不是這高塘，淮畔荆南各異方。","若向此中求薦枕，參差笑殺楚襄王。"]', '["高唐不是這高塘，淮畔荆南各異方。","若向此中求薦枕，參差笑殺楚襄王。"]', '诗', 'shi', '', NULL, '題敬愛詩後 李和風 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf1812cc-7a2e-4c20-b422-8557a8edbe71', '荅日休皮字詩', '荅日休皮字诗', '088d35da-710d-4979-8a6a-fb617957c746', '唐', '["八片尖裁浪作毬，火中燖了水中揉。","一包閑氣如長在，惹踢招拳卒未休。"]', '["八片尖裁浪作毬，火中燖了水中揉。","一包闲氣如长在，惹踢招拳卒未休。"]', '诗', 'shi', '', NULL, '荅日休皮字詩 歸氏子 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7afd439-4a06-49df-974a-b465ee29d54b', '謔池亳二州賓佐兼寄宣武軍掌書記李晝', '謔池亳二州賓佐兼寄宣武軍掌书記李晝', '2dcb8abf-c442-4efe-8d6d-45f0bfb95dee', '唐', '["杜叟學仙輕蕙質，韋公事佛畏青娥。","樂營却是閑人管，兩地風情日漸多。"]', '["杜叟学仙轻蕙質，韋公事佛畏青娥。","乐營却是闲人管，兩地风情日漸多。"]', '诗', 'shi', '', NULL, '謔池亳二州賓佐兼寄宣武軍掌書記李晝 張魯封 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('286ec312-7763-46d6-9b4f-b2ada214e81e', '戲酬張魯封', '戲酬張魯封', '8aed950b-3193-40d3-931a-91290b0fdccd', '唐', '["秋浦亞卿顏叔子，譙都中憲老桑門。","如今柳巷通車馬，唯恐他時立棘垣。"]', '["秋浦亞卿顏叔子，譙都中憲老桑门。","如今柳巷通车马，唯恐他时立棘垣。"]', '诗', 'shi', '', NULL, '戲酬張魯封 李晝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e54dea-ab66-4324-a38e-7b70da2b361c', '即事', '即事', '55f32968-0f4e-4833-8215-eb48226b17e9', '唐', '["白日蒼蠅滿飰盤，夜間蚊子又成團。","每到更深人靜後，定來頭上齩楊鸞。"]', '["白日蒼蠅满飰盤，夜间蚊子又成團。","每到更深人静後，定来头上齩楊鸾。"]', '诗', 'shi', '', NULL, '即事 楊鸞 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ba37bb9-75d4-40ef-a9ea-08942f3fd528', '嘲周顓', '嘲周顓', 'ce5d0da5-017d-41b1-bbc4-195f9a90a5ea', '唐', '["龍津掉尾十年勞，聲價當時鬬月高。","惟有紅妝回舞手，似持霜刀向猨猱。"]', '["龙津掉尾十年勞，声價當时鬬月高。","惟有紅妝回舞手，似持霜刀向猨猱。"]', '诗', 'shi', '', NULL, '嘲周顓 座客 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ac6db52-ec7e-4d0b-b41e-5eb95251b145', '和座客', '和座客', '3a9c2593-a304-4830-81c0-3a33f0995ca6', '唐', '["十載文場敢憚勞，宋都回鶂爲風高。","今朝甘被花枝笑，任道尊前愛縛猱。"]', '["十載文場敢憚勞，宋都回鶂爲风高。","今朝甘被花枝笑，任道尊前愛縛猱。"]', '诗', 'shi', '', NULL, '和座客 周顓 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2be3c28a-eacf-4ec8-b395-e20d5413fc20', '荅或人', '荅或人', '7bb6ac37-e7ae-4a84-af2c-0ea5e06513eb', '唐', '["寧可且將朱脣飲酒，誰能遂你黑齒常之。"]', '["寧可且將朱脣饮酒，誰能遂你黑齒常之。"]', '诗', 'shi', '', NULL, '荅或人 張鷟 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('831e4a20-b9e3-420c-a1b4-a4cfafc6c480', '嘲崔嘏', '嘲崔嘏', 'ec34ba07-4a12-4889-a341-af82c118aacd', '唐', '["二十九人及第，五十七眼看花。"]', '["二十九人及第，五十七眼看花。"]', '诗', 'shi', '', NULL, '嘲崔嘏 施肩吾 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d11956c-8fe0-49c2-81a0-6b3c8a635654', '嶺南詩句', '嶺南诗句', '4d405fd2-4182-4b4b-996e-218ce797f046', '唐', '["郭裏多榕樹，街中足使君。"]', '["郭裏多榕樹，街中足使君。"]', '诗', 'shi', '', NULL, '嶺南詩句 蘇芸 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a99520c1-cdec-4bb3-a39a-2607aa674352', '諧詩逸句 一', '諧诗逸句 一', '9a04dcf8-fcc0-4197-a808-b2d1a5b3aeba', '唐', '["霧是山巾子，船爲水靸鞋。"]', '["霧是山巾子，船爲水靸鞋。"]', '诗', 'shi', '', NULL, '諧詩逸句 一 包賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c47738d5-7ee8-4d60-b9e7-bc424d614413', '諧詩逸句 二', '諧诗逸句 二', '9a04dcf8-fcc0-4197-a808-b2d1a5b3aeba', '唐', '["櫂搖船掠鬢，風動水槌胸。"]', '["櫂搖船掠鬢，风动水槌胸。"]', '诗', 'shi', '', NULL, '諧詩逸句 二 包賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61faab0f-53ae-494e-a8f8-d5ab4dffcdcc', '諧詩逸句 三', '諧诗逸句 三', '9a04dcf8-fcc0-4197-a808-b2d1a5b3aeba', '唐', '["苦竹筍抽青橛子，石榴樹挂小缾兒。"]', '["苦竹筍抽青橛子，石榴樹挂小缾兒。"]', '诗', 'shi', '', NULL, '諧詩逸句 三 包賀 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7569c3e1-a5f7-4d24-b9a0-a7dcf576550d', '題洞庭湖', '題洞庭湖', '650b12d2-fb48-430d-a221-e52512221e12', '唐', '["可憐洞庭湖，恰到三冬無髭鬚。"]', '["可怜洞庭湖，恰到三冬無髭鬚。"]', '诗', 'shi', '', NULL, '題洞庭湖 蔡押衙 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3751fd48-8fcf-41f8-acb1-00102ba8f7cb', '戲令狐相', '戲令狐相', 'd42f7cb0-5bba-4d5b-9810-c01815d8c793', '唐', '["自從元老登庸後，天下諸胡悉帶鈴。"]', '["自從元老登庸後，天下諸胡悉带鈴。"]', '诗', 'shi', '', NULL, '戲令狐相 溫庭筠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d960ff7-d968-49b8-9ae1-6d88cad8c2a7', '與羅隱互謔', '與羅隐互謔', '44d45c55-d6a9-4165-b318-a4f60b04a4f6', '唐', '["青蠅被扇扇離席，白澤遭釘釘在門。"]', '["青蠅被扇扇離席，白澤遭釘釘在门。"]', '诗', 'shi', '', NULL, '與羅隱互謔 顧雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bcca43c9-e103-40fa-9fcc-9f0e2d13e41d', '引自落便宜句', '引自落便宜句', 'dec90a21-52ca-48ea-86a8-9b99cb36c5c0', '唐', '["窗下有時留客宿，室中無事伴僧眠。"]', '["窗下有时留客宿，室中無事伴僧眠。"]', '诗', 'shi', '', NULL, '引自落便宜句 孫光憲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50878319-f8f5-4c2c-85f2-e8cc2c3c6130', '嘲廩丘令丞', '嘲廩丘令丞', '480d94e8-1ede-4021-b414-4bb3a34bf551', '唐', '["令丞俱動手，縣尉止回身。"]', '["令丞俱动手，縣尉止回身。"]', '诗', 'shi', '', NULL, '嘲廩丘令丞 商則 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc3c57cf-70ee-429d-b484-09b7be883956', '題漢祖廟', '題漢祖廟', '302c5ada-ce4d-4d97-9107-9ecc1eb7e5e4', '唐', '["項羽英雄猶不懼，可憐容得辟陽侯。"]', '["項羽英雄猶不懼，可怜容得辟陽侯。"]', '诗', 'shi', '', NULL, '題漢祖廟 羅穎 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15e02ba3-6405-45b6-b21c-487aa7f76b95', '自賦催妝詩', '自賦催妝诗', 'c454bad7-ebc4-474a-9194-07112ec735a8', '唐', '["彭祖尚聞年八百，陳郎猶是小孩兒。"]', '["彭祖尚闻年八百，陳郎猶是小孩兒。"]', '诗', 'shi', '', NULL, '自賦催妝詩 陳嶠 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('befce723-3d11-46c0-8b90-7d5961daa036', '戲爲舉子對句', '戲爲舉子对句', 'e26157ce-10c5-43ed-9b4f-0a26975167f3', '唐', '["曉來犬吠張三婦，日暮猨啼呂四妻。"]', '["晓来犬吠張三婦，日暮猨啼呂四妻。"]', '诗', 'shi', '', NULL, '戲爲舉子對句 何承裕 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('585a0777-81ac-4794-80cc-207d3b019798', '荅弟婦歇後語', '荅弟婦歇後語', 'b5d2ead8-ce44-47da-a2af-94bc6846601c', '唐', '["慙無竇建，媿作梁山。"]', '["慙無竇建，媿作梁山。"]', '诗', 'shi', '', NULL, '荅弟婦歇後語 李濤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8c977d92-3f1a-431e-9603-ea489f62180c', '與釋惠江互謔', '與釋惠江互謔', 'e72586d0-5c02-40f9-8dc9-df6dbe5c3ff4', '唐', '["僧錄琵琶腿，先生觱栗頭。"]', '["僧錄琵琶腿，先生觱栗头。"]', '诗', 'shi', '', NULL, '與釋惠江互謔 程紫霄 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16bd2098-92df-4539-b8e5-11211aa92e52', '與李榮互謔', '與李榮互謔', '84a2fc1a-fc8c-45b6-8d87-4c06c69d5f0c', '唐', '["姓李應須禮，言榮又不榮。","身長三尺半，頭毛猶未生。"]', '["姓李應須禮，言榮又不榮。","身长三尺半，头毛猶未生。"]', '诗', 'shi', '', NULL, '與李榮互謔 僧法軌 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22adc2c6-e8aa-4420-a06a-1993d0548321', '廣州三樵歌', '廣州三樵歌', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["奉敕追三樵，隨侯傍道走。","迴頭語李郎，喚取爾朱九。"]', '["奉敕追三樵，隨侯傍道走。","迴头語李郎，喚取爾朱九。"]', '诗', 'shi', '', NULL, '廣州三樵歌 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ba83755-b142-49a0-be57-af5a7eb4069a', '三御史詠', '三御史詠', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["韋子凝而密，任生直且狂。","可憐元福慶，也學坐凝牀。"]', '["韋子凝而密，任生直且狂。","可怜元福慶，也学坐凝牀。"]', '诗', 'shi', '', NULL, '三御史詠 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eaaaddd-b62a-4b8a-b2ce-0d5953ce40ef', '臺中裏行詠', '台中裏行詠', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["柱下雖爲史，臺中未是官。","何時聞必也，早晚見任端。"]', '["柱下雖爲史，台中未是官。","何时闻必也，早晚见任端。"]', '诗', 'shi', '', NULL, '臺中裏行詠 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cf7451f-2238-47aa-99fb-bd0346b14ba4', '譏裴休', '譏裴休', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["趙氏兒皆尼氏女，師翁兒即晉公兒。","却教術士難推算，胎月分張與阿誰。"]', '["趙氏兒皆尼氏女，師翁兒即晉公兒。","却教術士难推算，胎月分張與阿誰。"]', '诗', 'shi', '', NULL, '譏裴休 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8fc6c63b-cef7-4ba0-b807-dbeea581b001', '嘲四相', '嘲四相', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["確確無餘事，錢財總被收。","商人都不管，貨賂幾時休。"]', '["確確無餘事，錢財總被收。","商人都不管，貨賂幾时休。"]', '诗', 'shi', '', NULL, '嘲四相 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('35949e15-34ad-42e0-9094-3064ddb967ed', '放牓詩', '放牓诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["乞兒還有大通年，三十三人椀杖全。","薛庶準前騎瘦馬，范酇依舊蓋番氈。"]', '["乞兒還有大通年，三十三人椀杖全。","薛庶準前騎瘦马，范酇依旧蓋番氈。"]', '诗', 'shi', '', NULL, '放牓詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72599425-eb86-487b-8af3-2aa2bd25a619', '改魏扶詩', '改魏扶诗', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["葉落滿庭陰，朱門試院深。","昔年辛苦地，今日負前心。"]', '["葉落满庭陰，朱门試院深。","昔年辛苦地，今日負前心。"]', '诗', 'shi', '', NULL, '改魏扶詩 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('097519cd-13cc-40af-871a-56c7eac18ada', '嘲舉子騎驢', '嘲舉子騎驢', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["今年敕下盡騎驢，短軸長鞦滿九衢。","清瘦兒郎猶自可，就中愁殺鄭昌圖。"]', '["今年敕下尽騎驢，短軸长鞦满九衢。","清瘦兒郎猶自可，就中愁殺鄭昌圖。"]', '诗', 'shi', '', NULL, '嘲舉子騎驢 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b2210b9-6b29-4945-a4fd-8004e3167cfe', '嘲崔垂休', '嘲崔垂休', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["慈恩塔下親泥壁，滑膩光華玉不如。","何事博陵崔四十，金陵腿上逞歐書。"]', '["慈恩塔下親泥壁，滑膩光华玉不如。","何事博陵崔四十，金陵腿上逞歐书。"]', '诗', 'shi', '', NULL, '嘲崔垂休 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('71868aee-f230-42e6-b8cc-f7257057a891', '嘲主司崔澹', '嘲主司崔澹', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主司何事厭吾王，解把黃巢比武王。"]', '["主司何事厭吾王，解把黄巢比武王。"]', '诗', 'shi', '', NULL, '嘲主司崔澹 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('298d51e6-e6df-4120-bd6e-34ef0bfa5942', '朝士戲任轂', '朝士戲任轂', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["雲林應訝鶴書遲，自入京來探事宜。","從此見山須合眼，被山相賺已多時。"]', '["云林應訝鹤书遲，自入京来探事宜。","從此见山須合眼，被山相賺已多时。"]', '诗', 'shi', '', NULL, '朝士戲任轂 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('04e9eaba-1ab2-4b54-9e67-659766f7037b', '題房魯題名後', '題房魯題名後', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["姚家新壻是房郎，未解芳顏意欲狂。","見說正調穿羽箭，莫教射破寺家牆。"]', '["姚家新壻是房郎，未解芳顏意欲狂。","见说正調穿羽箭，莫教射破寺家牆。"]', '诗', 'shi', '', NULL, '題房魯題名後 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf212c0c-1dfd-417c-b8b7-b994ae33632e', '洛陽人嘲跋異', '洛陽人嘲跋異', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["赫赫洛下，唯說異畫。","張氏出頭，跋異無價。"]', '["赫赫洛下，唯说異畫。","張氏出头，跋異無價。"]', '诗', 'shi', '', NULL, '洛陽人嘲跋異 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6da05223-3b72-42fb-9658-38fdaec440ce', '又嘲', '又嘲', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["李生來，跋君怕。","不意今日却增價，不畫羅漢畫駝馬。"]', '["李生来，跋君怕。","不意今日却增價，不畫羅漢畫駝马。"]', '诗', 'shi', '', NULL, '又嘲 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44bc6d62-8d14-45e7-9d65-1ed935fb9419', '蜀選人嘲韓昭', '蜀選人嘲韓昭', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["嘉眉邛蜀，侍郎骨肉。","導江青城，侍郎情親。","果閬二州，侍郎自留。","巴蓬集壁，侍郎不識。"]', '["嘉眉邛蜀，侍郎骨肉。","導江青城，侍郎情親。","果閬二州，侍郎自留。","巴蓬集壁，侍郎不識。"]', '诗', 'shi', '', NULL, '蜀選人嘲韓昭 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40d7d764-f91d-4df8-ba85-df33d0541d65', '嘲傴僂人', '嘲傴僂人', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["拄杖欲似乃，播笏還似及。","逆風盪雨行，面乾頂額溼。","著衣牀上坐，肚緩脊皮急。","城門爾許高，故自匍匐入。"]', '["拄杖欲似乃，播笏還似及。","逆风盪雨行，面乾頂額溼。","著衣牀上坐，肚緩脊皮急。","城门爾許高，故自匍匐入。"]', '诗', 'shi', '', NULL, '嘲傴僂人 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8038ea3f-a055-4b6b-9bd0-0890a963906d', '曲中唱語', '曲中唱語', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["張公喫酒李公顛，盛六生兒鄭九憐。","舍下雄雞傷一德，南頭小鳳納三千。"]', '["張公喫酒李公顛，盛六生兒鄭九怜。","舍下雄雞傷一德，南头小鳳納三千。"]', '诗', 'shi', '', NULL, '曲中唱語 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c63464d-69b0-429a-ab53-36103c0b73a7', '改唱', '改唱', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["張公喫酒李公顛，盛六生兒鄭九憐。","舍下雄雞失一足，街頭小福拉三拳。"]', '["張公喫酒李公顛，盛六生兒鄭九怜。","舍下雄雞失一足，街头小福拉三拳。"]', '诗', 'shi', '', NULL, '改唱 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29d21c88-83d0-4fdb-b472-eb79ed7ab89f', '街中又唱', '街中又唱', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["莫將龐大作荍團，龐大皮中的不乾。","不怕鳳皇當額打，更將雞脚用筋纏。"]', '["莫將龐大作荍團，龐大皮中的不乾。","不怕鳳皇當額打，更將雞脚用筋纏。"]', '诗', 'shi', '', NULL, '街中又唱 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae73c78d-eb09-4f15-86c6-31b5830979ed', '吹火詩 一', '吹火诗 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["吹火朱脣動，添薪玉腕斜。","遙看煙裏面，大似霧中花。"]', '["吹火朱脣动，添薪玉腕斜。","遙看煙裏面，大似霧中花。"]', '诗', 'shi', '', NULL, '吹火詩 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c79e8e7-0b15-4065-81bc-7363c8ebf2c4', '吹火詩 二', '吹火诗 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["吹火青脣動，添薪黑腕斜。","遙看煙裏面，恰似鳩盤荼。"]', '["吹火青脣动，添薪黑腕斜。","遙看煙裏面，恰似鳩盤荼。"]', '诗', 'shi', '', NULL, '吹火詩 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2516272c-7d3f-400c-91a8-b8d995bab96b', '劉黑闥解嘲人語 一', '劉黑闥解嘲人語 一', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["水惡，頭如鎌杓尾如鑿，河裏搦魚無僻錯。"]', '["水惡，头如鎌杓尾如鑿，河裏搦鱼無僻錯。"]', '诗', 'shi', '', NULL, '劉黑闥解嘲人語 一 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9675ec54-ca70-4c0f-8acf-045d8c8f85c2', '劉黑闥解嘲人語 二', '劉黑闥解嘲人語 二', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["駱駝，項曲綠蹄，被他負物多。"]', '["駱駝，項曲綠蹄，被他負物多。"]', '诗', 'shi', '', NULL, '劉黑闥解嘲人語 二 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('564634ff-045a-4be3-90db-9d99402787d1', '村人學解嘲人語', '村人学解嘲人語', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["緜絹，割兩耳，只有面。"]', '["緜絹，割兩耳，只有面。"]', '诗', 'shi', '', NULL, '村人學解嘲人語 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b519377e-7d5e-4ecd-94c6-1f8254036ccc', '嘲劉師老', '嘲劉師老', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["大府朝天升穆老，尚書倒地落劉郎。"]', '["大府朝天升穆老，尚书倒地落劉郎。"]', '诗', 'shi', '', NULL, '嘲劉師老 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fef721e-4cb9-437d-82de-131a272a0ca2', '嘲鄭薫', '嘲鄭薫', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["主司頭腦太冬烘，錯認顏標作魯公。"]', '["主司头腦太冬烘，錯認顏標作魯公。"]', '诗', 'shi', '', NULL, '嘲鄭薫 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1671bdf8-5039-41ec-bffb-40dc5eda4b08', '嘲蔣蟠金丹', '嘲蔣蟠金丹', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["張鵠只消千馱絹，蔣蟠惟用一丸丹。"]', '["張鵠只消千馱絹，蔣蟠惟用一丸丹。"]', '诗', 'shi', '', NULL, '嘲蔣蟠金丹 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5198b618-4dcd-4c30-af3f-732476c12663', '注苗張二進士題名', '注苗張二進士題名', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["一雙前進士，兩箇阿孩兒。"]', '["一雙前進士，兩箇阿孩兒。"]', '诗', 'shi', '', NULL, '注苗張二進士題名 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('adfe4786-20c0-42d3-87f9-104351ae2929', '袁州人謔彭伉', '袁州人謔彭伉', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["湛賁及第，彭伉落驢。"]', '["湛賁及第，彭伉落驢。"]', '诗', 'shi', '', NULL, '袁州人謔彭伉 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc07c340-a81b-4fdb-9f86-381dad6081d1', '洛中人語', '洛中人語', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["昔樓師德園，今袁德師樓。"]', '["昔楼師德园，今袁德師楼。"]', '诗', 'shi', '', NULL, '洛中人語 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('98db2114-6d06-4715-b152-59705771eb38', '嘲毛炳彭會', '嘲毛炳彭會', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["彭生作賦茶三片，毛氏傳詩酒半升。"]', '["彭生作賦茶三片，毛氏傳诗酒半升。"]', '诗', 'shi', '', NULL, '嘲毛炳彭會 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9ff621c-f53b-4ba2-b784-8d9bdd85845e', '右威衛嘲語', '右威衛嘲語', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["門緣御史塞，廳被校書侵。"]', '["门緣御史塞，廳被校书侵。"]', '诗', 'shi', '', NULL, '右威衛嘲語 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccec185e-cbe6-4797-9523-5debbb8252dc', '南唐伶人獻先主詞', '南唐伶人獻先主词', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["惟願普天多瑞慶，柳條結絮鵝雙生。"]', '["惟願普天多瑞慶，柳條結絮鵝雙生。"]', '诗', 'shi', '', NULL, '南唐伶人獻先主詞 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7580f868-fbc8-4b48-bf03-0f3534700ddc', '閩伶官戲主延政語', '閩伶官戲主延政語', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["只聞有泗州和尚，不見有五縣天子。"]', '["只闻有泗州和尚，不见有五縣天子。"]', '诗', 'shi', '', NULL, '閩伶官戲主延政語 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4feab68b-4a3d-4a97-ab54-6100b5dfa08c', '言志', '言志', '3fef2451-3384-4e62-9fb2-2e1e3fb62673', '唐', '["腰纏十萬貫，騎鶴上揚州。"]', '["腰纏十万貫，騎鹤上揚州。"]', '诗', 'shi', '', NULL, '言志 無名氏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9209f946-c955-4693-bd46-750bffe36fae', '題洛陽縣壁', '題洛陽縣壁', '8eb74955-6a0f-4f7a-a07b-f3ff210f36d4', '唐', '["猾吏畏服，縣妖破膽。","好錄政聲，聞於御覽。"]', '["猾吏畏服，縣妖破膽。","好錄政声，闻於御覽。"]', '诗', 'shi', '', NULL, '題洛陽縣壁 李兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8443bd6-5b54-4313-9e9d-3ceeac3329b0', '題書卷後語', '題书卷後語', '7e30a134-5e2c-4e97-b806-f01b323a04fb', '唐', '["倩俸寫來手自校，汝曹讀之知聖道，墜之鬻之爲不孝。"]', '["倩俸寫来手自校，汝曹读之知聖道，墜之鬻之爲不孝。"]', '诗', 'shi', '', NULL, '題書卷後語 杜兼 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e66a11bf-1cd1-488e-bd56-d04fd91bcdd4', '題李陽冰玉箸篆詞', '題李陽冰玉箸篆词', 'ca192c17-2433-4371-a87b-d46bb9c29767', '唐', '["斯去千年，冰生唐時。","冰復去矣，後來者誰。","後千年有人，誰來待之。","後千年無人，篆止於斯。","嗚呼主人，爲吾寶之。"]', '["斯去千年，冰生唐时。","冰复去矣，後来者誰。","後千年有人，誰来待之。","後千年無人，篆止於斯。","嗚呼主人，爲吾寶之。"]', '诗', 'shi', '', NULL, '題李陽冰玉箸篆詞 舒元輿 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d31261bd-f276-46f4-98da-3b33e997b3bb', '判誤書紙背', '判誤书紙背', 'b9df6e3d-9d15-4d38-8d8f-323541f3df7a', '唐', '["這畔似那畔，那畔似這畔。","我也不辭與你判，笑殺門前著鞾漢。"]', '["這畔似那畔，那畔似這畔。","我也不辞與你判，笑殺门前著鞾漢。"]', '诗', 'shi', '', NULL, '判誤書紙背 裴諝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('38c223e9-27da-4342-a0aa-13e57cbb758f', '又判爭貓兒狀', '又判爭貓兒狀', 'b9df6e3d-9d15-4d38-8d8f-323541f3df7a', '唐', '["貓兒不識主，傍家搦老鼠。","兩家不須爭，將來與裴諝。"]', '["貓兒不識主，傍家搦老鼠。","兩家不須爭，將来與裴諝。"]', '诗', 'shi', '', NULL, '又判爭貓兒狀 裴諝 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3e24873-d22c-4333-80dd-3dcc33378eec', '斷僧通狀', '斷僧通狀', '0766d938-3153-48c9-af84-d35b0d1dfbb9', '唐', '["上歲童子，二十受戒。","君王不朝，父母不拜。","口稱貧道，有錢放債。","量決十下，牒出東界。"]', '["上歲童子，二十受戒。","君王不朝，父母不拜。","口稱貧道，有錢放債。","量決十下，牒出东界。"]', '诗', 'shi', '', NULL, '斷僧通狀 李翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cc810091-de2b-4690-b53a-01e6d6a8c1d1', '判僧雲晏五人聚賭喧諍語', '判僧云晏五人聚賭喧諍語', '99df2fff-254f-450a-af49-6675d131ee01', '唐', '["正法何曾執貝，空門不積餘財。","白日既能賭博，通宵必醉尊罍。","強說天堂難到，又言地獄長開。","竝付江神收管，波中便是泉臺。"]', '["正法何曾執貝，空门不積餘財。","白日既能賭博，通宵必醉尊罍。","強说天堂难到，又言地獄长开。","竝付江神收管，波中便是泉台。"]', '诗', 'shi', '', NULL, '判僧雲晏五人聚賭喧諍語 韓滉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('31478bee-8a3d-4f10-9cad-f107425159d0', '判道士黃山隱', '判道士黄山隐', '73bd76b9-c25c-4651-a86f-5c3d2ceeebe1', '唐', '["道士黃山隱，輕人復重財。","太山將比甑，東海只容杯。","綠綬藏雲帔，烏巾換鹿胎。","黃泉六箇鬼，今夜待君來。"]', '["道士黄山隐，轻人复重財。","太山將比甑，东海只容杯。","綠綬藏云帔，烏巾換鹿胎。","黄泉六箇鬼，今夜待君来。"]', '诗', 'shi', '', NULL, '判道士黃山隱 皇甫大夫 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('da8dc3ec-92fa-4a81-b1ed-c61be4034e18', '碾驢鞍判', '碾驢鞍判', 'a14517f7-62ed-4099-83d0-ed84131af31f', '唐', '["鄴城大道甚寬，何故駕車碾鞍。","領鞴驢漢子科決，待駕車漢子喜歡。"]', '["鄴城大道甚寬，何故駕车碾鞍。","領鞴驢漢子科決，待駕车漢子喜歡。"]', '诗', 'shi', '', NULL, '碾驢鞍判 羅紹威 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de88950a-1521-4601-9299-28bc59e91c6a', '批州符', '批州符', '2f30c275-8aab-47c6-abbf-a836aec65f0e', '唐', '["秧開五葉，蠶長三眠。","人皆忙迫，划甚閑船。"]', '["秧开五葉，蠶长三眠。","人皆忙迫，划甚闲船。"]', '诗', 'shi', '', NULL, '批州符 蕭結 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a7641490-8a0a-477f-ba22-899956ca194f', '判部民訴主簿牒', '判部民訴主簿牒', 'bb5e4a8c-b054-44b3-8c6f-ba86f71f4514', '唐', '["汝雖打草，吾已驚蛇。"]', '["汝雖打草，吾已驚蛇。"]', '诗', 'shi', '', NULL, '判部民訴主簿牒 王魯 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('42f598a7-4bf4-406d-acb7-777db826b5b5', '戲爲冥吏判', '戲爲冥吏判', 'ebba9a6d-2599-49da-9b6a-8be8a25ad019', '唐', '["焦湖百里，一任作獺。"]', '["焦湖百里，一任作獺。"]', '诗', 'shi', '', NULL, '戲爲冥吏判 伶人 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c744e1ac-f7a5-4555-9259-2abe1cfe174b', '自狀', '自狀', 'b1aee750-c96b-497d-a91a-3f8841594b56', '唐', '["有張翱兮，寓止淮陰。","來綺席兮，放恣胸襟。"]', '["有張翱兮，寓止淮陰。","来綺席兮，放恣胸襟。"]', '诗', 'shi', '', NULL, '自狀 張翱 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('323ca1fe-a14b-4c9e-ae1d-cf47caff24e0', '刺左右膊詩', '刺左右膊诗', '6c8f83c3-583d-415f-a8b2-32e448d1e046', '唐', '["野鴨灘頭宿，朝朝被鶻梢。","忽驚飛入水，留命到今朝。"]', '["野鴨灘头宿，朝朝被鶻梢。","忽驚飞入水，留命到今朝。"]', '诗', 'shi', '', NULL, '刺左右膊詩 趙武建 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5734785e-d2ac-4de7-98d5-d003460e8560', '刺左臂膊詩', '刺左臂膊诗', 'a664ad66-39fb-44e9-80ce-494d66e41a0f', '唐', '["昔日已前家未貧，苦將錢物結交親。","如今失路尋知己，行盡關山無一人。"]', '["昔日已前家未貧，苦將錢物結交親。","如今失路尋知己，行尽关山無一人。"]', '诗', 'shi', '', NULL, '刺左臂膊詩 宋元素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0beba024-21de-41e7-90d2-296710dae268', '刺左右膊句', '刺左右膊句', 'b9c795c0-c48f-452e-94da-24dfa80662ce', '唐', '["生不怕京兆尹，死不畏閻羅王。"]', '["生不怕京兆尹，死不畏閻羅王。"]', '诗', 'shi', '', NULL, '刺左右膊句 張幹 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f5e0ea5-f41a-4cd4-a777-62f9e909db06', '廉州人歌', '廉州人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["廉州顏有道，性行同莊老。","愛民如赤子，不殺非時草。"]', '["廉州顏有道，性行同莊老。","愛民如赤子，不殺非时草。"]', '诗', 'shi', '', NULL, '廉州人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3ff3491-11de-4b09-a69a-87a928eaf626', '滄州百姓歌', '滄州百姓歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["新河得通舟楫利，直達滄海魚鹽至。","昔日徒行今騁駟，美哉薛公德滂被。"]', '["新河得通舟楫利，直達滄海鱼鹽至。","昔日徒行今騁駟，美哉薛公德滂被。"]', '诗', 'shi', '', NULL, '滄州百姓歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6f9d034e-c8a3-42dd-b925-5038877a8d83', '薛將軍歌', '薛將軍歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["將軍三箭定天山，戰士長歌入漢關。"]', '["將軍三箭定天山，戰士长歌入漢关。"]', '诗', 'shi', '', NULL, '薛將軍歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30a4a41c-c494-41ea-bddb-f93fedfb8eaa', '郢州人歌', '郢州人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["父母育我田使君，精神爲人上天聞。","田中致雨山出雲，但願常在不患貧。"]', '["父母育我田使君，精神爲人上天闻。","田中致雨山出云，但願常在不患貧。"]', '诗', 'shi', '', NULL, '郢州人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1ec01a6b-6def-4ba6-88ca-893c80e5d81b', '雒縣輿人誦', '雒縣輿人誦', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我有聖帝撫令君，遭暴昏椽惸寡紛。","民戶流散日月曛，君去來兮惠我仁，百姓蘇矣見陽春。"]', '["我有聖帝撫令君，遭暴昏椽惸寡紛。","民戶流散日月曛，君去来兮惠我仁，百姓蘇矣见陽春。"]', '诗', 'shi', '', NULL, '雒縣輿人誦 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e0c0f23-3184-4f95-b532-557ba6f1ec21', '黃麞歌', '黄麞歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黃麞黃麞草裏藏，彎弓射爾傷。"]', '["黄麞黄麞草裏藏，彎弓射爾傷。"]', '诗', 'shi', '', NULL, '黃麞歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45b14007-517b-4395-b605-6aa2c596bd45', '桑條歌', '桑條歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桑條韋也，女時韋也樂。"]', '["桑條韋也，女时韋也乐。"]', '诗', 'shi', '', NULL, '桑條歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81e6b195-a2e8-4e80-891e-b6b639567a8c', '景龍中嘲宰相歌', '景龙中嘲宰相歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["禮賢不解開東閣，燮理惟能閉北門。"]', '["禮賢不解开东閣，燮理惟能閉北门。"]', '诗', 'shi', '', NULL, '景龍中嘲宰相歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e1c8c16-5f05-4061-851c-d3dc8495c1fb', '選人歌', '選人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["今年選數恰相當，都由座主無文章。","案後一腔凍豬肉，所以名爲姜侍郎。"]', '["今年選數恰相當，都由座主無文章。","案後一腔凍豬肉，所以名爲姜侍郎。"]', '诗', 'shi', '', NULL, '選人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('896aa8ec-e49e-48d0-9270-7d02200030b1', '魯城民歌', '魯城民歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["魯地抑種稻，一概被水沫。","年年索蟹夫，百姓不可活。"]', '["魯地抑種稻，一概被水沫。","年年索蟹夫，百姓不可活。"]', '诗', 'shi', '', NULL, '魯城民歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9e71817-fe54-4513-a974-e30342a6a0d2', '王法曹歌', '王法曹歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["前得尹佛子，後得王癩獺。","判事驢齩瓜，喚人牛嚼沫。","見錢滿面喜，無鏹從頭喝。","常逢餓夜叉，百姓不可活。"]', '["前得尹佛子，後得王癩獺。","判事驢齩瓜，喚人牛嚼沫。","见錢满面喜，無鏹從头喝。","常逢餓夜叉，百姓不可活。"]', '诗', 'shi', '', NULL, '王法曹歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90eafc7b-3e02-4a91-8b8a-8ba4e135a45a', '得体歌', '得体歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得体紇那也，紇囊得体那。","潭裏船車鬧，揚州銅器多。","三郎當殿坐，聽唱得体歌。"]', '["得体紇那也，紇囊得体那。","潭裏船车鬧，揚州銅器多。","三郎當殿坐，听唱得体歌。"]', '诗', 'shi', '', NULL, '得体歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc2cf25b-c135-48a9-8554-7e6c125201e7', '得寶歌', '得寶歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得寶耶，弘農耶。","弘農耶，得寶耶。"]', '["得寶耶，弘農耶。","弘農耶，得寶耶。"]', '诗', 'shi', '', NULL, '得寶歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4829441-d859-4e16-840d-814c9d5487f4', '崔成甫飜得寶歌', '崔成甫飜得寶歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["得寶弘農野，弘農得寶那。","潭裏船車鬧，揚州銅器多。","三郎當殿坐，聽唱得寶歌。"]', '["得寶弘農野，弘農得寶那。","潭裏船车鬧，揚州銅器多。","三郎當殿坐，听唱得寶歌。"]', '诗', 'shi', '', NULL, '崔成甫飜得寶歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8b03efb-eb16-4b46-b900-22b27e17214b', '袁仁敬歌', '袁仁敬歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天不恤冤人兮，何奪我慈親兮。","有理無申兮，痛哉安訴陳兮。"]', '["天不恤冤人兮，何奪我慈親兮。","有理無申兮，痛哉安訴陳兮。"]', '诗', 'shi', '', NULL, '袁仁敬歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2b4d1c9-9dcb-48b0-b9fe-fa9591ff4bc8', '京兆二尹歌', '京兆二尹歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["前尹赫赫，具瞻允若。","後尹熙熙，具瞻允斯。"]', '["前尹赫赫，具瞻允若。","後尹熙熙，具瞻允斯。"]', '诗', 'shi', '', NULL, '京兆二尹歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('773861bf-936b-4c1e-b448-347360f05cc2', '黃州左公歌', '黄州左公歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我欲逃鄉里，我欲去墳墓。","左公今既來，誰忍棄之去。"]', '["我欲逃乡里，我欲去墳墓。","左公今既来，誰忍棄之去。"]', '诗', 'shi', '', NULL, '黃州左公歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e614240c-957a-48ab-bbdd-b3896325e818', '又歌', '又歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["吾鄉有鬼巫，惑人人不知。","天子正尊信，左公能殺之。"]', '["吾乡有鬼巫，惑人人不知。","天子正尊信，左公能殺之。"]', '诗', 'shi', '', NULL, '又歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09cb80b0-0414-425b-a7a8-3e555fa7a622', '舒州人歌', '舒州人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["鄰邑谷不登，我土豐粢盛。","禾稼美如雲，實繫我使君。"]', '["鄰邑谷不登，我土豐粢盛。","禾稼美如云，實繫我使君。"]', '诗', 'shi', '', NULL, '舒州人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aae5d506-db9d-48df-a491-6d0be69ff50b', '建州人歌 一', '建州人歌 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["令我州郡泰，令我戶口裕。","令我活計大，陸員外。"]', '["令我州郡泰，令我戶口裕。","令我活計大，陸員外。"]', '诗', 'shi', '', NULL, '建州人歌 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be8607c3-f3e3-4d88-bbf4-7e5262440aa7', '建州人歌 二', '建州人歌 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["令我家不分，令我馬成羣。","令我稻滿囷，陸使君。"]', '["令我家不分，令我马成羣。","令我稻满囷，陸使君。"]', '诗', 'shi', '', NULL, '建州人歌 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c1d178d6-2b66-4ad7-a582-f3edcbe16dc7', '吳人歌', '吳人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["朝判長洲暮判吳，道不拾遺人不孤。"]', '["朝判长洲暮判吳，道不拾遺人不孤。"]', '诗', 'shi', '', NULL, '吳人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e33a3f4-3de4-49d9-aabe-a6ef5eff7871', '汴州人歌 一', '汴州人歌 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["濁流洋洋，有闢其郛。","闐道歡呼，公來之初。","今公之歸，公在喪車。"]', '["濁流洋洋，有闢其郛。","闐道歡呼，公来之初。","今公之归，公在喪车。"]', '诗', 'shi', '', NULL, '汴州人歌 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a5e9ef55-de31-444e-8009-1c14ee7696ad', '汴州人歌 二', '汴州人歌 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["公既來止，東人以完。","今公歿矣，人誰與安。"]', '["公既来止，东人以完。","今公歿矣，人誰與安。"]', '诗', 'shi', '', NULL, '汴州人歌 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ea104cad-fd33-4747-a9be-258e5216a8be', '建昌民歌', '建昌民歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["我有父，何易于。","昔無儲，今有餘。"]', '["我有父，何易于。","昔無儲，今有餘。"]', '诗', 'shi', '', NULL, '建昌民歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476730d9-bec6-4649-b20b-e79c48f272b2', '巴州薛刺史歌', '巴州薛刺史歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["日出而耕，日入而歸。","吏不到門，夜不掩扉。","有孩有童，願以名垂。","何以字之，薛孫薛兒。"]', '["日出而耕，日入而归。","吏不到门，夜不掩扉。","有孩有童，願以名垂。","何以字之，薛孫薛兒。"]', '诗', 'shi', '', NULL, '巴州薛刺史歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1dab8453-d93d-4c64-809d-1d2310ee9d97', '高苑令歌', '高苑令歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["高苑之樹枯已榮，淄川之水渾已澄，鄒邑之民仆已行。"]', '["高苑之樹枯已榮，淄川之水渾已澄，鄒邑之民仆已行。"]', '诗', 'shi', '', NULL, '高苑令歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8db84576-ab49-46c2-8d6e-af645456df88', '九龍帳歌', '九龙帳歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["誰謂九龍帳，惟貯一歸郎。"]', '["誰謂九龙帳，惟貯一归郎。"]', '诗', 'shi', '', NULL, '九龍帳歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b1a33c6f-9e44-426e-bee5-b6c5b638f215', '僞蜀鴛鴦樹歌', '僞蜀鴛鴦樹歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["願作墳上鴛鴦，來作雙飛，去作雙歸。"]', '["願作墳上鴛鴦，来作雙飞，去作雙归。"]', '诗', 'shi', '', NULL, '僞蜀鴛鴦樹歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff95ecc0-970c-4262-b552-25353f836e46', '曲江遊人歌', '曲江游人歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["春光且莫去，留與醉人看。"]', '["春光且莫去，留與醉人看。"]', '诗', 'shi', '', NULL, '曲江遊人歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('400234cb-e3a0-458f-aa14-371145228adc', '蜥蜴求雨歌', '蜥蜴求雨歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["蜥蜴蜥蜴，興雲吐霧。","雨若滂沱，放汝歸去。"]', '["蜥蜴蜥蜴，兴云吐霧。","雨若滂沱，放汝归去。"]', '诗', 'shi', '', NULL, '蜥蜴求雨歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('107e29de-cdf4-4201-a165-49dde7a81672', '輓歌', '輓歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["紅輪決定沈西去，未委魂靈往那方。"]', '["紅輪決定沈西去，未委魂靈往那方。"]', '诗', 'shi', '', NULL, '輓歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6fbe3e3-eb02-4b84-97c7-bc45e2e207c0', '唐受命讖 一', '唐受命讖 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["法律存，道德在，白旗天子出東海。"]', '["法律存，道德在，白旗天子出东海。"]', '诗', 'shi', '', NULL, '唐受命讖 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b3af511-3a74-4650-b5e9-c818590c9d42', '唐受命讖 二', '唐受命讖 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桃李子，莫浪語。","黃鵠繞山飛，宛轉花園裏。"]', '["桃李子，莫浪語。","黄鵠繞山飞，宛轉花园裏。"]', '诗', 'shi', '', NULL, '唐受命讖 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('797b7c60-f97f-402c-bf72-5ac14c352ae5', '唐受命讖 三', '唐受命讖 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桃花園，宛轉屬旌幡。"]', '["桃花园，宛轉屬旌幡。"]', '诗', 'shi', '', NULL, '唐受命讖 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d41eca91-7854-4117-9d30-127fb0e2c9fe', '唐受命讖 四', '唐受命讖 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桃李子，鴻鵠繞陽山，宛轉花林裏。","莫浪語，誰道許。"]', '["桃李子，鴻鵠繞陽山，宛轉花林裏。","莫浪語，誰道許。"]', '诗', 'shi', '', NULL, '唐受命讖 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c93559bd-bd62-4dd6-b0d8-4ccb36e005ac', '唐受命讖 五', '唐受命讖 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["桃李子，洪水繞楊山。"]', '["桃李子，洪水繞楊山。"]', '诗', 'shi', '', NULL, '唐受命讖 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a6796fa2-6240-4c67-8cca-88996868b28b', '唐受命讖 六', '唐受命讖 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["江南楊柳樹，江北李花榮。","楊柳飛緜何處去，李花結果自然成。"]', '["江南楊柳樹，江北李花榮。","楊柳飞緜何处去，李花結果自然成。"]', '诗', 'shi', '', NULL, '唐受命讖 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46019415-cbb4-4d0f-984f-9e4f6531c977', '勸進疏引讖 一', '勸進疏引讖 一', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["東海十八子，八井喚三軍。","手持雙白雀，頭上戴紫雲。"]', '["东海十八子，八井喚三軍。","手持雙白雀，头上戴紫云。"]', '诗', 'shi', '', NULL, '勸進疏引讖 一 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b320bdb-496b-4539-8ceb-b7939564d6f4', '勸進疏引讖 二', '勸進疏引讖 二', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["丁丑語甲子，深藏八堂裏。","何意坐堂裏，中央有天子。"]', '["丁丑語甲子，深藏八堂裏。","何意坐堂裏，中央有天子。"]', '诗', 'shi', '', NULL, '勸進疏引讖 二 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d32fa3ca-29e4-46ea-85a9-963d368cfc44', '勸進疏引讖 三', '勸進疏引讖 三', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["西北天火照，龍山昭童子，赤光連北斗。","童子木上懸白幡，胡兵紛紛滿前後。","拍手唱堂堂，驅羊向南走。"]', '["西北天火照，龙山昭童子，赤光連北斗。","童子木上懸白幡，胡兵紛紛满前後。","拍手唱堂堂，驱羊向南走。"]', '诗', 'shi', '', NULL, '勸進疏引讖 三 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('566575c5-7c22-45c3-bc66-ba05a6fc9dcf', '勸進疏引讖 四', '勸進疏引讖 四', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["胡兵未濟漢不整，治中都護有八井。"]', '["胡兵未濟漢不整，治中都護有八井。"]', '诗', 'shi', '', NULL, '勸進疏引讖 四 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('740b83b8-a30f-41f6-ad4d-dd4839176c37', '勸進疏引讖 五', '勸進疏引讖 五', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["興伍伍，仁義行武。","得九九，得聲名。","童子木底百丈水，東家井裏五色星。","我語不可信，問取衛先生。"]', '["兴伍伍，仁義行武。","得九九，得声名。","童子木底百丈水，东家井裏五色星。","我語不可信，问取衛先生。"]', '诗', 'shi', '', NULL, '勸進疏引讖 五 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c975615a-8a7e-4a17-b760-471ece9c132e', '勸進疏引讖 六', '勸進疏引讖 六', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["戌亥君臣亂，子丑破城隍。","寅卯如欲定，龍蛇伏四方。","十八成男子，洪水主刀傍。","市朝義歸政，人寧俱不荒。","人言有恆性，也復道非常。","爲君好思量，何□□禹湯。","桃源花□□，李樹起堂堂。","只看寅卯歲，深水沒黃楊。"]', '["戌亥君臣亂，子丑破城隍。","寅卯如欲定，龙蛇伏四方。","十八成男子，洪水主刀傍。","市朝義归政，人寧俱不荒。","人言有恆性，也复道非常。","爲君好思量，何□□禹湯。","桃源花□□，李樹起堂堂。","只看寅卯歲，深水沒黄楊。"]', '诗', 'shi', '', NULL, '勸進疏引讖 六 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c43df912-7292-4e5f-9287-6e5b7287e088', '符鳳引讖', '符鳳引讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["黑衣神孫披天裳。"]', '["黑衣神孫披天裳。"]', '诗', 'shi', '', NULL, '符鳳引讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d8a264b-621a-4afa-a571-73e44bea1b1c', '安祿山古讖', '安祿山古讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["兩角女子綠衣裳，端坐太行邀君王，一止之月必消亡。"]', '["兩角女子綠衣裳，端坐太行邀君王，一止之月必消亡。"]', '诗', 'shi', '', NULL, '安祿山古讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('79f96849-12d5-4b60-8fcc-bce35a766886', '普滿題潞州佛舍', '普满題潞州佛舍', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["此水連涇水，雙珠血滿川。","青牛將赤虎，還號太平年。"]', '["此水連涇水，雙珠血满川。","青牛將赤虎，還號太平年。"]', '诗', 'shi', '', NULL, '普滿題潞州佛舍 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8790640-aea3-44b1-8794-a297f7b339ee', '南省北街人吟', '南省北街人吟', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["放牓只應三月暮，登科又校一年遲。"]', '["放牓只應三月暮，登科又校一年遲。"]', '诗', 'shi', '', NULL, '南省北街人吟 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3cc8d29-0de3-4516-9b9f-0b8e89d4276c', '盧求牓讖', '盧求牓讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["裴頭黃尾，三求六李。"]', '["裴头黄尾，三求六李。"]', '诗', 'shi', '', NULL, '盧求牓讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('45267eab-d914-4438-b1f1-004c45dc8e66', '清僧示趙宗儒', '清僧示趙宗儒', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["棃花發後杏花初，甸邑南來慶有餘。"]', '["棃花發後杏花初，甸邑南来慶有餘。"]', '诗', 'shi', '', NULL, '清僧示趙宗儒 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a0288aa-fc66-4d72-9536-a6ece55bf3ec', '又示段文昌', '又示段文昌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["去日既逢梅蘂綻，來時應見杏花開。"]', '["去日既逢梅蘂綻，来时應见杏花开。"]', '诗', 'shi', '', NULL, '又示段文昌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de39890-6bff-47b6-8425-0d0794a94412', '洛城五鳳樓中歌', '洛城五鳳楼中歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天津橋畔火光起，魏王堤上看洪水。"]', '["天津橋畔火光起，魏王堤上看洪水。"]', '诗', 'shi', '', NULL, '洛城五鳳樓中歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6606baa-2788-4737-a8d6-6e789ee54055', '延和閣詩', '延和閣诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["延和高閣上干雲，小語猶疑太乙聞。","燒盡降真無一事，開門迎得畢將軍。"]', '["延和高閣上干云，小語猶疑太乙闻。","燒尽降真無一事，开门迎得畢將軍。"]', '诗', 'shi', '', NULL, '延和閣詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0669ab73-31c8-446d-99ae-61dc7c96e8c7', '唐舊讖', '唐旧讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["兔子上金牀。"]', '["兔子上金牀。"]', '诗', 'shi', '', NULL, '唐舊讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd298e7d-bb53-4a10-bd4a-f0c2840d7b9d', '越中狂生題旗亭', '越中狂生題旗亭', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["日日草重生，悠悠傍秦城。","諸侯逐兔白，夏滿鏡湖平。"]', '["日日草重生，悠悠傍秦城。","諸侯逐兔白，夏满镜湖平。"]', '诗', 'shi', '', NULL, '越中狂生題旗亭 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1130a6a2-4516-4ee2-af80-c21b5d42b6ad', '清泰三年歌', '清泰三年歌', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["丙申年，數在五樓前。","但看八九月，胡虜亂中原。"]', '["丙申年，數在五楼前。","但看八九月，胡虜亂中原。"]', '诗', 'shi', '', NULL, '清泰三年歌 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c71bcfc7-14a3-4463-8655-a571adc35e4a', '蜀王氏讖文', '蜀王氏讖文', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["李祜西王逢吉昌，上德兌興丹莫當。"]', '["李祜西王逢吉昌，上德兌兴丹莫當。"]', '诗', 'shi', '', NULL, '蜀王氏讖文 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('caeafb82-fa6a-4df6-91e6-9be6a9dba072', '黃萬祜題蜀宮壁', '黄万祜題蜀宮壁', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫交牽動青豬足，動即炎炎不可撲。","鷙獸不欲兩頭黃，黃即其年天下哭。"]', '["莫交牽动青豬足，动即炎炎不可撲。","鷙獸不欲兩头黄，黄即其年天下哭。"]', '诗', 'shi', '', NULL, '黃萬祜題蜀宮壁 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9632e076-0011-44ef-96bc-dd6445252e2a', '孟蜀丐者語', '孟蜀丐者語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不得登，登便倒。"]', '["不得登，登便倒。"]', '诗', 'shi', '', NULL, '孟蜀丐者語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12d19b09-970c-443f-8c83-52b15fffb02d', '孟蜀桃符詩', '孟蜀桃符诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["新年納餘慶，嘉節號長春。"]', '["新年納餘慶，嘉節號长春。"]', '诗', 'shi', '', NULL, '孟蜀桃符詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ed52ca89-70c1-4f08-8240-cfd4da3e3e59', '上藍和尚晉漢二代讖', '上藍和尚晉漢二代讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["石榴花發石榴開。"]', '["石榴花發石榴开。"]', '诗', 'shi', '', NULL, '上藍和尚晉漢二代讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2794613d-c31d-458f-be66-719563e8e525', '又遺鍾傳偈', '又遺鍾傳偈', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["但看來年二三月，柳條堪作打鐘槌。"]', '["但看来年二三月，柳條堪作打鐘槌。"]', '诗', 'shi', '', NULL, '又遺鍾傳偈 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61b92c46-76c1-4fcb-824d-39f14eb82601', '又報王審知十字讖', '又報王審知十字讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["不怕羊入屋，只怕錢入腹。"]', '["不怕羊入屋，只怕錢入腹。"]', '诗', 'shi', '', NULL, '又報王審知十字讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('208fa8e7-dad9-4226-8c13-7e43c3fc5492', '錢處士李氏讖', '錢处士李氏讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["髣髴之間一倍楊。"]', '["髣髴之间一倍楊。"]', '诗', 'shi', '', NULL, '錢處士李氏讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2e18ee99-dfe4-47ce-a19c-bc8fbdb4ed3a', '孫咸題廬山神廟詩', '孫咸題廬山神廟诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["獨入玄宮禮至真，焚香不爲賤貧身。","秦淮兩岸沙埋骨，湓浦千家血染塵。","廬阜煙霞誰是主，虎溪風月屬何人。","九江太守勤王室，好放天兵渡要津。"]', '["独入玄宮禮至真，焚香不爲賤貧身。","秦淮兩岸沙埋骨，湓浦千家血染塵。","廬阜煙霞誰是主，虎溪风月屬何人。","九江太守勤王室，好放天兵渡要津。"]', '诗', 'shi', '', NULL, '孫咸題廬山神廟詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b39a689-d862-4d3d-9397-15c67fd59f33', '南唐江州風墜詩', '南唐江州风墜诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["由來秉節世無雙，獨守孤城死不降。","何似知機早回首，免教流血滿長江。"]', '["由来秉節世無雙，独守孤城死不降。","何似知機早回首，免教流血满长江。"]', '诗', 'shi', '', NULL, '南唐江州風墜詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cd4c3e1-4abf-4e38-8fa3-93dd7b0d7b9e', '杭州還鄉和尚唱', '杭州還乡和尚唱', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["還鄉寂寂杳無蹤，不挂征帆水陸通。","蹋得故鄉回地穩，更無南北與西東。"]', '["還乡寂寂杳無蹤，不挂征帆水陸通。","蹋得故乡回地穩，更無南北與西东。"]', '诗', 'shi', '', NULL, '杭州還鄉和尚唱 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('162eac2f-9ce7-4a3b-a2b8-76853563a8c4', '福州記', '福州記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["潮水來，巖頭沒。","潮水去，矢口出。"]', '["潮水来，巖头沒。","潮水去，矢口出。"]', '诗', 'shi', '', NULL, '福州記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a61c89c6-65de-4ffd-8600-8f7cce89a11b', '黃涅槃讖', '黄涅槃讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["先打南，後打北，留取清源作佛國。"]', '["先打南，後打北，留取清源作佛国。"]', '诗', 'shi', '', NULL, '黃涅槃讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fcc3fcf0-1122-4f0b-9412-664340a10534', '陳智廣讖', '陳智廣讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["騎馬來，騎馬去。"]', '["騎马来，騎马去。"]', '诗', 'shi', '', NULL, '陳智廣讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af91408-fdb5-43bb-9f05-cbfba3c3170c', '又讖', '又讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["功下田，力交連。","井底坐，二十年。"]', '["功下田，力交連。","井底坐，二十年。"]', '诗', 'shi', '', NULL, '又讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20b44e91-29f2-444f-b745-415e24f68614', '僧緘示王處厚', '僧緘示王处厚', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["周士同成，二王殊名。","王居一焉，百日爲程。"]', '["周士同成，二王殊名。","王居一焉，百日爲程。"]', '诗', 'shi', '', NULL, '僧緘示王處厚 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4de40025-fdd4-43cf-822a-f09f6224686b', '任叟書授劉生', '任叟书授劉生', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["承欲往梁宋，梁宋災方重。","旦夕爲人訟，承欲訪鄭生。","鄭生將有厄，即爲千里客，兼亦變衫色。"]', '["承欲往梁宋，梁宋災方重。","旦夕爲人訟，承欲訪鄭生。","鄭生將有厄，即爲千里客，兼亦变衫色。"]', '诗', 'shi', '', NULL, '任叟書授劉生 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('293b1796-ab54-40d1-92db-5b4319727956', '昌明里中讖', '昌明里中讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲知修續者，脚下是生毛。"]', '["欲知修續者，脚下是生毛。"]', '诗', 'shi', '', NULL, '昌明里中讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ca83dd60-d648-4104-969d-13525d661ccd', '宋善威詩', '宋善威诗', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["月落三株樹，日映九重天。","良夜歡宴罷，暫別庚申年。"]', '["月落三株樹，日映九重天。","良夜歡宴罷，暫別庚申年。"]', '诗', 'shi', '', NULL, '宋善威詩 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d643f49-362d-42a2-8058-3f220ad372af', '田承嗣誑李寶臣僞讖', '田承嗣誑李寶臣僞讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["二帝同功勢萬全，將田作伴入幽燕。"]', '["二帝同功勢万全，將田作伴入幽燕。"]', '诗', 'shi', '', NULL, '田承嗣誑李寶臣僞讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee4325dc-b923-4401-9ad9-6a2cf3848403', '皮日休造黃巢讖', '皮日休造黄巢讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["欲知聖人姓，田八二十一。","欲知聖人名，果頭三屈律。"]', '["欲知聖人姓，田八二十一。","欲知聖人名，果头三屈律。"]', '诗', 'shi', '', NULL, '皮日休造黃巢讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d5d6bca4-7f88-43f7-b410-fc00aa7f0f87', '上元初嵩山石記', '上元初嵩山石記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["木子當天下。","止戈龍。","李代代不移宗。","中鼎顯真容。","基千萬歲。"]', '["木子當天下。","止戈龙。","李代代不移宗。","中鼎显真容。","基千万歲。"]', '诗', 'shi', '', NULL, '上元初嵩山石記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('716e15a7-dc80-46b3-9155-7e0207014a5f', '上陽銅器篆', '上陽銅器篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["長宜子孫。"]', '["长宜子孫。"]', '诗', 'shi', '', NULL, '上陽銅器篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5082ad43-9f50-4664-a14c-d69c207ca244', '永安渠石銘', '永安渠石銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["百年爲市後爲池。"]', '["百年爲市後爲池。"]', '诗', 'shi', '', NULL, '永安渠石銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88a86386-a27a-4aaa-b0ca-3a264dbb1f9f', '漳泉分地神篆', '漳泉分地神篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["漳泉兩州，分地太平。","永安龍溪，山高氣清。","千年不惑，萬古作程。"]', '["漳泉兩州，分地太平。","永安龙溪，山高氣清。","千年不惑，万古作程。"]', '诗', 'shi', '', NULL, '漳泉分地神篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b897ae6d-1f25-4c73-adac-f12a13803be3', '含元殿丹石隱語', '含元殿丹石隐語', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["天漢二年，赤光生栗。","木下有子，傷心遇酷。"]', '["天漢二年，赤光生栗。","木下有子，傷心遇酷。"]', '诗', 'shi', '', NULL, '含元殿丹石隱語 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc428eb1-f8f7-4c0b-9cc3-0f6c010f8bc7', '長安空宅銘篆', '长安空宅銘篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["夏天子紫金三千斤，賜有德者。"]', '["夏天子紫金三千斤，賜有德者。"]', '诗', 'shi', '', NULL, '長安空宅銘篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0193d4af-9481-4066-a8b4-ea9bc185fb2b', '莆田石記', '莆田石記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["石敢當，鎮百鬼，壓災殃。","官吏福，百姓康。","風教盛，禮樂昌。"]', '["石敢當，鎮百鬼，壓災殃。","官吏福，百姓康。","风教盛，禮乐昌。"]', '诗', 'shi', '', NULL, '莆田石記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('105f5340-4763-4829-b3c2-8ebb426cbd0a', '符離樹穴中石篆', '符離樹穴中石篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["旁有水，上有道，八百年中逢栲栳。"]', '["旁有水，上有道，八百年中逢栲栳。"]', '诗', 'shi', '', NULL, '符離樹穴中石篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5132e200-c112-44ac-9872-2621fe04fe8e', '淮西池濠石銘', '淮西池濠石銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["井底一竿竹，竹色深綠綠。","雞未肥，酒未熟，障車兒郎且須縮。"]', '["井底一竿竹，竹色深綠綠。","雞未肥，酒未熟，障车兒郎且須縮。"]', '诗', 'shi', '', NULL, '淮西池濠石銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c8bc5f-3d8f-4c1d-9f71-9783e4f6f7fa', '羅池石刻', '羅池石刻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龍城柳，神所守。","驅厲鬼，山左首。","福士氓，制九醜。"]', '["龙城柳，神所守。","驱厲鬼，山左首。","福士氓，制九醜。"]', '诗', 'shi', '', NULL, '羅池石刻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e838ad-239f-4388-8acf-3290f9d0927b', '道者遺記', '道者遺記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["武之在卯，堯王八季。","我棄其寢，我去其扆。","深深然，高高然。","人不吾知，又不吾謂。","由今之後，二百餘祀。","燄燄其光，和和其始。","東方有兔，小首元尾。","經過吾道，來至吾里。","飲吾泉以醉，登吾榻而寐。","刻乎其壁，奧乎其義。","人誰以辨，其東平子。"]', '["武之在卯，堯王八季。","我棄其寢，我去其扆。","深深然，高高然。","人不吾知，又不吾謂。","由今之後，二百餘祀。","燄燄其光，和和其始。","东方有兔，小首元尾。","經過吾道，来至吾里。","饮吾泉以醉，登吾榻而寐。","刻乎其壁，奧乎其義。","人誰以辨，其东平子。"]', '诗', 'shi', '', NULL, '道者遺記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('64ce5c22-06b8-4955-a399-fc99a74c2e2a', '王璠石銘', '王璠石銘', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["山有石，石有玉。","玉有瑕，即休也。"]', '["山有石，石有玉。","玉有瑕，即休也。"]', '诗', 'shi', '', NULL, '王璠石銘 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dab00c5d-f461-4636-98e8-c1f3320c28a8', '玄元觀棟桁記', '玄元观棟桁記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["山水誰無言，元年有福重修。"]', '["山水誰無言，元年有福重修。"]', '诗', 'shi', '', NULL, '玄元觀棟桁記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('725c1d62-aa54-44f1-8998-e029b46f6138', '天台觀石簡記', '天台观石簡記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["海水竭，台山缺，皇家寶祚無休歇。"]', '["海水竭，台山缺，皇家寶祚無休歇。"]', '诗', 'shi', '', NULL, '天台觀石簡記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd29e453-d8e4-425a-8384-3a81e1c91f9b', '成都羅城北門石記', '成都羅城北门石記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["五五復五五，五五逾重數。","浮世若浮雲，金石一如故。","與君相見時，杳杳非今土。"]', '["五五复五五，五五逾重數。","浮世若浮云，金石一如故。","與君相见时，杳杳非今土。"]', '诗', 'shi', '', NULL, '成都羅城北門石記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f2896c-ad09-41a4-b1f5-f92a1d5c1d84', '青羊宮甎記', '青羊宮甎記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["太平平中元災。"]', '["太平平中元災。"]', '诗', 'shi', '', NULL, '青羊宮甎記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20690d53-7f5a-40cc-95e9-627ef385ba41', '銅雀臺玉板篆', '銅雀台玉板篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["上土巴灰除虛除，伊尹東北八九餘。","秦趙多應分五玉，絲竹木子世世居。","但看六六百中外，世主難留如國如。"]', '["上土巴灰除虛除，伊尹东北八九餘。","秦趙多應分五玉，絲竹木子世世居。","但看六六百中外，世主难留如国如。"]', '诗', 'shi', '', NULL, '銅雀臺玉板篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('21d7ce4c-deef-4aeb-9ee2-c5182d770702', '顯德道宮石記', '显德道宮石記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["瑞雲靈跡鎮梁東，他日多應與古同。","歲月遷移人事改，再來閑處又興功。"]', '["瑞云靈跡鎮梁东，他日多應與古同。","歲月遷移人事改，再来闲处又兴功。"]', '诗', 'shi', '', NULL, '顯德道宮石記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b79cea79-87fe-4b35-ae19-20b02be9ccc5', '南唐昇元殿基下石記', '南唐昇元殿基下石記', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["莫問江南事，江南事可憑。","抱雞升寶位，跨犬出金陵。","子建司南位，安仁秉夜燈。","東鄰嬌小女，騎虎渡河冰。"]', '["莫问江南事，江南事可憑。","抱雞升寶位，跨犬出金陵。","子建司南位，安仁秉夜灯。","东鄰嬌小女，騎虎渡河冰。"]', '诗', 'shi', '', NULL, '南唐昇元殿基下石記 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6541b507-5e32-44e6-bf78-65bd6affe6a2', '馬殷浚城石碣篆', '马殷浚城石碣篆', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["龍舉頭，猳掉尾。","羊爲兄，猴作弟。","羊歸穴，猴離次。"]', '["龙舉头，猳掉尾。","羊爲兄，猴作弟。","羊归穴，猴離次。"]', '诗', 'shi', '', NULL, '馬殷浚城石碣篆 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('140b43a1-d4a5-495d-9c8c-9b1e4bdbe8b9', '王霸仙壇甎刻', '王霸仙壇甎刻', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["樹枯不用伐，壇壞不須結。","未滿一千歲，自有系孫列。","後來是三皇，潮水蕩禍殃。","巖逢二乍間，未免有消亡。","子孫依吾道，代代封閩疆。"]', '["樹枯不用伐，壇壞不須結。","未满一千歲，自有系孫列。","後来是三皇，潮水蕩禍殃。","巖逢二乍间，未免有消亡。","子孫依吾道，代代封閩疆。"]', '诗', 'shi', '', NULL, '王霸仙壇甎刻 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d71dc04-00ad-4e16-a909-cbcf19cfee66', '劉龑石讖', '劉龑石讖', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["人人有一，山山值牛。","兔絲吞骨，蓋海承劉。"]', '["人人有一，山山值牛。","兔絲吞骨，蓋海承劉。"]', '诗', 'shi', '', NULL, '劉龑石讖 不詳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e0bca56-4c6b-41c9-91fd-103b4ea575c6', '南漢羅浮古劒篆文', '南漢羅浮古劒篆文', 'b756b2eb-d092-46b3-8894-9cbd6ceb15be', '唐', '["丁與水同宮，王將耳口同。","尹來居口上，山岫獲重重。"]', '["丁與水同宮，王將耳口同。","尹来居口上，山岫獲重重。"]', '诗', 'shi', '', NULL, '南漢羅浮古劒篆文 不詳 shi');
